fn read_index(state: &AppState) -> Result<Value, String> {
    let text = fs::read_to_string(&state.index_path)
        .map_err(|error| format!("无法读取索引文件 {}：{error}", state.index_path.display()))?;
    serde_json::from_str(&text)
        .map_err(|error| format!("索引 JSON 解析失败 {}：{error}", state.index_path.display()))
}

fn load_codex_session_transcript_for_index(
    state: &AppState,
    thread_id: &str,
) -> Result<CodexTranscript, String> {
    let db_path = codex_db::default_state_db_path();
    match read_index(state) {
        Ok(index) => load_codex_session_transcript_with_catalog(&index, thread_id, &db_path),
        Err(index_error) => load_codex_session_transcript_with_optional_catalog(
            None,
            thread_id,
            &db_path,
            Some(index_error),
        ),
    }
}

fn load_codex_session_transcript_with_catalog(
    index: &Value,
    thread_id: &str,
    db_path: &Path,
) -> Result<CodexTranscript, String> {
    load_codex_session_transcript_with_optional_catalog(Some(index), thread_id, db_path, None)
}

fn load_codex_session_transcript_with_optional_catalog(
    index: Option<&Value>,
    thread_id: &str,
    db_path: &Path,
    index_error: Option<String>,
) -> Result<CodexTranscript, String> {
    match codex_db::read_threads(db_path) {
        Ok(rows) => {
            if let Some(row) = rows.into_iter().find(|row| row.thread_id == thread_id) {
                return load_codex_session_transcript_from_sqlite_row(&row, db_path);
            }
        }
        Err(err) => {
            if let Some(index) = index {
                if let Some(thread) = find_index_thread(index, thread_id) {
                    return load_codex_session_transcript_from_index_thread(
                        index,
                        &thread,
                        "index_fallback_sqlite_unavailable",
                    );
                }
            }
            if let Some(index_error) = index_error {
                return Err(format!(
                    "sqlite_unavailable:{err};index_unavailable:{index_error}"
                ));
            }
            return Err(format!("sqlite_unavailable:{err}"));
        }
    }

    if let Some(index) = index {
        if let Some(thread) = find_index_thread(index, thread_id) {
            return load_codex_session_transcript_from_index_thread(
                index,
                &thread,
                "index_fallback_thread_missing_in_sqlite",
            );
        }
    }

    Err(format!("session_not_found:{thread_id}"))
}

fn load_codex_session_transcript_from_sqlite_row(
    row: &codex_db::CodexThreadRow,
    db_path: &Path,
) -> Result<CodexTranscript, String> {
    let codex_home = db_path
        .parent()
        .ok_or_else(|| "unexpected_internal_error:sqlite_db_path_without_parent".to_string())?;
    let metadata = codex_transcript::TranscriptThreadMetadata {
        thread_id: row.thread_id.clone(),
        rollout_path: row.rollout_path.clone(),
        project_root: row.project_root.clone(),
        title: Some(row.title.clone()),
        created_at_ms: None,
        updated_at_ms: row.updated_at_ms,
        catalog_source: "sqlite".to_string(),
        index_thread_count: None,
    };
    codex_transcript::read_transcript_from_rollout(metadata, codex_home)
}

fn load_codex_session_transcript_from_index_thread(
    index: &Value,
    thread: &SessionRecord,
    catalog_source: &str,
) -> Result<CodexTranscript, String> {
    let codex_home = codex_home_from_index(index)?;
    let metadata = codex_transcript::TranscriptThreadMetadata {
        thread_id: thread.thread_id.clone(),
        rollout_path: thread.rollout_path.clone(),
        project_root: thread.project_root.clone(),
        title: Some(thread.title.clone()),
        created_at_ms: None,
        updated_at_ms: thread.updated_at_ms,
        catalog_source: catalog_source.to_string(),
        index_thread_count: index.get("threads").and_then(Value::as_array).map(Vec::len),
    };
    codex_transcript::read_transcript_from_rollout(metadata, &codex_home)
}

fn codex_home_from_index(index: &Value) -> Result<PathBuf, String> {
    index
        .get("source_stats")
        .and_then(|source_stats| source_stats.get("codex_home"))
        .and_then(|codex_home| codex_home.get("path"))
        .and_then(Value::as_str)
        .filter(|path| !path.trim().is_empty())
        .map(PathBuf::from)
        .ok_or_else(|| "unexpected_internal_error:missing_index_codex_home_path".to_string())
}

fn read_workflow_state_snapshot(path: &Path) -> Result<WorkflowStateSnapshot, String> {
    if !path.exists() {
        return Ok(empty_workflow_state_snapshot(
            path,
            vec!["状态文件不存在；不会自动创建。".to_string()],
        ));
    }

    let text = fs::read_to_string(path)
        .map_err(|error| format!("无法读取工作流状态文件 {}：{error}", path.display()))?;
    let value: Value = serde_json::from_str(&text)
        .map_err(|error| format!("工作流状态 JSON 解析失败 {}：{error}", path.display()))?;
    let mut warnings = validate_workflow_state(&value);

    let project_workflows = project_workflow_summaries(&value);
    let project_blackboards = project_blackboards_from_workflows(&project_workflows);

    Ok(WorkflowStateSnapshot {
        exists: true,
        path: path.display().to_string(),
        schema_version: optional_string_from(&value, "schema_version"),
        workflow_version: i64_value(&value, "workflow_version"),
        workspace_id: optional_string_from(&value, "workspace_id"),
        updated_at: optional_string_from(&value, "updated_at"),
        initialized: warnings.is_empty(),
        counts: workflow_state_counts(&value),
        project_workflows,
        project_blackboards,
        warnings: {
            if warnings.is_empty() {
                warnings.push("状态文件已读取；只展示元数据，不展示正文。".to_string());
            }
            warnings
        },
    })
}

fn initialize_workflow_state_at(path: &Path) -> Result<WorkflowStateMutationResult, String> {
    let existed = path.exists();
    let timestamp = unix_timestamp_string();
    let audit_event_id = format!("audit:init:{timestamp}");
    let parent = path
        .parent()
        .ok_or_else(|| format!("状态文件路径没有父目录：{}", path.display()))?;
    fs::create_dir_all(parent)
        .map_err(|error| format!("创建状态目录失败 {}：{error}", parent.display()))?;

    let backup_path = if existed {
        let backups_dir = parent.join("backups");
        fs::create_dir_all(&backups_dir)
            .map_err(|error| format!("创建备份目录失败 {}：{error}", backups_dir.display()))?;
        let backup = backups_dir.join(format!("workflow-state.v0.{timestamp}.json"));
        fs::copy(path, &backup)
            .map_err(|error| format!("备份旧状态文件失败 {}：{error}", backup.display()))?;
        Some(backup)
    } else {
        None
    };

    let value = initial_workflow_state_json(&timestamp, &audit_event_id, existed, path);
    let validation_warnings = validate_workflow_state(&value);
    if !validation_warnings.is_empty() {
        return Err(format!(
            "初始化状态未通过 schema 校验：{}",
            validation_warnings.join(", ")
        ));
    }

    atomic_write_json(path, &value)?;
    let snapshot = read_workflow_state_snapshot(path)?;
    if !snapshot.exists
        || snapshot.schema_version.as_deref() != Some("workflow_state_v0")
        || snapshot.workflow_version != Some(1)
    {
        return Err("初始化后重新读取校验失败".to_string());
    }

    Ok(WorkflowStateMutationResult {
        message: if existed {
            "已在用户确认后初始化工作流事实层；旧状态文件已先备份。".to_string()
        } else {
            "已在用户确认后首次初始化工作流事实层；此前无旧状态文件可备份。".to_string()
        },
        path: path.display().to_string(),
        backup_path: backup_path.map(|backup| backup.display().to_string()),
        audit_event_id,
        first_initialize: !existed,
        snapshot,
    })
}

fn bootstrap_project_workflow_at(
    path: &Path,
    project: &ProjectRecord,
) -> Result<WorkflowStateMutationResult, String> {
    let existed = path.exists();
    let timestamp = unix_timestamp_string();
    let audit_event_id = format!(
        "audit:bootstrap:{}:{timestamp}",
        stable_id(&project.project_root)
    );
    let parent = path
        .parent()
        .ok_or_else(|| format!("状态文件路径没有父目录：{}", path.display()))?;
    fs::create_dir_all(parent)
        .map_err(|error| format!("创建状态目录失败 {}：{error}", parent.display()))?;

    let backup_path = if existed {
        let backups_dir = parent.join("backups");
        fs::create_dir_all(&backups_dir)
            .map_err(|error| format!("创建备份目录失败 {}：{error}", backups_dir.display()))?;
        let backup = backups_dir.join(format!("workflow-state.v0.{timestamp}.json"));
        fs::copy(path, &backup)
            .map_err(|error| format!("备份旧状态文件失败 {}：{error}", backup.display()))?;
        Some(backup)
    } else {
        None
    };

    let mut value = if existed {
        let text = fs::read_to_string(path)
            .map_err(|error| format!("无法读取工作流状态文件 {}：{error}", path.display()))?;
        serde_json::from_str(&text)
            .map_err(|error| format!("工作流状态 JSON 解析失败 {}：{error}", path.display()))?
    } else {
        initial_workflow_state_json(&timestamp, &format!("audit:init:{timestamp}"), false, path)
    };

    let validation_warnings = validate_workflow_state(&value);
    if !validation_warnings.is_empty() {
        return Err(format!(
            "当前状态文件未通过 schema 校验：{}",
            validation_warnings.join(", ")
        ));
    }

    let workflow_id = default_workflow_id(&project.project_root);
    if workflow_exists(&value, &workflow_id) {
        let snapshot = read_workflow_state_snapshot(path)?;
        return Ok(WorkflowStateMutationResult {
            message: format!("该项目已有默认工作流草稿，未重复创建：{}", project.name),
            path: path.display().to_string(),
            backup_path: None,
            audit_event_id: "no-op:existing-workflow".to_string(),
            first_initialize: !existed,
            snapshot,
        });
    }

    append_default_project_workflow(&mut value, project, &timestamp, &audit_event_id)?;
    let validation_warnings = validate_workflow_state(&value);
    if !validation_warnings.is_empty() {
        return Err(format!(
            "写入前 schema 校验失败：{}",
            validation_warnings.join(", ")
        ));
    }

    atomic_write_json(path, &value)?;
    let snapshot = read_workflow_state_snapshot(path)?;
    if !snapshot.exists
        || snapshot.counts.workflows == 0
        || snapshot.counts.nodes < 7
        || snapshot.counts.edges < 6
    {
        return Err("创建项目默认工作流后重新读取校验失败".to_string());
    }

    Ok(WorkflowStateMutationResult {
        message: format!("已创建项目默认工作流草稿：{}", project.name),
        path: path.display().to_string(),
        backup_path: backup_path.map(|backup| backup.display().to_string()),
        audit_event_id,
        first_initialize: !existed,
        snapshot,
    })
}

fn append_default_project_workflow(
    value: &mut Value,
    project: &ProjectRecord,
    timestamp: &str,
    audit_event_id: &str,
) -> Result<(), String> {
    let project_id = project_id(&project.project_root);
    let workflow_id = default_workflow_id(&project.project_root);
    let project_ref = project.project_root.clone();

    if !project_exists(value, &project_id) {
        array_mut(value, "projects")?.push(json!({
          "project_id": project_id,
          "display_name": project.name,
          "root_path": project.project_root,
          "source_kind": "codex_index",
          "permission_level": "read_only",
          "created_at": timestamp,
          "updated_at": timestamp,
          "warnings": project.warnings
        }));
    }

    array_mut(value, "workflows")?.push(json!({
      "workflow_id": workflow_id,
      "workflow_version": 1,
      "project_id": project_id,
      "title": format!("{} 默认工作流草稿", project.name),
      "state": "draft",
      "source_kind": "workspace_state",
      "permission_level": "user_confirmed_write",
      "model_policy": "none",
      "created_at": timestamp,
      "updated_at": timestamp
    }));

    let nodes = [
        (
            "director",
            "director",
            "总指导 / Director",
            "role:director",
            None,
        ),
        (
            "codex-dev",
            "actor",
            "Codex 开发线",
            "adapter:codex-local",
            Some("codex"),
        ),
        ("validation", "validation", "验证线", "role:tester", None),
        ("task", "task", "任务包", "artifact:task-package", None),
        ("handoff", "artifact", "Handoff", "artifact:handoff", None),
        (
            "evidence",
            "artifact",
            "Evidence",
            "artifact:evidence",
            None,
        ),
        ("review", "review", "Review", "artifact:review", None),
    ];
    for (index, (suffix, node_type, title, source_ref, agent_type)) in nodes.iter().enumerate() {
        array_mut(value, "nodes")?.push(json!({
      "node_id": format!("{workflow_id}:node:{suffix}"),
      "workflow_id": workflow_id,
      "node_type": node_type,
      "title": title,
      "state": "draft",
      "source_kind": if *suffix == "codex-dev" { "workspace_state" } else { "derived" },
      "source_ref": source_ref,
      "agent_type": agent_type,
      "adapter_id": if *suffix == "codex-dev" { Value::String("codex-local".to_string()) } else { Value::Null },
      "artifact_type": if ["task", "handoff", "evidence", "review"].contains(suffix) { Value::String((*suffix).to_string()) } else { Value::Null },
      "permission_level": "user_confirmed_write",
      "position": {
        "x": 120 + (index as i64 % 4) * 220,
        "y": 120 + (index as i64 / 4) * 180
      },
      "warnings": []
    }));
    }

    let edges = [
        ("assigns_task", "director", "task", "decomposes_to"),
        ("assigned_to_codex", "task", "codex-dev", "assigned_to"),
        ("produces_handoff", "codex-dev", "handoff", "produces"),
        ("produces_evidence", "codex-dev", "evidence", "produces"),
        ("validates_artifacts", "validation", "evidence", "validates"),
        ("reviews_handoff", "review", "handoff", "reviews"),
    ];
    for (suffix, from, to, edge_type) in edges {
        array_mut(value, "edges")?.push(json!({
          "edge_id": format!("{workflow_id}:edge:{suffix}"),
          "workflow_id": workflow_id,
          "from_node_id": format!("{workflow_id}:node:{from}"),
          "to_node_id": format!("{workflow_id}:node:{to}"),
          "edge_type": edge_type,
          "state": "draft",
          "source_kind": "derived",
          "permission_level": "user_confirmed_write",
          "created_at": timestamp,
          "updated_at": timestamp,
          "warnings": []
        }));
    }

    array_mut(value, "audit_events")?.push(json!({
      "event_id": audit_event_id,
      "event_type": "project_default_workflow_bootstrapped",
      "target_ref": workflow_id,
      "actor_ref": "user_confirmed_desktop_shell",
      "source_kind": "workspace_state",
      "permission_level": "user_confirmed_write",
      "before_state": "missing_project_workflow",
      "after_state": "draft",
      "created_at": timestamp,
      "reason": format!("用户确认给索引内项目创建默认工作流草稿：{project_ref}")
    }));

    value["updated_at"] = Value::String(timestamp.to_string());
    Ok(())
}

fn create_task_draft_at(
    path: &Path,
    request: &TaskDraftRequest,
) -> Result<WorkflowStateMutationResult, String> {
    if request.title.trim().is_empty() {
        return Err("任务包草稿标题不能为空".to_string());
    }
    if request.objective.trim().is_empty() {
        return Err("任务包草稿目标说明不能为空".to_string());
    }
    if !path.exists() {
        return Err("工作流状态文件不存在；请先初始化并创建项目默认工作流草稿".to_string());
    }

    let timestamp = unix_timestamp_string();
    let mut value = read_workflow_state_value(path)?;
    let validation_warnings = validate_workflow_state(&value);
    if !validation_warnings.is_empty() {
        return Err(format!(
            "当前状态文件未通过 schema 校验：{}",
            validation_warnings.join(", ")
        ));
    }

    let workflow_id = default_workflow_id(&request.project_root);
    if !workflow_exists(&value, &workflow_id) {
        return Err("当前项目还没有本地 workflow；请先创建默认工作流草稿".to_string());
    }

    let normalized_title = request.title.trim();
    if task_draft_exists(&value, &workflow_id, normalized_title) {
        let snapshot = read_workflow_state_snapshot(path)?;
        return Ok(WorkflowStateMutationResult {
            message: format!("同名任务包草稿已存在，未重复创建：{normalized_title}"),
            path: path.display().to_string(),
            backup_path: None,
            audit_event_id: "no-op:existing-task-draft".to_string(),
            first_initialize: false,
            snapshot,
        });
    }

    let parent = path
        .parent()
        .ok_or_else(|| format!("状态文件路径没有父目录：{}", path.display()))?;
    let backups_dir = parent.join("backups");
    fs::create_dir_all(&backups_dir)
        .map_err(|error| format!("创建备份目录失败 {}：{error}", backups_dir.display()))?;
    let backup = backups_dir.join(format!("workflow-state.v0.{timestamp}.json"));
    fs::copy(path, &backup)
        .map_err(|error| format!("备份旧状态文件失败 {}：{error}", backup.display()))?;

    let assigned_role = request.assigned_role.as_deref().unwrap_or("codex-dev");
    let work_item_id = format!("work-item:{workflow_id}:{timestamp}");
    let artifact_id = format!("artifact:{workflow_id}:task-package:{timestamp}");
    let audit_event_id = format!(
        "audit:task-draft:{}:{timestamp}",
        stable_id(normalized_title)
    );

    array_mut(&mut value, "work_items")?.push(json!({
      "work_item_id": work_item_id,
      "project_id": project_id(&request.project_root),
      "workflow_id": workflow_id,
      "title": normalized_title,
      "state": "draft",
      "source_kind": "workspace_state",
      "source_ref": artifact_id,
      "assigned_role_id": assigned_role,
      "current_node_id": workflow_node_for_work_item_state(&workflow_id, "draft"),
      "agent_type": "codex",
      "adapter_id": "codex-local",
      "permission_level": "user_confirmed_write",
      "created_at": timestamp,
      "updated_at": timestamp
    }));

    array_mut(&mut value, "artifacts")?.push(json!({
      "artifact_id": artifact_id,
      "artifact_type": "task_package",
      "project_id": project_id(&request.project_root),
      "path": Value::Null,
      "title": normalized_title,
      "brief": request.objective.trim(),
      "source_kind": "workspace_state",
      "source_ref": work_item_id,
      "permission_level": "user_confirmed_write",
      "version": 1,
      "stale": true,
      "stale_reasons": ["任务包仍是草稿，必须补齐字段、检查并生成可派发版本。"],
      "created_at": timestamp,
      "updated_at": timestamp,
      "warnings": ["draft_only_no_markdown_file"]
    }));

    let task_node_before_state = update_task_node_state(&mut value, &workflow_id, &timestamp)?;

    array_mut(&mut value, "audit_events")?.push(json!({
      "event_id": audit_event_id,
      "event_type": "task_draft_created",
      "target_ref": work_item_id,
      "actor_ref": "user_confirmed_desktop_shell",
      "source_kind": "workspace_state",
      "permission_level": "user_confirmed_write",
      "before_state": "missing_task_draft",
      "after_state": "draft",
      "created_at": timestamp,
      "reason": format!("用户确认登记任务包草稿：{normalized_title}")
    }));

    if let Some(before_state) = task_node_before_state {
        array_mut(&mut value, "audit_events")?.push(json!({
          "event_id": format!("audit:task-node-draft:{}:{timestamp}", stable_id(normalized_title)),
          "event_type": "task_node_state_updated",
          "target_ref": format!("{workflow_id}:node:task"),
          "actor_ref": "user_confirmed_desktop_shell",
          "source_kind": "workspace_state",
          "permission_level": "user_confirmed_write",
          "before_state": before_state,
          "after_state": "draft",
          "created_at": timestamp,
          "reason": format!("登记任务包草稿时同步任务包节点状态：{normalized_title}")
        }));
    }

    value["updated_at"] = Value::String(timestamp.to_string());
    let validation_warnings = validate_workflow_state(&value);
    if !validation_warnings.is_empty() {
        return Err(format!(
            "写入前 schema 校验失败：{}",
            validation_warnings.join(", ")
        ));
    }

    atomic_write_json(path, &value)?;
    let snapshot = read_workflow_state_snapshot(path)?;
    if snapshot.counts.work_items == 0 || snapshot.counts.artifacts == 0 {
        return Err("登记任务包草稿后重新读取校验失败".to_string());
    }

    Ok(WorkflowStateMutationResult {
        message: format!("已登记任务包草稿：{normalized_title}"),
        path: path.display().to_string(),
        backup_path: Some(backup.display().to_string()),
        audit_event_id,
        first_initialize: false,
        snapshot,
    })
}

fn render_task_package_preview_at(
    path: &Path,
    project: &ProjectRecord,
    request: &TaskPackagePreviewRequest,
) -> Result<TaskPackagePreview, String> {
    if !path.exists() {
        return Err("工作流状态文件不存在；无法渲染任务包预览".to_string());
    }

    let value = read_workflow_state_value(path)?;
    let validation_warnings = validate_workflow_state(&value);
    if !validation_warnings.is_empty() {
        return Err(format!(
            "当前状态文件未通过 schema 校验：{}",
            validation_warnings.join(", ")
        ));
    }

    let workflow_id = default_workflow_id(&request.project_root);
    if !workflow_exists(&value, &workflow_id) {
        return Err("当前项目还没有本地 workflow；无法渲染任务包预览".to_string());
    }

    let work_item = find_work_item(&value, &workflow_id, &request.work_item_id)
        .ok_or_else(|| "当前 workflow 下找不到该 work item；无法渲染任务包预览".to_string())?;
    let artifact = find_task_package_artifact(&value, &request.work_item_id, &work_item)
        .ok_or_else(|| {
            "当前 work item 找不到 task_package artifact；无法渲染任务包预览".to_string()
        })?;

    let fields = task_package_fields_from(
        work_item,
        artifact,
        project,
        &workflow_id,
        &request.work_item_id,
    );
    let artifact_id = optional_string_from(artifact, "artifact_id");
    let warnings = preview_warnings(work_item, artifact);
    let memory_snapshot = task_memory_injection::snapshot_from_artifact(artifact);
    let memory_injection_summary = memory_snapshot
        .as_ref()
        .map(|snapshot| task_memory_injection::summary_from_snapshot(snapshot, vec![]))
        .unwrap_or_else(task_memory_injection::missing_summary);
    let markdown =
        render_task_package_markdown(&fields, artifact_id.as_deref(), memory_snapshot.as_ref());

    Ok(TaskPackagePreview {
        project_root: request.project_root.clone(),
        workflow_id,
        work_item_id: request.work_item_id.clone(),
        artifact_id,
        markdown,
        memory_injection_summary,
        warnings,
    })
}

fn update_task_package_draft_fields_at(
    path: &Path,
    request: &TaskPackageFieldsUpdateRequest,
) -> Result<WorkflowStateMutationResult, String> {
    update_task_package_fields_at(path, request, TaskPackageFieldWriteMode::DraftUpdate)
}

enum TaskPackageFieldWriteMode {
    DraftUpdate,
    DispatchCorrection,
}

fn update_task_package_fields_at(
    path: &Path,
    request: &TaskPackageFieldsUpdateRequest,
    mode: TaskPackageFieldWriteMode,
) -> Result<WorkflowStateMutationResult, String> {
    if !path.exists() {
        return Err("工作流状态文件不存在；无法更新任务包字段".to_string());
    }

    let timestamp = unix_timestamp_string();
    let mut value = read_workflow_state_value(path)?;
    let validation_warnings = validate_workflow_state(&value);
    if !validation_warnings.is_empty() {
        return Err(format!(
            "当前状态文件未通过 schema 校验：{}",
            validation_warnings.join(", ")
        ));
    }

    let workflow_id = default_workflow_id(&request.project_root);
    if !workflow_exists(&value, &workflow_id) {
        return Err("当前项目还没有本地 workflow；无法更新任务包字段".to_string());
    }

    let work_item_index = find_work_item_index(&value, &workflow_id, &request.work_item_id)
        .ok_or_else(|| "当前 workflow 下找不到该 work item；无法更新任务包字段".to_string())?;
    let current_state = value
        .get("work_items")
        .and_then(Value::as_array)
        .and_then(|items| items.get(work_item_index))
        .and_then(|item| optional_string_from(item, "state"))
        .unwrap_or_else(|| "draft".to_string());
    let artifact_index =
        find_task_package_artifact_index(&value, &request.work_item_id, work_item_index)
            .ok_or_else(|| {
                "当前 work item 找不到 task_package artifact；无法更新任务包字段".to_string()
            })?;

    let parent = path
        .parent()
        .ok_or_else(|| format!("状态文件路径没有父目录：{}", path.display()))?;
    let backups_dir = parent.join("backups");
    fs::create_dir_all(&backups_dir)
        .map_err(|error| format!("创建备份目录失败 {}：{error}", backups_dir.display()))?;
    let backup = backups_dir.join(format!("workflow-state.v0.{timestamp}.json"));
    fs::copy(path, &backup)
        .map_err(|error| format!("备份旧状态文件失败 {}：{error}", backup.display()))?;

    let task_name = cleaned_scalar(&request.fields.task_name);
    let assigned_line = cleaned_scalar(&request.fields.assigned_line);
    let title_for_work_item = if task_name.is_empty() {
        "待补充".to_string()
    } else {
        task_name.clone()
    };
    let assigned_role_id = assigned_line_id(&assigned_line);

    let work_items = array_mut(&mut value, "work_items")?;
    let work_item = work_items
        .get_mut(work_item_index)
        .ok_or_else(|| "当前 workflow 下找不到该 work item；无法更新任务包字段".to_string())?;
    work_item["title"] = Value::String(title_for_work_item.clone());
    work_item["assigned_role_id"] = Value::String(assigned_role_id.to_string());
    work_item["current_node_id"] = Value::String(workflow_node_for_work_item_state(
        &workflow_id,
        &current_state,
    ));
    work_item["updated_at"] = Value::String(timestamp.clone());

    let artifacts = array_mut(&mut value, "artifacts")?;
    let artifact = artifacts.get_mut(artifact_index).ok_or_else(|| {
        "当前 work item 找不到 task_package artifact；无法更新任务包字段".to_string()
    })?;
    artifact["title"] = Value::String(title_for_work_item);
    artifact["brief"] = Value::String(join_lines(&request.fields.goals));
    artifact["task_name"] = Value::String(task_name);
    artifact["assigned_line"] = Value::String(assigned_line);
    artifact["background"] = string_vec_value(&request.fields.background);
    artifact["goals"] = string_vec_value(&request.fields.goals);
    artifact["allowed_read"] = string_vec_value(&request.fields.allowed_read);
    artifact["allowed_write"] = string_vec_value(&request.fields.allowed_write);
    artifact["forbidden_actions"] = string_vec_value(&request.fields.forbidden_actions);
    artifact["acceptance_criteria"] = string_vec_value(&request.fields.acceptance_criteria);
    artifact["required_return"] = string_vec_value(&request.fields.required_return);
    artifact["review_focus"] = string_vec_value(&request.fields.review_focus);
    artifact["template_version"] = Value::String("task_package_v1".to_string());
    artifact["version"] = Value::Number((i64_value(artifact, "version").unwrap_or(0) + 1).into());
    artifact["stale"] = Value::Bool(true);
    artifact["stale_reasons"] = string_vec_value(&vec![
        "任务包字段已编辑，必须重新运行检查并生成新版本。".to_string(),
    ]);
    if matches!(mode, TaskPackageFieldWriteMode::DraftUpdate) {
        artifact["path"] = Value::Null;
    }
    artifact["updated_at"] = Value::String(timestamp.clone());
    artifact["warnings"] = string_vec_value(&field_warning_strings(&request.fields));

    let (audit_prefix, event_type, reason, message) = match mode {
        TaskPackageFieldWriteMode::DraftUpdate => (
            "task-fields",
            "task_package_fields_updated",
            "用户确认更新任务包草稿结构化字段",
            "已更新任务包草稿结构化字段。",
        ),
        TaskPackageFieldWriteMode::DispatchCorrection => (
            "task-fields-correction",
            "task_package_fields_corrected_for_dispatch",
            "用户确认修正任务包派发字段；没有生成真实任务包文件",
            "已保存任务包派发字段修正；没有生成真实任务包文件。",
        ),
    };
    let audit_event_id = format!(
        "audit:{audit_prefix}:{}:{timestamp}",
        stable_id(&request.work_item_id)
    );
    array_mut(&mut value, "audit_events")?.push(json!({
      "event_id": audit_event_id,
      "event_type": event_type,
      "target_ref": request.work_item_id,
      "actor_ref": "user_confirmed_desktop_shell",
      "source_kind": "workspace_state",
      "permission_level": "user_confirmed_write",
      "before_state": "draft",
      "after_state": "draft",
      "created_at": timestamp,
      "reason": reason
    }));

    value["updated_at"] = Value::String(timestamp);
    let validation_warnings = validate_workflow_state(&value);
    if !validation_warnings.is_empty() {
        return Err(format!(
            "写入前 schema 校验失败：{}",
            validation_warnings.join(", ")
        ));
    }

    atomic_write_json(path, &value)?;
    let snapshot = read_workflow_state_snapshot(path)?;
    if !snapshot.exists {
        return Err("更新任务包字段后重新读取校验失败".to_string());
    }

    Ok(WorkflowStateMutationResult {
        message: message.to_string(),
        path: path.display().to_string(),
        backup_path: Some(backup.display().to_string()),
        audit_event_id,
        first_initialize: false,
        snapshot,
    })
}

fn generate_task_package_file_at(
    path: &Path,
    project: &ProjectRecord,
    request: &TaskPackageFileGenerationRequest,
    tasks_dir: &Path,
) -> Result<TaskPackageFileGenerationResult, String> {
    if !path.exists() {
        return Err("工作流状态文件不存在；无法生成真实任务包文件".to_string());
    }

    let timestamp = unix_timestamp_string();
    let mut value = read_workflow_state_value(path)?;
    let validation_warnings = validate_workflow_state(&value);
    if !validation_warnings.is_empty() {
        return Err(format!(
            "当前状态文件未通过 schema 校验：{}",
            validation_warnings.join(", ")
        ));
    }

    let workflow_id = default_workflow_id(&request.project_root);
    if !workflow_exists(&value, &workflow_id) {
        return Err("当前项目还没有本地 workflow；无法生成真实任务包文件".to_string());
    }

    let work_item_index = find_work_item_index(&value, &workflow_id, &request.work_item_id)
        .ok_or_else(|| "当前 workflow 下找不到该 work item；无法生成真实任务包文件".to_string())?;
    let artifact_index =
        find_task_package_artifact_index(&value, &request.work_item_id, work_item_index)
            .ok_or_else(|| {
                "当前 work item 找不到 task_package artifact；无法生成真实任务包文件".to_string()
            })?;

    let work_item = value
        .get("work_items")
        .and_then(Value::as_array)
        .and_then(|items| items.get(work_item_index))
        .ok_or_else(|| "当前 workflow 下找不到该 work item；无法生成真实任务包文件".to_string())?;
    let artifact = value
        .get("artifacts")
        .and_then(Value::as_array)
        .and_then(|artifacts| artifacts.get(artifact_index))
        .ok_or_else(|| {
            "当前 work item 找不到 task_package artifact；无法生成真实任务包文件".to_string()
        })?;

    let fields = task_package_fields_from(
        work_item,
        artifact,
        project,
        &workflow_id,
        &request.work_item_id,
    );
    let artifact_id = optional_string_from(artifact, "artifact_id");
    let memory_input = task_memory_packet_input_from_task_package(
        &request.project_root,
        &workflow_id,
        &request.work_item_id,
        work_item,
        artifact,
        &fields,
    );
    let memory_output = preview_task_memory_packet_at(path, &memory_input, &timestamp)?;
    let memory_snapshot = task_memory_injection::snapshot_from_build_output(
        &memory_output,
        &request.work_item_id,
        artifact_id.as_deref(),
        &timestamp,
    )?;
    let memory_injection_summary =
        task_memory_injection::summary_from_snapshot(&memory_snapshot, vec![]);
    let markdown =
        render_task_package_markdown(&fields, artifact_id.as_deref(), Some(&memory_snapshot));
    validate_generated_task_package_markdown(&markdown)?;

    fs::create_dir_all(tasks_dir)
        .map_err(|error| format!("创建任务包目录失败 {}：{error}", tasks_dir.display()))?;
    let (file_path, file_already_matched) = next_task_package_path_or_existing_match(
        tasks_dir,
        &fields.task_name,
        &request.work_item_id,
        &markdown,
    )?;

    let parent = path
        .parent()
        .ok_or_else(|| format!("状态文件路径没有父目录：{}", path.display()))?;
    let backups_dir = parent.join("backups");
    fs::create_dir_all(&backups_dir)
        .map_err(|error| format!("创建备份目录失败 {}：{error}", backups_dir.display()))?;
    let backup = backups_dir.join(format!("workflow-state.v0.{timestamp}.json"));
    fs::copy(path, &backup)
        .map_err(|error| format!("备份旧状态文件失败 {}：{error}", backup.display()))?;

    if !file_already_matched {
        atomic_write_new_text_file(&file_path, &markdown)?;
    }

    let written = fs::read_to_string(&file_path)
        .map_err(|error| format!("重新读取生成任务包失败 {}：{error}", file_path.display()))?;
    if written != markdown {
        return Err("生成任务包后重新读取校验失败：文件内容不一致".to_string());
    }
    validate_generated_task_package_markdown(&written)?;

    let audit_event_id = format!(
        "audit:task-file:{}:{timestamp}",
        stable_id(&request.work_item_id)
    );
    {
        let artifacts = array_mut(&mut value, "artifacts")?;
        let artifact = artifacts.get_mut(artifact_index).ok_or_else(|| {
            "当前 work item 找不到 task_package artifact；无法生成真实任务包文件".to_string()
        })?;
        artifact["path"] = Value::String(file_path.display().to_string());
        artifact["last_generated_fingerprint"] = Value::String(task_package_fingerprint(&fields));
        task_memory_injection::write_snapshot_to_artifact(artifact, &memory_snapshot)?;
        artifact["stale"] = Value::Bool(false);
        artifact["stale_reasons"] = Value::Array(vec![]);
        artifact["updated_at"] = Value::String(timestamp.clone());
        let warnings = string_array(artifact, "warnings")
            .into_iter()
            .filter(|warning| warning != "draft_only_no_markdown_file")
            .collect::<Vec<_>>();
        artifact["warnings"] = string_vec_value(&warnings);
    }
    array_mut(&mut value, "audit_events")?.push(json!({
      "event_id": audit_event_id,
      "event_type": "task_package_file_generated",
      "target_ref": request.work_item_id,
      "actor_ref": "user_confirmed_desktop_shell",
      "source_kind": "workspace_state",
      "permission_level": "user_confirmed_write",
      "before_state": "draft",
      "after_state": "draft",
      "created_at": timestamp,
      "reason": format!("用户确认从选中任务草稿生成真实任务包文件：{}", file_path.display())
    }));
    let memory_audit_event_id = format!(
        "audit:task-memory-injection:{}:{timestamp}",
        stable_id(&request.work_item_id)
    );
    array_mut(&mut value, "audit_events")?.push(json!({
      "event_id": memory_audit_event_id,
      "event_type": "task_memory_packet_injected_into_task_package",
      "target_ref": request.work_item_id,
      "actor_ref": "user_confirmed_desktop_shell",
      "source_kind": "workspace_state",
      "permission_level": "user_confirmed_write",
      "before_state": "task_package_without_memory_packet_snapshot",
      "after_state": "task_package_with_memory_packet_snapshot",
      "created_at": timestamp,
      "reason": task_memory_injection::audit_reason(&memory_snapshot)
    }));
    value["updated_at"] = Value::String(timestamp);

    let validation_warnings = validate_workflow_state(&value);
    if !validation_warnings.is_empty() {
        return Err(format!(
            "写入前 schema 校验失败：{}",
            validation_warnings.join(", ")
        ));
    }

    atomic_write_json(path, &value)?;
    let snapshot = read_workflow_state_snapshot(path)?;
    let updated = read_workflow_state_value(path)?;
    let updated_artifact = updated
        .get("artifacts")
        .and_then(Value::as_array)
        .and_then(|artifacts| artifacts.get(artifact_index))
        .ok_or_else(|| "生成任务包后状态快照校验失败：artifact 缺失".to_string())?;
    if optional_string_from(updated_artifact, "path").as_deref()
        != Some(file_path.display().to_string().as_str())
    {
        return Err("生成任务包后状态快照校验失败：artifact path 未更新".to_string());
    }

    Ok(TaskPackageFileGenerationResult {
        message: format!("已生成真实任务包文件：{}", file_path.display()),
        file_path: file_path.display().to_string(),
        workflow_state_path: path.display().to_string(),
        backup_path: backup.display().to_string(),
        audit_event_id,
        memory_injection_summary,
        snapshot,
    })
}

fn inspect_task_package_dispatch_readiness_at(
    path: &Path,
    project: &ProjectRecord,
    request: &TaskPackageDispatchReadinessRequest,
) -> Result<TaskPackageDispatchReadiness, String> {
    if !path.exists() {
        return Err("工作流状态文件不存在；无法检查任务包派发准备状态".to_string());
    }

    let value = read_workflow_state_value(path)?;
    let validation_warnings = validate_workflow_state(&value);
    if !validation_warnings.is_empty() {
        return Err(format!(
            "当前状态文件未通过 schema 校验：{}",
            validation_warnings.join(", ")
        ));
    }

    let workflow_id = default_workflow_id(&request.project_root);
    if !workflow_exists(&value, &workflow_id) {
        return Err("当前项目还没有本地 workflow；无法检查任务包派发准备状态".to_string());
    }

    let work_item =
        find_work_item(&value, &workflow_id, &request.work_item_id).ok_or_else(|| {
            "当前 workflow 下找不到该 work item；无法检查任务包派发准备状态".to_string()
        })?;
    let artifact = find_task_package_artifact(&value, &request.work_item_id, work_item)
        .ok_or_else(|| {
            "当前 work item 找不到 task_package artifact；无法检查任务包派发准备状态".to_string()
        })?;

    let fields = task_package_fields_from(
        work_item,
        artifact,
        project,
        &workflow_id,
        &request.work_item_id,
    );
    let artifact_path = optional_string_from(artifact, "path");
    let artifact_id = optional_string_from(artifact, "artifact_id");
    let mut blocking_reasons = dispatch_blocking_reasons(&fields, artifact_path.as_deref());
    let memory_injection_summary =
        task_memory_injection::summary_from_artifact_with_current_revisions(
            path,
            artifact,
            &unix_timestamp_string(),
        )?;
    let authorization_check = inspect_task_package_authorization_at(
        path,
        project,
        &workflow_id,
        work_item,
        artifact,
        &fields,
        "inspect_only",
    )?;
    if authorization_check.status != "authorized" {
        blocking_reasons.extend(authorization_check.reasons.clone());
    }
    let mut warnings = dispatch_warning_reasons(artifact, artifact_path.as_deref());
    warnings.extend(
        memory_injection_summary
            .warnings
            .iter()
            .map(|warning| format!("memory packet: {warning}")),
    );
    warnings.extend(
        memory_injection_summary
            .stale_reasons
            .iter()
            .map(|reason| format!("memory packet stale: {reason}")),
    );
    if bool_value(artifact, "stale") {
        blocking_reasons.push("任务包已 stale；派发前必须重新检查并生成新版本。".to_string());
    }
    if memory_injection_summary.stale && memory_injection_summary.snapshot_id.is_some() {
        blocking_reasons.push("任务包记忆快照已 stale；派发前必须重新生成任务包。".to_string());
    }
    if optional_string_from(artifact, "model_id").is_none() {
        blocking_reasons.push("缺模型；系统不会自动选择模型。".to_string());
    }
    if string_array(artifact, "required_return").is_empty() {
        blocking_reasons.push("缺 report format；必须回传格式未登记。".to_string());
    }
    if bool_value(artifact, "requires_harness")
        && string_array(artifact, "harness_requirements").is_empty()
    {
        blocking_reasons.push("节点要求 harness 但没有配置。".to_string());
    }
    if bool_value(artifact, "requires_tools")
        && string_array(artifact, "callable_tool_capabilities").is_empty()
    {
        blocking_reasons.push("节点需要工具但没有工具白名单。".to_string());
    }
    if bool_value(artifact, "requires_knowledge_refs")
        && string_array(artifact, "available_knowledge_refs").is_empty()
    {
        blocking_reasons.push("任务包声明需要知识库引用，但没有显式引用。".to_string());
    }
    if bool_value(artifact, "requires_memory_refs")
        && string_array(artifact, "available_memory_refs").is_empty()
    {
        blocking_reasons.push("任务包声明需要记忆作为依据，但没有确认记忆引用。".to_string());
    }
    if bool_value(artifact, "requires_memory_refs")
        && memory_injection_summary.snapshot_id.is_none()
    {
        blocking_reasons.push("任务包声明需要记忆作为依据，但记忆快照缺失。".to_string());
    }
    if bool_value(artifact, "requires_memory_refs")
        && memory_injection_summary.snapshot_id.is_some()
        && memory_injection_summary.included_count == 0
    {
        blocking_reasons
            .push("任务包声明需要记忆作为依据，但快照 included 正式记忆为空。".to_string());
    }
    let status = if optional_string_from(artifact, "dispatch_readiness_status").as_deref()
        == Some("blocked")
    {
        "blocked".to_string()
    } else if blocking_reasons.is_empty() {
        "ready".to_string()
    } else {
        "not_ready".to_string()
    };
    if status == "blocked" && blocking_reasons.is_empty() {
        blocking_reasons.push("任务包已被显式标记为 blocked。".to_string());
    }

    Ok(TaskPackageDispatchReadiness {
        project_root: request.project_root.clone(),
        workflow_id,
        work_item_id: request.work_item_id.clone(),
        artifact_id,
        artifact_path,
        status: status.clone(),
        blocking_reasons,
        warnings,
        can_generate_next_version: status == "ready",
        memory_injection_summary,
        authorization_check: Some(authorization_check),
    })
}

fn inspect_workflow_run_check_at(
    path: &Path,
    project: &ProjectRecord,
    request: &WorkflowRunCheckRequest,
) -> Result<WorkflowRunCheck, String> {
    if !path.exists() {
        return Ok(blocked_workflow_run_check(
            &project.project_root,
            request.workflow_id.as_deref(),
            "missing_workflow",
            "没有工作流",
            "工作流状态文件不存在；不会自动创建或补编。",
        ));
    }

    let value = read_workflow_state_value(path)?;
    let validation_warnings = validate_workflow_state(&value);
    let workflow_id = request
        .workflow_id
        .clone()
        .unwrap_or_else(|| default_workflow_id(&request.project_root));
    let workflow = value
        .get("workflows")
        .and_then(Value::as_array)
        .and_then(|workflows| {
            workflows.iter().find(|workflow| {
                optional_string_from(workflow, "workflow_id").as_deref()
                    == Some(workflow_id.as_str())
            })
        });
    let Some(workflow) = workflow else {
        let mut check = blocked_workflow_run_check(
            &project.project_root,
            Some(&workflow_id),
            "missing_workflow",
            "没有工作流",
            "当前项目没有匹配的 workflow；不能运行、派发或标记准备完成。",
        );
        check.warnings.extend(validation_warnings);
        return Ok(check);
    };

    let nodes = value
        .get("nodes")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    let work_items = value
        .get("work_items")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    let artifacts = value
        .get("artifacts")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    let bindings = value
        .get("workflow_node_session_bindings")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    let mut check = inspect_workflow_run_check_from_value(
        &project.project_root,
        Some(&workflow_id),
        workflow,
        &nodes,
        &work_items,
        &artifacts,
        &bindings,
    );
    check.warnings.extend(validation_warnings);
    Ok(check)
}

fn inspect_workflow_run_check_from_value(
    project_root: &str,
    workflow_id: Option<&str>,
    workflow: &Value,
    nodes: &[Value],
    work_items: &[Value],
    artifacts: &[Value],
    bindings: &[Value],
) -> WorkflowRunCheck {
    let workflow_id_string = workflow_id.map(str::to_string);
    let mut checks = Vec::new();
    let workflow_id_value = workflow_id.unwrap_or_default();

    let has_director = optional_string_from(workflow, "owner_role")
        .is_some_and(|role| !role.trim().is_empty())
        || nodes.iter().any(|node| {
            optional_string_from(node, "workflow_id").as_deref() == Some(workflow_id_value)
                && (optional_string_from(node, "node_type").as_deref() == Some("director")
                    || optional_string_from(node, "node_id")
                        .is_some_and(|node_id| node_id.ends_with(":node:director")))
        });
    push_check(
        &mut checks,
        "missing_owner",
        "项目主管",
        if has_director { "pass" } else { "blocked" },
        if has_director {
            "工作流存在 director 节点或 owner_role。"
        } else {
            "没有项目主管；不能运行、派发或标记准备完成。"
        },
        workflow_id,
    );

    let workflow_items = work_items
        .iter()
        .filter(|item| {
            optional_string_from(item, "workflow_id").as_deref() == Some(workflow_id_value)
        })
        .collect::<Vec<_>>();
    if workflow_items.is_empty() {
        push_check(
            &mut checks,
            "missing_work_item",
            "工作项",
            "warning",
            "当前 workflow 还没有工作项；可以查看和编辑草稿，但不能派发。",
            workflow_id,
        );
    }

    for work_item in &workflow_items {
        let work_item_id = optional_string_from(work_item, "work_item_id")
            .unwrap_or_else(|| "work-item:missing".to_string());
        let artifact =
            find_task_package_artifact_for_work_item(artifacts, &work_item_id, work_item);
        let assigned_role = optional_string_from(work_item, "assigned_role_id");
        let dispatch_node_id = assigned_role
            .as_deref()
            .map(|role| format!("{workflow_id_value}:node:{role}"))
            .or_else(|| optional_string_from(work_item, "current_node_id"));
        let has_binding = dispatch_node_id.as_deref().is_some_and(|node_id| {
            bindings.iter().any(|binding| {
                optional_string_from(binding, "workflow_id").as_deref() == Some(workflow_id_value)
                    && optional_string_from(binding, "node_id").as_deref() == Some(node_id)
                    && optional_string_from(binding, "lifecycle").as_deref() == Some("active")
                    && bool_value(binding, "rollout_exists")
            })
        });
        push_check(
            &mut checks,
            "missing_session",
            "绑定会话",
            if has_binding { "pass" } else { "blocked" },
            if has_binding {
                "要派发的节点已有 active 会话绑定。"
            } else {
                "要派发的节点没有 active 会话绑定。"
            },
            Some(&work_item_id),
        );

        let model_id = artifact.and_then(|artifact| optional_string_from(artifact, "model_id"));
        push_check(
            &mut checks,
            "missing_model",
            "模型",
            if model_id
                .as_deref()
                .is_some_and(|value| !value.trim().is_empty())
            {
                "pass"
            } else {
                "blocked"
            },
            if model_id.is_some() {
                "任务包已显式指定模型。"
            } else {
                "缺模型；系统不会自动选择模型。"
            },
            Some(&work_item_id),
        );

        let allowed_read = artifact
            .map(|artifact| string_array(artifact, "allowed_read"))
            .unwrap_or_default();
        push_check(
            &mut checks,
            "missing_read_scope",
            "读取范围",
            if allowed_read.is_empty() {
                "blocked"
            } else {
                "pass"
            },
            if allowed_read.is_empty() {
                "没有读范围；不能运行。"
            } else {
                "任务包已登记允许读取范围。"
            },
            Some(&work_item_id),
        );

        let allowed_write = artifact
            .map(|artifact| string_array(artifact, "allowed_write"))
            .unwrap_or_default();
        push_check(
            &mut checks,
            "missing_write_scope",
            "写入范围",
            if allowed_write.is_empty() {
                "blocked"
            } else {
                "pass"
            },
            if allowed_write.is_empty() {
                "会写文件但没有写范围；不能运行。"
            } else {
                "任务包已登记允许写入范围。"
            },
            Some(&work_item_id),
        );

        let acceptance = artifact
            .map(|artifact| string_array(artifact, "acceptance_criteria"))
            .unwrap_or_default();
        push_check(
            &mut checks,
            "missing_acceptance_criteria",
            "验收标准",
            if acceptance.is_empty() {
                "blocked"
            } else {
                "pass"
            },
            if acceptance.is_empty() {
                "没有验收标准；不能运行。"
            } else {
                "任务包已登记验收标准。"
            },
            Some(&work_item_id),
        );

        let requires_tools =
            artifact.is_some_and(|artifact| bool_value(artifact, "requires_tools"));
        let tools = artifact
            .map(|artifact| string_array(artifact, "callable_tool_capabilities"))
            .unwrap_or_default();
        push_check(
            &mut checks,
            "missing_tool_whitelist",
            "工具白名单",
            if requires_tools && tools.is_empty() {
                "blocked"
            } else if tools.is_empty() {
                "warning"
            } else {
                "pass"
            },
            if requires_tools && tools.is_empty() {
                "节点声明需要工具但没有工具白名单。"
            } else if tools.is_empty() {
                "节点没有声明工具；工具白名单为空。"
            } else {
                "任务包已登记可调用工具白名单。"
            },
            Some(&work_item_id),
        );

        let requires_harness =
            artifact.is_some_and(|artifact| bool_value(artifact, "requires_harness"));
        let harness = artifact
            .map(|artifact| string_array(artifact, "harness_requirements"))
            .unwrap_or_default();
        push_check(
            &mut checks,
            "missing_harness_requirement",
            "Harness",
            if requires_harness && harness.is_empty() {
                "blocked"
            } else if harness.is_empty() {
                "warning"
            } else {
                "pass"
            },
            if requires_harness && harness.is_empty() {
                "节点要求 harness 但没有配置。"
            } else if harness.is_empty() {
                "节点未要求 harness；harness 要求为空。"
            } else {
                "任务包已登记 harness 要求。"
            },
            Some(&work_item_id),
        );

        let forbidden = artifact
            .map(|artifact| string_array(artifact, "forbidden_actions"))
            .unwrap_or_default();
        let policy_blocked = forbidden
            .iter()
            .any(|line| contains_conflicting_generation_ban(line))
            || allowed_write
                .iter()
                .any(|line| line.contains("/Users/yoyi/.codex"));
        push_check(
            &mut checks,
            "policy_violation",
            "权限冲突",
            if policy_blocked { "blocked" } else { "pass" },
            if policy_blocked {
                "存在权限冲突或历史禁令冲突。"
            } else {
                "没有发现权限冲突。"
            },
            Some(&work_item_id),
        );

        let unresolved_risk = artifact.is_some_and(|artifact| {
            bool_value(artifact, "unresolved_direction_risk")
                || string_array(artifact, "risk_flags")
                    .iter()
                    .any(|risk| risk.contains("unresolved"))
        });
        push_check(
            &mut checks,
            "unresolved_conflict",
            "未解决方向风险",
            if unresolved_risk { "blocked" } else { "pass" },
            if unresolved_risk {
                "有未解决方向风险；进入等待决策。"
            } else {
                "没有登记未解决方向风险。"
            },
            Some(&work_item_id),
        );

        let requires_knowledge =
            artifact.is_some_and(|artifact| bool_value(artifact, "requires_knowledge_refs"));
        let knowledge = artifact
            .map(|artifact| string_array(artifact, "available_knowledge_refs"))
            .unwrap_or_default();
        if requires_knowledge && knowledge.is_empty() {
            push_check(
                &mut checks,
                "missing_knowledge_refs",
                "知识库引用",
                "blocked",
                "任务包声明需要知识库引用，但没有显式引用。",
                Some(&work_item_id),
            );
        }
        let requires_memory =
            artifact.is_some_and(|artifact| bool_value(artifact, "requires_memory_refs"));
        let memory = artifact
            .map(|artifact| string_array(artifact, "available_memory_refs"))
            .unwrap_or_default();
        if requires_memory && memory.is_empty() {
            push_check(
                &mut checks,
                "missing_memory_refs",
                "记忆引用",
                "blocked",
                "任务包声明需要记忆作为依据，但没有确认记忆引用。",
                Some(&work_item_id),
            );
        }
    }

    let blocked_reasons = checks
        .iter()
        .filter(|check| check.status == "blocked")
        .map(|check| check.reason.clone())
        .collect::<Vec<_>>();
    let warnings = checks
        .iter()
        .filter(|check| check.status == "warning")
        .map(|check| check.reason.clone())
        .collect::<Vec<_>>();
    let status = if !blocked_reasons.is_empty() {
        "blocked"
    } else if !warnings.is_empty() {
        "warning"
    } else {
        "runnable"
    };

    WorkflowRunCheck {
        project_root: project_root.to_string(),
        workflow_id: workflow_id_string,
        status: status.to_string(),
        checks,
        blocked_reasons,
        warnings,
        evidence_completeness: if status == "runnable" {
            "complete".to_string()
        } else {
            "missing".to_string()
        },
    }
}

fn blocked_workflow_run_check(
    project_root: &str,
    workflow_id: Option<&str>,
    check_id: &str,
    label: &str,
    reason: &str,
) -> WorkflowRunCheck {
    let item = WorkflowRunCheckItem {
        check_id: check_id.to_string(),
        label: label.to_string(),
        status: "blocked".to_string(),
        severity: "blocked".to_string(),
        reason: reason.to_string(),
        source_ref: workflow_id.map(str::to_string),
    };
    WorkflowRunCheck {
        project_root: project_root.to_string(),
        workflow_id: workflow_id.map(str::to_string),
        status: "blocked".to_string(),
        checks: vec![item],
        blocked_reasons: vec![reason.to_string()],
        warnings: vec![],
        evidence_completeness: "missing".to_string(),
    }
}

fn push_check(
    checks: &mut Vec<WorkflowRunCheckItem>,
    check_id: &str,
    label: &str,
    status: &str,
    reason: &str,
    source_ref: Option<&str>,
) {
    checks.push(WorkflowRunCheckItem {
        check_id: check_id.to_string(),
        label: label.to_string(),
        status: status.to_string(),
        severity: status.to_string(),
        reason: reason.to_string(),
        source_ref: source_ref.map(str::to_string),
    });
}

fn find_task_package_artifact_for_work_item<'a>(
    artifacts: &'a [Value],
    work_item_id: &str,
    work_item: &Value,
) -> Option<&'a Value> {
    let source_ref = optional_string_from(work_item, "source_ref");
    artifacts.iter().find(|artifact| {
        optional_string_from(artifact, "artifact_type").as_deref() == Some("task_package")
            && (optional_string_from(artifact, "source_ref").as_deref() == Some(work_item_id)
                || source_ref.as_deref().is_some_and(|source_ref| {
                    optional_string_from(artifact, "artifact_id").as_deref() == Some(source_ref)
                }))
    })
}

fn update_work_item_state_at(
    path: &Path,
    request: &WorkItemStateUpdateRequest,
) -> Result<WorkflowStateMutationResult, String> {
    if !path.exists() {
        return Err("工作流状态文件不存在；无法推进工作项状态".to_string());
    }

    let timestamp = unix_timestamp_string();
    let mut value = read_workflow_state_value(path)?;
    let validation_warnings = validate_workflow_state(&value);
    if !validation_warnings.is_empty() {
        return Err(format!(
            "当前状态文件未通过 schema 校验：{}",
            validation_warnings.join(", ")
        ));
    }

    let workflow_id = default_workflow_id(&request.project_root);
    if !workflow_exists(&value, &workflow_id) {
        return Err("当前项目还没有本地 workflow；无法推进工作项状态".to_string());
    }

    let work_item_index = find_work_item_index(&value, &workflow_id, &request.work_item_id)
        .ok_or_else(|| "当前 workflow 下找不到该 work item；无法推进工作项状态".to_string())?;
    let before_state = value
        .get("work_items")
        .and_then(Value::as_array)
        .and_then(|items| items.get(work_item_index))
        .and_then(|item| optional_string_from(item, "state"))
        .unwrap_or_else(|| "draft".to_string());
    let next_state = request.next_state.trim();
    control_core::validate_work_item_state_transition(&before_state, next_state)?;

    let parent = path
        .parent()
        .ok_or_else(|| format!("状态文件路径没有父目录：{}", path.display()))?;
    let backups_dir = parent.join("backups");
    fs::create_dir_all(&backups_dir)
        .map_err(|error| format!("创建备份目录失败 {}：{error}", backups_dir.display()))?;
    let backup = backups_dir.join(format!("workflow-state.v0.{timestamp}.json"));
    fs::copy(path, &backup)
        .map_err(|error| format!("备份旧状态文件失败 {}：{error}", backup.display()))?;

    let current_node_id = workflow_node_for_work_item_state(&workflow_id, next_state);
    {
        let work_items = array_mut(&mut value, "work_items")?;
        let work_item = work_items
            .get_mut(work_item_index)
            .ok_or_else(|| "当前 workflow 下找不到该 work item；无法推进工作项状态".to_string())?;
        work_item["state"] = Value::String(next_state.to_string());
        work_item["current_node_id"] = Value::String(current_node_id.clone());
        work_item["updated_at"] = Value::String(timestamp.clone());
    }
    update_node_state_for_id(&mut value, &current_node_id, next_state, &timestamp)?;

    let audit_event_id = format!(
        "audit:work-item-state:{}:{timestamp}",
        stable_id(&request.work_item_id)
    );
    array_mut(&mut value, "audit_events")?.push(workflow_audit::work_item_state_changed(
        workflow_audit::WorkItemStateChangedAudit {
            event_id: audit_event_id.clone(),
            work_item_id: &request.work_item_id,
            before_state: &before_state,
            after_state: next_state,
            created_at: &timestamp,
            reason: format!(
                "用户确认推进工作项状态到：{}",
                work_item_state_label(next_state)
            ),
        },
    ));

    value["updated_at"] = Value::String(timestamp);
    let validation_warnings = validate_workflow_state(&value);
    if !validation_warnings.is_empty() {
        return Err(format!(
            "写入前 schema 校验失败：{}",
            validation_warnings.join(", ")
        ));
    }

    atomic_write_json(path, &value)?;
    let snapshot = read_workflow_state_snapshot(path)?;
    if !snapshot.exists {
        return Err("推进工作项状态后重新读取校验失败".to_string());
    }

    Ok(WorkflowStateMutationResult {
        message: format!(
            "已推进工作项状态：{} -> {}",
            work_item_state_label(&before_state),
            work_item_state_label(next_state)
        ),
        path: path.display().to_string(),
        backup_path: Some(backup.display().to_string()),
        audit_event_id,
        first_initialize: false,
        snapshot,
    })
}

fn bind_workflow_node_codex_session_at(
    path: &Path,
    request: &WorkflowNodeSessionBindRequest,
    session: &SessionRecord,
) -> Result<WorkflowStateMutationResult, String> {
    if !path.exists() {
        return Err("工作流状态文件不存在；无法绑定节点会话".to_string());
    }

    let timestamp = unix_timestamp_string();
    let timestamp_ms = unix_timestamp_ms();
    let mut value = read_workflow_state_value(path)?;
    ensure_workflow_node_session_bindings_array(&mut value)?;
    let validation_warnings = validate_workflow_state(&value);
    if !validation_warnings.is_empty() {
        return Err(format!(
            "当前状态文件未通过 schema 校验：{}",
            validation_warnings.join(", ")
        ));
    }

    let workflow_id = default_workflow_id(&request.project_root);
    if !workflow_exists(&value, &workflow_id) {
        return Err("当前项目还没有本地 workflow；无法绑定节点会话".to_string());
    }
    if !node_exists(&value, &workflow_id, &request.node_id) {
        return Err("当前 workflow 下找不到该 node；无法绑定节点会话".to_string());
    }
    if let Some(work_item_id) = request.work_item_id.as_deref() {
        if find_work_item(&value, &workflow_id, work_item_id).is_none() {
            return Err("当前 workflow 下找不到该 work item；无法绑定节点会话".to_string());
        }
    }

    let parent = path
        .parent()
        .ok_or_else(|| format!("状态文件路径没有父目录：{}", path.display()))?;
    let backups_dir = parent.join("backups");
    fs::create_dir_all(&backups_dir)
        .map_err(|error| format!("创建备份目录失败 {}：{error}", backups_dir.display()))?;
    let backup = backups_dir.join(format!("workflow-state.v0.{timestamp}.json"));
    fs::copy(path, &backup)
        .map_err(|error| format!("备份旧状态文件失败 {}：{error}", backup.display()))?;

    let existing_active_index = workflow_node_session_binding_index(
        &value,
        &workflow_id,
        &request.node_id,
        request.work_item_id.as_deref(),
    );
    let before_state = existing_active_index
        .and_then(|index| {
            value
                .get("workflow_node_session_bindings")
                .and_then(Value::as_array)
                .and_then(|bindings| bindings.get(index))
                .and_then(|binding| optional_string_from(binding, "native_thread_id"))
        })
        .unwrap_or_else(|| "unbound".to_string());
    let event_type = if existing_active_index.is_some() {
        "workflow_node_session_rebound"
    } else {
        "workflow_node_session_bound"
    };
    let binding_id = existing_active_index
        .and_then(|index| {
            value
                .get("workflow_node_session_bindings")
                .and_then(Value::as_array)
                .and_then(|bindings| bindings.get(index))
                .and_then(|binding| optional_string_from(binding, "binding_id"))
        })
        .unwrap_or_else(|| {
            format!(
                "binding:{}:{}:{}",
                stable_id(&workflow_id),
                stable_id(&request.node_id),
                stable_id(request.work_item_id.as_deref().unwrap_or("node"))
            )
        });
    let mut warnings = Vec::new();
    if !session.rollout_exists {
        warnings.push("index_session_rollout_missing".to_string());
    }
    if session.project_root.as_deref() != Some(request.project_root.as_str()) {
        warnings.push("session_project_root_differs_from_current_project".to_string());
    }
    let binding = json!({
      "binding_id": binding_id,
      "project_id": project_id(&request.project_root),
      "workflow_id": workflow_id,
      "node_id": request.node_id,
      "work_item_id": request.work_item_id,
      "agent_type": "codex",
      "adapter_id": "codex-local",
      "native_thread_id": session.thread_id,
      "native_rollout_path": session.rollout_path,
      "session_title": session.title,
      "session_updated_at_ms": session.updated_at_ms,
      "rollout_exists": session.rollout_exists,
      "project_binding_source": "index_inferred",
      "binding_source": "workflow_bound",
      "binding_mode": "select_existing_session",
      "lifecycle": "active",
      "created_at_ms": timestamp_ms,
      "updated_at_ms": timestamp_ms,
      "warnings": warnings
    });
    if let Some(index) = existing_active_index {
        let bindings = array_mut(&mut value, "workflow_node_session_bindings")?;
        let old_created_at = bindings
            .get(index)
            .and_then(|binding| i64_value(binding, "created_at_ms"));
        bindings[index] = binding;
        if let Some(created_at) = old_created_at {
            bindings[index]["created_at_ms"] = Value::Number(created_at.into());
        }
    } else {
        array_mut(&mut value, "workflow_node_session_bindings")?.push(binding);
    }

    let audit_event_id = format!(
        "audit:workflow-node-session:{}:{timestamp}",
        stable_id(&request.node_id)
    );
    array_mut(&mut value, "audit_events")?.push(json!({
      "event_id": audit_event_id,
      "event_type": event_type,
      "target_ref": request.node_id,
      "actor_ref": "user_confirmed_desktop_shell",
      "source_kind": "workspace_state",
      "permission_level": "user_confirmed_write",
      "before_state": before_state,
      "after_state": session.thread_id,
      "created_at": timestamp,
      "reason": "用户确认把已有 Codex 会话绑定到工作流节点；没有启动 Codex、没有发送消息、没有读取 transcript 正文。"
    }));
    value["updated_at"] = Value::String(timestamp);

    let validation_warnings = validate_workflow_state(&value);
    if !validation_warnings.is_empty() {
        return Err(format!(
            "写入前 schema 校验失败：{}",
            validation_warnings.join(", ")
        ));
    }
    atomic_write_json(path, &value)?;
    let snapshot = read_workflow_state_snapshot(path)?;
    if !snapshot.exists {
        return Err("绑定节点会话后重新读取校验失败".to_string());
    }

    Ok(WorkflowStateMutationResult {
        message: format!("已绑定节点会话：{}", session.title),
        path: path.display().to_string(),
        backup_path: Some(backup.display().to_string()),
        audit_event_id,
        first_initialize: false,
        snapshot,
    })
}

fn unbind_workflow_node_codex_session_at(
    path: &Path,
    request: &WorkflowNodeSessionUnbindRequest,
) -> Result<WorkflowStateMutationResult, String> {
    if !path.exists() {
        return Err("工作流状态文件不存在；无法解绑节点会话".to_string());
    }

    let timestamp = unix_timestamp_string();
    let timestamp_ms = unix_timestamp_ms();
    let mut value = read_workflow_state_value(path)?;
    ensure_workflow_node_session_bindings_array(&mut value)?;
    let validation_warnings = validate_workflow_state(&value);
    if !validation_warnings.is_empty() {
        return Err(format!(
            "当前状态文件未通过 schema 校验：{}",
            validation_warnings.join(", ")
        ));
    }
    let workflow_id = default_workflow_id(&request.project_root);
    if !workflow_exists(&value, &workflow_id) {
        return Err("当前项目还没有本地 workflow；无法解绑节点会话".to_string());
    }

    let binding_index = value
        .get("workflow_node_session_bindings")
        .and_then(Value::as_array)
        .and_then(|bindings| {
            bindings.iter().position(|binding| {
                optional_string_from(binding, "binding_id").as_deref()
                    == Some(request.binding_id.as_str())
                    && optional_string_from(binding, "workflow_id").as_deref()
                        == Some(workflow_id.as_str())
                    && optional_string_from(binding, "lifecycle").as_deref() == Some("active")
            })
        })
        .ok_or_else(|| "当前 workflow 下找不到 active 节点会话绑定；无法解绑".to_string())?;

    let parent = path
        .parent()
        .ok_or_else(|| format!("状态文件路径没有父目录：{}", path.display()))?;
    let backups_dir = parent.join("backups");
    fs::create_dir_all(&backups_dir)
        .map_err(|error| format!("创建备份目录失败 {}：{error}", backups_dir.display()))?;
    let backup = backups_dir.join(format!("workflow-state.v0.{timestamp}.json"));
    fs::copy(path, &backup)
        .map_err(|error| format!("备份旧状态文件失败 {}：{error}", backup.display()))?;

    let before_thread_id = value
        .get("workflow_node_session_bindings")
        .and_then(Value::as_array)
        .and_then(|bindings| bindings.get(binding_index))
        .and_then(|binding| optional_string_from(binding, "native_thread_id"))
        .unwrap_or_else(|| "unknown".to_string());
    {
        let bindings = array_mut(&mut value, "workflow_node_session_bindings")?;
        let binding = bindings
            .get_mut(binding_index)
            .ok_or_else(|| "当前 workflow 下找不到 active 节点会话绑定；无法解绑".to_string())?;
        binding["lifecycle"] = Value::String("detached".to_string());
        binding["updated_at_ms"] = Value::Number(timestamp_ms.into());
    }
    let audit_event_id = format!(
        "audit:workflow-node-session-unbind:{}:{timestamp}",
        stable_id(&request.binding_id)
    );
    array_mut(&mut value, "audit_events")?.push(json!({
      "event_id": audit_event_id,
      "event_type": "workflow_node_session_unbound",
      "target_ref": request.binding_id,
      "actor_ref": "user_confirmed_desktop_shell",
      "source_kind": "workspace_state",
      "permission_level": "user_confirmed_write",
      "before_state": before_thread_id,
      "after_state": "detached",
      "created_at": timestamp,
      "reason": "用户确认解除工作台自己的节点会话绑定；没有删除、移动或归档 Codex 原始会话。"
    }));
    value["updated_at"] = Value::String(timestamp);

    let validation_warnings = validate_workflow_state(&value);
    if !validation_warnings.is_empty() {
        return Err(format!(
            "写入前 schema 校验失败：{}",
            validation_warnings.join(", ")
        ));
    }
    atomic_write_json(path, &value)?;
    let snapshot = read_workflow_state_snapshot(path)?;
    if !snapshot.exists {
        return Err("解绑节点会话后重新读取校验失败".to_string());
    }

    Ok(WorkflowStateMutationResult {
        message: "已解除节点会话绑定；没有删除 Codex 原始会话。".to_string(),
        path: path.display().to_string(),
        backup_path: Some(backup.display().to_string()),
        audit_event_id,
        first_initialize: false,
        snapshot,
    })
}

fn prepare_workflow_node_dispatch_at(
    path: &Path,
    index: &Value,
    request: &WorkflowNodeDispatchPrepareRequest,
) -> Result<WorkflowNodeDispatchResult, String> {
    let mut context = workflow_node_dispatch_context(path, index, request)?;
    control_core::validate_dispatch_prepare(&context.work_item_state)?;
    let authorization_check = inspect_workflow_node_dispatch_authorization(path, &context)?;
    ensure_authorized_for_prepare(&authorization_check)?;
    context.plan_authorization_id = authorization_check.authorization_id.clone();
    context.authorization_check = Some(authorization_check);
    write_prepared_dispatch(path, context)
}

fn execute_workflow_node_dispatch_at(
    path: &Path,
    index: &Value,
    readback_db_path: &Path,
    runner: &dyn CodexResumeRunner,
    request: &WorkflowNodeDispatchExecuteRequest,
) -> Result<WorkflowNodeDispatchResult, String> {
    let prepare_request = WorkflowNodeDispatchPrepareRequest {
        project_root: request.project_root.clone(),
        node_id: request.node_id.clone(),
        work_item_id: request.work_item_id.clone(),
        prompt_kind: request.prompt_kind.clone(),
        user_reviewed_instruction: request.user_reviewed_instruction.clone(),
    };
    let context = workflow_node_dispatch_context(path, index, &prepare_request)?;
    control_core::validate_dispatch_start(&context.work_item_state)?;
    let _prepared = write_prepared_dispatch(path, context.clone())?;
    let dispatch = write_started_dispatch(path, &context)?;
    let dispatch_id = dispatch.dispatch_id.clone();
    let last_message_path = dispatch
        .last_message_path
        .as_ref()
        .ok_or_else(|| "派发记录缺少最终回复路径".to_string())
        .map(PathBuf::from)?;

    let run_result = runner.resume_with_options(
        &context.native_thread_id,
        &context.prompt_preview,
        &last_message_path,
        &codex_resume_options_for_context(&context)?,
    );
    match run_result {
        Ok((result, options)) if result.exit_code == 0 => {
            let stats = match options.readback_stats {
                Some(stats) => stats,
                None => dispatch_readback_stats(Some(index), readback_db_path, &context)?,
            };
            write_completed_dispatch(path, &dispatch_id, result.exit_code, stats)
        }
        Ok((result, _options)) => write_failed_dispatch(
            path,
            &dispatch_id,
            result.exit_code,
            classify_codex_resume_failure(
                result.exit_code,
                result.timed_out,
                &context.user_reviewed_instruction,
                result.stderr_summary.as_deref().unwrap_or(""),
            ),
        ),
        Err(error) => write_failed_dispatch(
            path,
            &dispatch_id,
            -1,
            classify_codex_resume_failure(-1, false, &context.user_reviewed_instruction, &error),
        ),
    }
}

fn read_workflow_node_dispatch_result_at(
    path: &Path,
    index: &Value,
    readback_db_path: &Path,
    request: &WorkflowNodeDispatchReadbackRequest,
) -> Result<WorkflowNodeDispatchResult, String> {
    if !path.exists() {
        return Err("工作流状态文件不存在；无法读取节点派发结果".to_string());
    }
    let value = read_workflow_state_value(path)?;
    let dispatch = find_workflow_node_dispatch(&value, &request.dispatch_id)
        .ok_or_else(|| "找不到该节点派发记录".to_string())?;
    let workflow_id = optional_string_from(dispatch, "workflow_id")
        .ok_or_else(|| "节点派发记录缺 workflow_id".to_string())?;
    let work_item_id = optional_string_from(dispatch, "work_item_id")
        .ok_or_else(|| "节点派发记录缺 work_item_id".to_string())?;
    let node_id = optional_string_from(dispatch, "node_id")
        .ok_or_else(|| "节点派发记录缺 node_id".to_string())?;
    let prompt_kind =
        optional_string_from(dispatch, "prompt_kind").unwrap_or_else(|| "safe_probe".to_string());
    let user_reviewed_instruction = if prompt_kind == "user_reviewed_instruction" {
        Some(user_reviewed_instruction_input_from_value(
            dispatch.get("user_reviewed_instruction").ok_or_else(|| {
                "业务派发记录缺少 user_reviewed_instruction，无法回读".to_string()
            })?,
        )?)
    } else {
        None
    };
    let prepare_request = WorkflowNodeDispatchPrepareRequest {
        project_root: request.project_root.clone(),
        node_id,
        work_item_id,
        prompt_kind,
        user_reviewed_instruction,
    };
    let context = workflow_node_dispatch_context(path, index, &prepare_request)?;
    if context.workflow_id != workflow_id {
        return Err("节点派发记录不属于当前项目默认 workflow".to_string());
    }
    let stats = dispatch_readback_stats(Some(index), readback_db_path, &context)?;
    write_readback_dispatch(path, &request.dispatch_id, stats)
}

#[derive(Clone, Debug)]
struct WorkflowNodeDispatchContext {
    project_id: String,
    workflow_id: String,
    node_id: String,
    work_item_id: String,
    work_item_state: String,
    binding_id: String,
    native_thread_id: String,
    prompt_preview: String,
    prompt_kind: String,
    memory_packet_snapshot_id: Option<String>,
    memory_packet_fingerprint: Option<String>,
    plan_authorization_id: Option<String>,
    authorization_check: Option<AutoDispatchGuardResult>,
    user_reviewed_instruction: Option<UserReviewedInstructionInput>,
    warnings: Vec<String>,
}

fn workflow_node_dispatch_context(
    path: &Path,
    index: &Value,
    request: &WorkflowNodeDispatchPrepareRequest,
) -> Result<WorkflowNodeDispatchContext, String> {
    if !path.exists() {
        return Err("工作流状态文件不存在；无法准备节点派发".to_string());
    }
    let value = read_workflow_state_value(path)?;
    ensure_valid_dispatch_state(&value)?;
    let workflow_id = default_workflow_id(&request.project_root);
    if !workflow_exists(&value, &workflow_id) {
        return Err("当前项目还没有本地 workflow；无法准备节点派发".to_string());
    }
    if !node_exists(&value, &workflow_id, &request.node_id) {
        return Err("当前 workflow 下找不到该 node；无法准备节点派发".to_string());
    }
    let work_item = find_work_item(&value, &workflow_id, &request.work_item_id)
        .ok_or_else(|| "当前 workflow 下找不到该 work item；无法准备节点派发".to_string())?;
    let work_item_state =
        optional_string_from(work_item, "state").unwrap_or_else(|| "unknown".to_string());
    let binding_index = workflow_node_session_binding_index(
        &value,
        &workflow_id,
        &request.node_id,
        Some(&request.work_item_id),
    )
    .or_else(|| workflow_node_session_binding_index(&value, &workflow_id, &request.node_id, None))
    .ok_or_else(|| "当前工作流节点没有 active Codex 会话绑定；无法派发".to_string())?;
    let binding = value
        .get("workflow_node_session_bindings")
        .and_then(Value::as_array)
        .and_then(|bindings| bindings.get(binding_index))
        .ok_or_else(|| "当前工作流节点绑定记录缺失；无法派发".to_string())?;
    let native_thread_id = optional_string_from(binding, "native_thread_id")
        .ok_or_else(|| "节点绑定缺少 Codex thread id；无法派发".to_string())?;
    let session = find_index_thread(index, &native_thread_id)
        .ok_or_else(|| "绑定会话不在当前索引内，已拒绝派发".to_string())?;
    if !session.rollout_exists {
        return Err("绑定会话在索引中缺少 rollout，已拒绝派发".to_string());
    }
    let prompt_kind = request.prompt_kind.trim();
    let user_reviewed_instruction = if prompt_kind == "user_reviewed_instruction" {
        let instruction = request
            .user_reviewed_instruction
            .clone()
            .ok_or_else(|| "用户审核模式缺少完整派发字段，已阻止真实业务派发".to_string())?;
        validate_user_reviewed_instruction(&instruction)?;
        Some(instruction)
    } else {
        None
    };
    let base_prompt_preview = if prompt_kind == "safe_probe" {
        safe_probe_prompt()
    } else if prompt_kind == "user_reviewed_instruction" {
        render_user_reviewed_business_prompt(
            user_reviewed_instruction
                .as_ref()
                .ok_or_else(|| "用户审核模式缺少完整派发字段，已阻止真实业务派发".to_string())?,
        )
    } else {
        return Err(format!("未知派发模式：{prompt_kind}"));
    };
    let memory_snapshot = find_task_package_artifact(&value, &request.work_item_id, work_item)
        .and_then(task_memory_injection::snapshot_from_artifact);
    let prompt_preview = memory_snapshot
        .as_ref()
        .map(|snapshot| {
            format!(
                "{}\n\n{}",
                base_prompt_preview,
                task_memory_injection::render_prompt_block(snapshot)
            )
        })
        .unwrap_or(base_prompt_preview);
    let mut warnings = string_array(binding, "warnings");
    warnings.push("legacy_workflow_node_dispatch_not_h5_unified_product_command".to_string());
    warnings.push(
        "legacy_dispatch_requires_h5_continuation_routing_before_product_real_execution"
            .to_string(),
    );
    if session.project_root.as_deref() != Some(request.project_root.as_str()) {
        warnings.push("session_project_root_differs_from_current_project".to_string());
    }
    if let Some(snapshot) = &memory_snapshot {
        warnings.push("task_memory_packet_snapshot_attached".to_string());
        let current =
            task_memory_injection::current_store_revisions(path, &unix_timestamp_string())?;
        if !task_memory_injection::stale_reasons(snapshot, &current).is_empty() {
            warnings.push("task_memory_packet_snapshot_stale".to_string());
        }
    }

    Ok(WorkflowNodeDispatchContext {
        project_id: project_id(&request.project_root),
        workflow_id,
        node_id: request.node_id.clone(),
        work_item_id: request.work_item_id.clone(),
        work_item_state,
        binding_id: optional_string_from(binding, "binding_id")
            .ok_or_else(|| "节点绑定缺少 binding_id；无法派发".to_string())?,
        native_thread_id,
        prompt_preview,
        prompt_kind: prompt_kind.to_string(),
        memory_packet_snapshot_id: memory_snapshot
            .as_ref()
            .map(|snapshot| snapshot.snapshot_id.clone()),
        memory_packet_fingerprint: memory_snapshot
            .as_ref()
            .map(|snapshot| snapshot.fingerprint.clone()),
        plan_authorization_id: None,
        authorization_check: None,
        user_reviewed_instruction,
        warnings,
    })
}

fn inspect_task_package_authorization_at(
    path: &Path,
    project: &ProjectRecord,
    workflow_id: &str,
    work_item: &Value,
    artifact: &Value,
    fields: &RenderTaskPackageFields,
    dispatch_kind: &str,
) -> Result<AutoDispatchGuardResult, String> {
    let work_item_id = fields.work_item_id.clone();
    let target_role_id = optional_string_from(work_item, "assigned_role_id")
        .or_else(|| optional_string_from(artifact, "target_role"))
        .unwrap_or_else(|| assigned_line_id(&fields.assigned_line).to_string());
    let input = AutoDispatchGuardInput {
        project_id: project_id(&project.project_root),
        workflow_id: workflow_id.to_string(),
        work_item_id,
        task_package_id: optional_string_from(artifact, "artifact_id"),
        task_package_kind: optional_string_from(artifact, "artifact_type")
            .or_else(|| Some("task_package".to_string())),
        target_role_id,
        target_agent_id: optional_string_from(artifact, "target_session_id"),
        requested_read_roots: fields.allowed_read.clone(),
        requested_write_roots: fields.allowed_write.clone(),
        requested_tools: string_array(artifact, "callable_tool_capabilities"),
        requested_checks: string_array(artifact, "harness_requirements"),
        triggered_stop_conditions: vec![],
        dispatch_kind: dispatch_kind.to_string(),
    };
    plan_authorization_store::inspect_auto_dispatch_authorization(
        path,
        &input,
        unix_timestamp_ms(),
        &format!("write-task-package-auth-check-{}", unix_timestamp_nanos()),
    )
}

#[derive(Clone)]
struct ProjectDirectorAuthorizationContext {
    project: ProjectRecord,
    proposal: ProjectConsultationProposal,
    authorization: PlanAuthorization,
    authorization_store: PlanAuthorizationStoreV1,
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct ActiveBindingInfo {
    binding_id: String,
    native_thread_id: String,
    rollout_exists: bool,
    warnings: Vec<String>,
}

fn preview_project_director_task_plan_for_index_at(
    path: &Path,
    index: &Value,
    request: &PreviewProjectDirectorTaskPlanInput,
) -> Result<ProjectDirectorTaskPlan, String> {
    let value = read_c4_workflow_value(path, &request.project_root, &request.workflow_id)?;
    let context = project_director_authorization_context(
        path,
        index,
        &request.project_root,
        &request.project_id,
        &request.workflow_id,
        &request.proposal_id,
        &request.authorization_id,
        request.expected_authorization_revision,
    )?;
    let tasks = annotate_project_director_planned_tasks(
        index,
        &value,
        &context,
        deterministic_project_director_planned_tasks(&context),
        unix_timestamp_ms(),
    );
    Ok(project_director_task_plan_from_tasks(
        &request.project_root,
        &request.project_id,
        &request.workflow_id,
        &request.proposal_id,
        &request.authorization_id,
        &request.actor_id,
        tasks,
        &value,
    ))
}

fn prepare_authorized_auto_dispatch_for_index_at(
    path: &Path,
    index: &Value,
    request: &PrepareAuthorizedAutoDispatchInput,
) -> Result<AuthorizedPreparedDispatchResult, String> {
    let mut value = read_c4_workflow_value(path, &request.project_root, &request.workflow_id)?;
    if let Some(expected) = request.expected_workflow_revision {
        let current = i64_value(&value, "workflow_version").unwrap_or_default();
        if current != expected {
            return Err(format!(
                "workflow revision 不匹配：expected {expected}, actual {current}"
            ));
        }
    }
    let context = project_director_authorization_context(
        path,
        index,
        &request.project_root,
        &request.project_id,
        &request.workflow_id,
        &request.proposal_id,
        &request.authorization_id,
        request.expected_authorization_revision,
    )?;
    let timestamp = unix_timestamp_string();
    let timestamp_ms = unix_timestamp_ms();
    let mut backup_path: Option<PathBuf> = None;
    let mut audit_event_id = format!(
        "no-op:authorized-prepared-dispatch:{}",
        request.authorization_id
    );
    let planned_tasks = if request.planned_tasks.is_empty() {
        deterministic_project_director_planned_tasks(&context)
    } else {
        request.planned_tasks.clone()
    };
    let mut annotated = annotate_project_director_planned_tasks(
        index,
        &value,
        &context,
        planned_tasks.clone(),
        timestamp_ms,
    );

    for task in &mut annotated {
        if task
            .guard_result
            .as_ref()
            .is_none_or(|guard| guard.status != "authorized")
            || !task.blocked_reasons.is_empty() && task.status == "blocked"
        {
            ensure_c4_backup(path, &timestamp, &mut backup_path)?;
            audit_event_id = push_authorized_prepared_dispatch_blocked_audit(
                &mut value,
                task,
                &context.authorization.authorization_id,
                &timestamp,
                "authorized_prepared_dispatch_blocked",
                "项目主管拆任务授权检查未通过；未创建 prepared dispatch。",
            )?;
            continue;
        }

        let work_item_id =
            c4_work_item_id(&context.authorization.workflow_id, &task.planned_task_id);
        let artifact_id =
            c4_task_package_artifact_id(&context.authorization.workflow_id, &task.planned_task_id);
        let node_id = c4_node_id(&context.authorization.workflow_id, &task.scope.target_role);
        task.work_item_id = Some(work_item_id.clone());
        task.task_package_id = Some(artifact_id.clone());
        task.workflow_node_id = Some(node_id.clone());

        ensure_c4_backup(path, &timestamp, &mut backup_path)?;
        ensure_project_director_worker_node(&mut value, &node_id, task, &timestamp)?;
        ensure_project_director_work_item(
            &mut value,
            &work_item_id,
            &artifact_id,
            task,
            &timestamp,
        )?;
        let memory_snapshot = project_director_memory_snapshot(
            path,
            &request.project_root,
            task,
            &work_item_id,
            &artifact_id,
            &timestamp,
        )?;
        task.memory_packet_snapshot_id = Some(memory_snapshot.snapshot_id.clone());
        ensure_project_director_task_package_artifact(
            &mut value,
            &context.project,
            &work_item_id,
            &artifact_id,
            task,
            &memory_snapshot,
            &timestamp,
        )?;

        let binding = active_binding_for_planned_task(index, &value, &node_id, &work_item_id);
        let Some(binding) = binding else {
            task.status = "needs_binding".to_string();
            push_unique(&mut task.blocked_reasons, "等待绑定会话后才能准备派发。");
            audit_event_id = push_authorized_prepared_dispatch_blocked_audit(
                &mut value,
                task,
                &context.authorization.authorization_id,
                &timestamp,
                "authorized_prepared_dispatch_blocked",
                "项目主管拆任务已生成任务包草案和记忆快照，但目标 worker 节点缺少 active binding；未创建 prepared dispatch。",
            )?;
            continue;
        };
        if !binding.rollout_exists {
            task.status = "needs_binding".to_string();
            push_unique(
                &mut task.blocked_reasons,
                "绑定会话 rollout 不可用，等待重新绑定。",
            );
            audit_event_id = push_authorized_prepared_dispatch_blocked_audit(
                &mut value,
                task,
                &context.authorization.authorization_id,
                &timestamp,
                "authorized_prepared_dispatch_blocked",
                "项目主管拆任务已生成任务包草案和记忆快照，但绑定会话不可用；未创建 prepared dispatch。",
            )?;
            continue;
        }

        if let Some(existing_dispatch) = existing_prepared_dispatch_for_planned_task(
            &value,
            &task.planned_task_id,
            &work_item_id,
            &context.authorization.authorization_id,
        ) {
            task.status = "prepared".to_string();
            task.prepared_dispatch_id = optional_string_from(existing_dispatch, "dispatch_id");
            continue;
        }

        let prompt_preview = render_project_director_prepared_prompt(task, &memory_snapshot);
        let dispatch_id = format!(
            "authorized-prepared-dispatch:{}:{}",
            stable_id(&task.planned_task_id),
            timestamp
        );
        let authorization_check = task.guard_result.clone().ok_or_else(|| {
            "项目主管 planned task 缺少授权检查结果，不能创建 prepared dispatch".to_string()
        })?;
        array_mut(&mut value, "workflow_node_dispatches")?.push(json!({
          "dispatch_id": dispatch_id,
          "project_id": context.authorization.project_id,
          "workflow_id": context.authorization.workflow_id,
          "node_id": node_id,
          "work_item_id": work_item_id,
          "binding_id": binding.binding_id,
          "native_thread_id": binding.native_thread_id,
          "prompt_preview": prompt_preview,
          "prompt_kind": "authorized_prepared_auto_dispatch",
          "memory_packet_snapshot_id": memory_snapshot.snapshot_id,
          "memory_packet_fingerprint": memory_snapshot.fingerprint,
          "plan_authorization_id": context.authorization.authorization_id,
          "authorization_check": serde_json::to_value(&authorization_check).unwrap_or(Value::Null),
          "state": "prepared",
          "started_at_ms": Value::Null,
          "ended_at_ms": Value::Null,
          "exit_code": Value::Null,
          "last_message_path": Value::Null,
          "last_message_summary": Value::Null,
          "transcript_event_count": Value::Null,
          "transcript_target_hits": Value::Null,
          "c4_planned_task_id": task.planned_task_id,
          "warnings": dedupe_strings({
              let mut warnings = vec![
                  "prepared_only_no_worker_execution".to_string(),
                  "task_memory_packet_snapshot_attached".to_string()
              ];
              warnings.extend(binding.warnings.clone());
              warnings
          }),
          "created_at_ms": timestamp_ms,
          "updated_at_ms": timestamp_ms
        }));
        task.status = "prepared".to_string();
        task.prepared_dispatch_id = Some(dispatch_id.clone());
        audit_event_id = push_authorized_prepared_dispatch_created_audit(
            &mut value,
            task,
            &dispatch_id,
            &context.authorization.authorization_id,
            &timestamp,
        )?;
    }

    if backup_path.is_some() {
        value["updated_at"] = Value::String(timestamp.clone());
        write_validated_workflow_state(path, &value)?;
    }

    let updated_value = read_workflow_state_value(path)?;
    let final_tasks = annotate_project_director_planned_tasks(
        index,
        &updated_value,
        &context,
        planned_tasks,
        timestamp_ms,
    );
    let plan = project_director_task_plan_from_tasks(
        &request.project_root,
        &request.project_id,
        &request.workflow_id,
        &request.proposal_id,
        &request.authorization_id,
        &request.actor_id,
        final_tasks,
        &updated_value,
    );
    let prepared_dispatches = prepared_dispatch_read_models_from_plan(&plan, &updated_value);
    let snapshot = read_workflow_state_snapshot(path)?;
    let warnings = plan.warnings.clone();
    Ok(AuthorizedPreparedDispatchResult {
        message: format!(
            "项目主管拆任务已准备：planned {} / prepared {} / needs_binding {} / blocked {}；已准备；仍未执行 worker。",
            plan.planned_task_count,
            plan.prepared_dispatch_count,
            plan.needs_binding_count,
            plan.blocked_count
        ),
        path: path.display().to_string(),
        backup_path: backup_path.map(|path| path.display().to_string()),
        audit_event_id,
        plan,
        prepared_dispatches,
        snapshot,
        warnings,
    })
}

fn record_worker_structured_report_at(
    path: &Path,
    request: &WorkerStructuredReportInput,
) -> Result<WorkflowStateMutationResult, String> {
    if !path.exists() {
        return Err("工作流状态文件不存在；无法记录 worker 结构化汇报".to_string());
    }
    validate_worker_structured_report_input(request)?;
    let timestamp = unix_timestamp_string();
    let mut value = read_workflow_state_value(path)?;
    if let Some(expected) = request.expected_workflow_revision {
        let current = i64_value(&value, "workflow_version").unwrap_or_default();
        if current != expected {
            return Err(format!(
                "workflow revision 不匹配：expected {expected}, actual {current}"
            ));
        }
    }
    let validation_warnings = validate_workflow_state(&value);
    if !validation_warnings.is_empty() {
        return Err(format!(
            "当前状态文件未通过 schema 校验：{}",
            validation_warnings.join(", ")
        ));
    }
    if !workflow_exists(&value, &request.workflow_id) {
        return Err("当前项目还没有目标 workflow；无法记录 worker 结构化汇报".to_string());
    }
    if find_work_item(&value, &request.workflow_id, &request.work_item_id).is_none() {
        return Err("当前 workflow 下找不到该 work item；无法记录 worker 结构化汇报".to_string());
    }
    if !node_exists(&value, &request.workflow_id, &request.workflow_node_id) {
        return Err("当前 workflow 下找不到该 worker node；无法记录 worker 结构化汇报".to_string());
    }
    if let Some(dispatch_id) = request.dispatch_id.as_deref() {
        let dispatch = find_workflow_node_dispatch(&value, dispatch_id)
            .ok_or_else(|| "找不到关联 dispatch；无法记录 worker 结构化汇报".to_string())?;
        if optional_string_from(dispatch, "workflow_id").as_deref()
            != Some(request.workflow_id.as_str())
            || optional_string_from(dispatch, "work_item_id").as_deref()
                != Some(request.work_item_id.as_str())
        {
            return Err(
                "关联 dispatch 不属于目标 work item，已拒绝记录 worker 结构化汇报".to_string(),
            );
        }
        let state = optional_string_from(dispatch, "state").unwrap_or_default();
        if !matches!(
            state.as_str(),
            "prepared" | "completed" | "failed" | "timed_out" | "cancelled"
        ) {
            return Err(format!(
                "关联 dispatch 状态 {state} 不能作为 C5 worker 汇报来源"
            ));
        }
    }

    let backup = backup_workflow_state_file(path, &timestamp)?;
    let report_id = format!(
        "worker-report:{}:{}:{}",
        stable_id(&request.work_item_id),
        stable_id(&request.summary),
        timestamp
    );
    array_mut(&mut value, "audit_events")?.push(json!({
      "event_id": report_id,
      "event_type": "worker_structured_report_recorded",
      "target_ref": request.work_item_id,
      "project_id": request.project_id,
      "workflow_id": request.workflow_id,
      "node_id": request.workflow_node_id,
      "work_item_id": request.work_item_id,
      "dispatch_id": request.dispatch_id,
      "actor_ref": request.actor_role,
      "source_kind": "worker_handoff",
      "permission_level": "workflow_event_record",
      "executed_what": request.executed_what.trim(),
      "changed_what": request.changed_what.trim(),
      "reason": request.summary.trim(),
      "evidence_refs": request.evidence_refs,
      "open_issues": request.open_issues,
      "permission_requests": request.permission_requests,
      "direction_risks": request.direction_risks,
      "follow_up_suggestions": request.follow_up_suggestions,
      "acceptance_status": request.acceptance_status.trim(),
      "source_refs": request.source_refs,
      "created_at": timestamp,
      "warnings": [
        "worker_report_is_not_formal_fact",
        "worker_report_is_not_formal_memory",
        "project_director_confirmation_required"
      ]
    }));
    value["updated_at"] = Value::String(timestamp);
    write_validated_workflow_state(path, &value)?;
    let snapshot = read_workflow_state_snapshot(path)?;
    Ok(WorkflowStateMutationResult {
        message: "worker 结构化汇报已记录；仍不是正式事实或正式记忆。".to_string(),
        path: path.display().to_string(),
        backup_path: Some(backup.display().to_string()),
        audit_event_id: report_id,
        first_initialize: false,
        snapshot,
    })
}

fn record_project_director_process_fact_decision_at(
    path: &Path,
    request: &ProjectDirectorProcessFactDecisionInput,
) -> Result<ProjectDirectorProcessFactDecisionResult, String> {
    if !path.exists() {
        return Err("工作流状态文件不存在；无法记录过程事实确认".to_string());
    }
    validate_process_fact_decision_input(request)?;
    let timestamp = unix_timestamp_string();
    let mut value = read_workflow_state_value(path)?;
    if let Some(expected) = request.expected_workflow_revision {
        let current = i64_value(&value, "workflow_version").unwrap_or_default();
        if current != expected {
            return Err(format!(
                "workflow revision 不匹配：expected {expected}, actual {current}"
            ));
        }
    }
    let validation_warnings = validate_workflow_state(&value);
    if !validation_warnings.is_empty() {
        return Err(format!(
            "当前状态文件未通过 schema 校验：{}",
            validation_warnings.join(", ")
        ));
    }
    if !workflow_exists(&value, &request.workflow_id) {
        return Err("当前项目还没有目标 workflow；无法记录过程事实确认".to_string());
    }
    let report = find_worker_report_event(&value, &request.report_id)
        .ok_or_else(|| "找不到 worker 汇报；无法记录过程事实确认".to_string())?
        .clone();
    if optional_string_from(&report, "workflow_id").as_deref() != Some(request.workflow_id.as_str())
    {
        return Err("worker 汇报不属于目标 workflow，已拒绝确认过程事实".to_string());
    }
    if process_fact_decision_exists(&value, &request.report_id, &request.accepted_facts) {
        return Err("process_fact_duplicate: 同一 report / process fact 已确认过".to_string());
    }

    let mut observations = Vec::new();
    let mut observation_store_revision = request.expected_observation_store_revision;
    if request.decision == "confirm_process_fact" {
        for fact in &request.accepted_facts {
            validate_process_fact_candidate(fact, request)?;
            let observation_input = CreateObservationInput {
                project_root: request.project_root.clone(),
                project_id: Some(request.project_id.clone()),
                workflow_id: Some(request.workflow_id.clone()),
                scope: fact.scope.clone(),
                observation_type: fact.proposed_observation_type.clone(),
                summary: fact.summary.trim().to_string(),
                source_refs: fact.source_refs.clone(),
                generated_by_role: "project_director".to_string(),
                actor_id: request.actor_id.clone(),
                risk_level: fact.risk_level.clone(),
                sensitive_level: fact.sensitive_level.clone(),
                reason: request.summary.trim().to_string(),
                expected_store_revision: observation_store_revision,
            };
            let output = create_observation_at(
                path,
                &observation_input,
                &timestamp,
                &format!(
                    "write-c5-process-fact-observation-{}-{}",
                    stable_id(&fact.process_fact_id),
                    unix_timestamp_nanos()
                ),
            )?;
            observation_store_revision = Some(output.store_revision);
            observations.push(output.observation);
        }
    }

    let backup = backup_workflow_state_file(path, &timestamp)?;
    let decision_record_id = format!(
        "process-fact-decision:{}:{}",
        stable_id(&request.report_id),
        timestamp
    );
    let audit_event_id = format!(
        "audit:process-fact-decision:{}:{}",
        stable_id(&request.report_id),
        timestamp
    );
    let observation_ids = observations
        .iter()
        .map(|observation| observation.observation_id.clone())
        .collect::<Vec<_>>();
    let accepted_fact_ids = request
        .accepted_facts
        .iter()
        .map(|fact| fact.process_fact_id.clone())
        .collect::<Vec<_>>();
    let evidence_refs = request
        .accepted_facts
        .iter()
        .flat_map(|fact| fact.evidence_refs.clone())
        .collect::<Vec<_>>();
    array_mut(&mut value, "reviews")?.push(json!({
      "review_id": decision_record_id,
      "project_id": request.project_id,
      "workflow_id": request.workflow_id,
      "work_item_id": optional_string_from(&report, "work_item_id"),
      "dispatch_id": optional_string_from(&report, "dispatch_id"),
      "workflow_node_id": optional_string_from(&report, "node_id"),
      "report_id": request.report_id,
      "reviewer_role": "project_director",
      "decision": request.decision,
      "summary": request.summary.trim(),
      "accepted_fact_ids": accepted_fact_ids,
      "rejected_fact_ids": request.rejected_fact_ids,
      "observation_ids": observation_ids,
      "evidence_refs": evidence_refs,
      "created_at": timestamp,
      "updated_at": timestamp,
      "warnings": [
        "process_fact_observation_is_not_formal_memory",
        "worker_report_not_direct_formal_fact",
        "global_director_final_review_still_required"
      ]
    }));
    array_mut(&mut value, "audit_events")?.push(json!({
      "event_id": audit_event_id,
      "event_type": "project_director_process_fact_decision_recorded",
      "target_ref": request.report_id,
      "project_id": request.project_id,
      "workflow_id": request.workflow_id,
      "actor_ref": request.actor_id,
      "source_kind": "project_director_confirmation",
      "permission_level": "workflow_event_record",
      "decision": request.decision,
      "accepted_fact_ids": request.accepted_facts.iter().map(|fact| fact.process_fact_id.clone()).collect::<Vec<_>>(),
      "rejected_fact_ids": request.rejected_fact_ids,
      "observation_ids": observations.iter().map(|observation| observation.observation_id.clone()).collect::<Vec<_>>(),
      "created_at": timestamp,
      "reason": request.summary.trim()
    }));
    value["updated_at"] = Value::String(timestamp);
    write_validated_workflow_state(path, &value)?;
    let snapshot = read_workflow_state_snapshot(path)?;
    let message = match request.decision.as_str() {
        "confirm_process_fact" => {
            "项目主管已确认过程事实；已记录为观察，仍不是正式记忆。".to_string()
        }
        "request_rework" => "项目主管已要求返工；未写入过程事实 observation。".to_string(),
        "block_and_escalate" => "项目主管已阻断并上报；未写入过程事实 observation。".to_string(),
        _ => "项目主管过程事实决定已记录。".to_string(),
    };
    Ok(ProjectDirectorProcessFactDecisionResult {
        message,
        path: path.display().to_string(),
        backup_path: Some(backup.display().to_string()),
        audit_event_id,
        decision_record_id,
        observations,
        observation_store_revision,
        snapshot,
        warnings: vec![
            "worker_report_not_direct_formal_fact".to_string(),
            "observation_is_not_formal_memory".to_string(),
        ],
    })
}

fn record_global_final_result_review_at(
    path: &Path,
    request: &GlobalFinalResultReviewInput,
) -> Result<WorkflowStateMutationResult, String> {
    if !path.exists() {
        return Err("工作流状态文件不存在；无法记录全局最终复核".to_string());
    }
    validate_global_final_result_review_input(request)?;
    let timestamp = unix_timestamp_string();
    let mut value = read_workflow_state_value(path)?;
    validate_expected_workflow_revision(&value, request.expected_workflow_revision)?;
    let validation_warnings = validate_workflow_state(&value);
    if !validation_warnings.is_empty() {
        return Err(format!(
            "当前状态文件未通过 schema 校验：{}",
            validation_warnings.join(", ")
        ));
    }
    validate_c6_prerequisites_for_final_review(path, &value, request)?;
    let confirmed_fact_ids = confirmed_process_fact_ids_for_workflow(&value, &request.workflow_id);
    if request.decision == "accepted" {
        if request.accepted_process_fact_ids.is_empty() {
            return Err("全局最终复核 accepted 必须引用已确认过程事实".to_string());
        }
        for fact_id in &request.accepted_process_fact_ids {
            if !confirmed_fact_ids
                .iter()
                .any(|confirmed| confirmed == fact_id)
            {
                return Err(format!("全局最终复核引用了未确认的过程事实：{fact_id}"));
            }
        }
        let unresolved = unresolved_process_fact_decisions(&value, &request.workflow_id);
        if !unresolved.is_empty() {
            return Err(format!(
                "仍有返工 / 阻断过程事实未处理，不能记录 accepted：{}",
                unresolved.join("；")
            ));
        }
    }

    let backup = backup_workflow_state_file(path, &timestamp)?;
    let review_id = format!(
        "global-final-review:{}:{}:{}",
        stable_id(&request.workflow_id),
        stable_id(&request.decision),
        timestamp
    );
    let audit_event_id = format!(
        "audit:global-final-review:{}:{}",
        stable_id(&review_id),
        timestamp
    );
    array_mut(&mut value, "reviews")?.push(json!({
      "review_id": review_id,
      "project_id": request.project_id,
      "workflow_id": request.workflow_id,
      "reviewer_role": "global_director",
      "review_target": "global_final_result",
      "proposal_id": request.proposal_id,
      "authorization_id": request.authorization_id,
      "decision": request.decision,
      "summary": request.summary.trim(),
      "accepted_fact_ids": request.accepted_process_fact_ids,
      "observation_ids": [],
      "evidence_refs": request.evidence_refs,
      "open_issues": request.open_issues,
      "deferred_items": request.deferred_items,
      "created_at": timestamp,
      "updated_at": timestamp,
      "warnings": [
        "global_final_review_is_not_user_acceptance",
        "process_fact_observation_is_not_formal_memory",
        "stage_c_acceptance_summary_still_required"
      ]
    }));
    array_mut(&mut value, "audit_events")?.push(json!({
      "event_id": audit_event_id,
      "event_type": "global_final_result_review_recorded",
      "target_ref": request.workflow_id,
      "project_id": request.project_id,
      "workflow_id": request.workflow_id,
      "actor_ref": request.actor_id,
      "source_kind": "global_director_final_review",
      "permission_level": "workflow_event_record",
      "decision": request.decision,
      "review_id": review_id,
      "proposal_id": request.proposal_id,
      "authorization_id": request.authorization_id,
      "accepted_process_fact_ids": request.accepted_process_fact_ids,
      "created_at": timestamp,
      "reason": request.summary.trim()
    }));
    value["updated_at"] = Value::String(timestamp);
    write_validated_workflow_state(path, &value)?;
    let snapshot = read_workflow_state_snapshot(path)?;
    Ok(WorkflowStateMutationResult {
        message: "全局主管已完成最终复核；这不代表用户已接受，也不写正式记忆。".to_string(),
        path: path.display().to_string(),
        backup_path: Some(backup.display().to_string()),
        audit_event_id,
        first_initialize: false,
        snapshot,
    })
}

fn record_user_result_decision_at(
    path: &Path,
    request: &UserResultDecisionInput,
) -> Result<WorkflowStateMutationResult, String> {
    if !path.exists() {
        return Err("工作流状态文件不存在；无法记录用户结果决定".to_string());
    }
    validate_user_result_decision_input(request)?;
    let timestamp = unix_timestamp_string();
    let mut value = read_workflow_state_value(path)?;
    validate_expected_workflow_revision(&value, request.expected_workflow_revision)?;
    let validation_warnings = validate_workflow_state(&value);
    if !validation_warnings.is_empty() {
        return Err(format!(
            "当前状态文件未通过 schema 校验：{}",
            validation_warnings.join(", ")
        ));
    }
    if !workflow_exists(&value, &request.workflow_id) {
        return Err("当前项目还没有目标 workflow；无法记录用户结果决定".to_string());
    }
    let global_review = latest_global_final_review(&value, &request.workflow_id)
        .ok_or_else(|| "缺少全局主管最终复核，不能记录用户结果决定".to_string())?;
    let global_review_id = optional_string_from(global_review, "review_id")
        .unwrap_or_else(|| "global-final-review:missing".to_string());
    if let Some(accepted_review_id) = request.accepted_review_id.as_deref() {
        if accepted_review_id != global_review_id {
            return Err("用户结果决定引用的全局最终复核不是当前最新复核".to_string());
        }
    }
    if request.decision == "accept_result"
        && optional_string_from(global_review, "decision").as_deref() != Some("accepted")
    {
        return Err("全局最终复核未 accepted，用户不能记录接受结果".to_string());
    }

    let backup = backup_workflow_state_file(path, &timestamp)?;
    let decision_id = format!(
        "user-result-decision:{}:{}:{}",
        stable_id(&request.workflow_id),
        stable_id(&request.decision),
        timestamp
    );
    let audit_event_id = format!(
        "audit:user-result-decision:{}:{}",
        stable_id(&decision_id),
        timestamp
    );
    array_mut(&mut value, "reviews")?.push(json!({
      "review_id": decision_id,
      "project_id": request.project_id,
      "workflow_id": request.workflow_id,
      "reviewer_role": "user",
      "review_target": "user_result_decision",
      "accepted_review_id": request.accepted_review_id,
      "decision": request.decision,
      "summary": request.summary.trim(),
      "accepted_fact_ids": [],
      "observation_ids": [],
      "evidence_refs": [global_review_id],
      "requested_changes": request.requested_changes,
      "created_at": timestamp,
      "updated_at": timestamp,
      "warnings": [
        "user_result_decision_is_for_this_result_only",
        "user_decision_does_not_write_formal_memory"
      ]
    }));
    array_mut(&mut value, "audit_events")?.push(json!({
      "event_id": audit_event_id,
      "event_type": "user_result_decision_recorded",
      "target_ref": request.workflow_id,
      "project_id": request.project_id,
      "workflow_id": request.workflow_id,
      "actor_ref": request.actor_id,
      "source_kind": "user_result_view",
      "permission_level": "workflow_event_record",
      "decision": request.decision,
      "accepted_review_id": request.accepted_review_id,
      "created_at": timestamp,
      "reason": request.summary.trim()
    }));
    value["updated_at"] = Value::String(timestamp);
    write_validated_workflow_state(path, &value)?;
    let snapshot = read_workflow_state_snapshot(path)?;
    Ok(WorkflowStateMutationResult {
        message: "用户已查看结果并作出决定；只适用于本次结果，不写正式记忆。".to_string(),
        path: path.display().to_string(),
        backup_path: Some(backup.display().to_string()),
        audit_event_id,
        first_initialize: false,
        snapshot,
    })
}

fn generate_stage_c_acceptance_summary_at(
    path: &Path,
    request: &GenerateStageCAcceptanceSummaryInput,
) -> Result<WorkflowStateMutationResult, String> {
    if !path.exists() {
        return Err("工作流状态文件不存在；无法生成阶段 C 验收摘要".to_string());
    }
    validate_generate_stage_c_acceptance_summary_input(request)?;
    let timestamp = unix_timestamp_string();
    let mut value = read_workflow_state_value(path)?;
    validate_expected_workflow_revision(&value, request.expected_workflow_revision)?;
    let validation_warnings = validate_workflow_state(&value);
    if !validation_warnings.is_empty() {
        return Err(format!(
            "当前状态文件未通过 schema 校验：{}",
            validation_warnings.join(", ")
        ));
    }
    if !workflow_exists(&value, &request.workflow_id) {
        return Err("当前项目还没有目标 workflow；无法生成阶段 C 验收摘要".to_string());
    }
    let summary =
        build_stage_c_acceptance_summary(path, &value, &request.project_id, &request.workflow_id)?;
    let backup = backup_workflow_state_file(path, &timestamp)?;
    let artifact_id = format!(
        "stage-c-acceptance-summary:{}:{}",
        stable_id(&request.workflow_id),
        timestamp
    );
    let audit_event_id = format!(
        "audit:stage-c-acceptance-summary:{}:{}",
        stable_id(&request.workflow_id),
        timestamp
    );
    array_mut(&mut value, "artifacts")?.push(json!({
      "artifact_id": artifact_id,
      "artifact_type": "stage_c_acceptance_summary",
      "project_id": request.project_id,
      "workflow_id": request.workflow_id,
      "source_kind": "stage_c_acceptance",
      "source_ref": request.workflow_id,
      "permission_level": "workflow_event_record",
      "title": "阶段 C 验收摘要",
      "brief": if summary.accepted_as_stage_c_complete { "阶段 C gates 已通过，后置项已列明。" } else { "阶段 C gates 尚未全部通过。" },
      "stage_c_acceptance_summary": summary,
      "created_at": timestamp,
      "updated_at": timestamp,
      "warnings": [
        "stage_c_summary_does_not_complete_middle_version",
        "deferred_items_remain_out_of_scope_for_c6"
      ]
    }));
    array_mut(&mut value, "audit_events")?.push(json!({
      "event_id": audit_event_id,
      "event_type": "stage_c_acceptance_summary_generated",
      "target_ref": request.workflow_id,
      "project_id": request.project_id,
      "workflow_id": request.workflow_id,
      "actor_ref": "control_core",
      "source_kind": "stage_c_acceptance",
      "permission_level": "workflow_event_record",
      "created_at": timestamp,
      "reason": "生成阶段 C 验收 gate 摘要；不执行真实 worker，不写正式记忆。"
    }));
    value["updated_at"] = Value::String(timestamp);
    write_validated_workflow_state(path, &value)?;
    let snapshot = read_workflow_state_snapshot(path)?;
    Ok(WorkflowStateMutationResult {
        message: if snapshot
            .project_workflows
            .iter()
            .find(|workflow| workflow.workflow_id == request.workflow_id)
            .and_then(|workflow| workflow.derived_workflow.as_ref())
            .is_some_and(|workflow| {
                workflow
                    .result_summary
                    .stage_c_acceptance
                    .accepted_as_stage_c_complete
            }) {
            "阶段 C 验收摘要已生成：gates 已通过；这不代表中间版本整体完成。".to_string()
        } else {
            "阶段 C 验收摘要已生成：仍有缺口、修改项、阻断或后置项。".to_string()
        },
        path: path.display().to_string(),
        backup_path: Some(backup.display().to_string()),
        audit_event_id,
        first_initialize: false,
        snapshot,
    })
}

fn validate_expected_workflow_revision(value: &Value, expected: Option<i64>) -> Result<(), String> {
    if let Some(expected) = expected {
        let current = i64_value(value, "workflow_version").unwrap_or_default();
        if current != expected {
            return Err(format!(
                "workflow revision 不匹配：expected {expected}, actual {current}"
            ));
        }
    }
    Ok(())
}

fn validate_global_final_result_review_input(
    request: &GlobalFinalResultReviewInput,
) -> Result<(), String> {
    if request.actor_role != "global_director" {
        return Err("只有全局主管可以记录最终结果复核".to_string());
    }
    for (label, value) in [
        ("project_root", request.project_root.as_str()),
        ("project_id", request.project_id.as_str()),
        ("workflow_id", request.workflow_id.as_str()),
        ("authorization_id", request.authorization_id.as_str()),
        ("proposal_id", request.proposal_id.as_str()),
        ("actor_id", request.actor_id.as_str()),
        ("summary", request.summary.as_str()),
    ] {
        if value.trim().is_empty() {
            return Err(format!("全局最终复核缺少必填字段：{label}"));
        }
    }
    match request.decision.as_str() {
        "accepted" | "needs_changes" | "blocked" => {}
        other => return Err(format!("未知全局最终复核 decision：{other}")),
    }
    if request.evidence_refs.is_empty() {
        return Err("全局最终复核缺少 evidence_refs，已拒绝记录".to_string());
    }
    if matches!(request.decision.as_str(), "needs_changes" | "blocked")
        && request.open_issues.is_empty()
    {
        return Err("needs_changes / blocked 必须写明 open_issues".to_string());
    }
    Ok(())
}

fn validate_user_result_decision_input(request: &UserResultDecisionInput) -> Result<(), String> {
    if request.actor_role != "user" {
        return Err("只有用户可以记录用户结果决定".to_string());
    }
    for (label, value) in [
        ("project_root", request.project_root.as_str()),
        ("project_id", request.project_id.as_str()),
        ("workflow_id", request.workflow_id.as_str()),
        ("actor_id", request.actor_id.as_str()),
        ("summary", request.summary.as_str()),
    ] {
        if value.trim().is_empty() {
            return Err(format!("用户结果决定缺少必填字段：{label}"));
        }
    }
    match request.decision.as_str() {
        "accept_result" | "request_changes" | "reject_result" => {}
        other => return Err(format!("未知用户结果决定：{other}")),
    }
    if matches!(
        request.decision.as_str(),
        "request_changes" | "reject_result"
    ) && request.requested_changes.is_empty()
    {
        return Err("用户要求修改 / 拒绝结果必须写明 requested_changes".to_string());
    }
    Ok(())
}

fn validate_generate_stage_c_acceptance_summary_input(
    request: &GenerateStageCAcceptanceSummaryInput,
) -> Result<(), String> {
    for (label, value) in [
        ("project_root", request.project_root.as_str()),
        ("project_id", request.project_id.as_str()),
        ("workflow_id", request.workflow_id.as_str()),
    ] {
        if value.trim().is_empty() {
            return Err(format!("阶段 C 验收摘要缺少必填字段：{label}"));
        }
    }
    Ok(())
}

fn validate_c6_prerequisites_for_final_review(
    path: &Path,
    value: &Value,
    request: &GlobalFinalResultReviewInput,
) -> Result<(), String> {
    if !workflow_exists(value, &request.workflow_id) {
        return Err("当前项目还没有目标 workflow；无法记录全局最终复核".to_string());
    }
    let timestamp_ms = unix_timestamp_ms();
    let proposal_store = project_consultation_proposal_store::load_store(path, timestamp_ms)?;
    let proposal = proposal_store
        .proposals
        .iter()
        .find(|proposal| proposal.proposal_id == request.proposal_id)
        .ok_or_else(|| format!("找不到 C2 项目咨询方案：{}", request.proposal_id))?;
    if proposal.project_id != request.project_id || proposal.workflow_id != request.workflow_id {
        return Err("C2 proposal 不属于目标 project/workflow".to_string());
    }
    if proposal.status != ProjectConsultationProposalStatus::UserConfirmed {
        return Err("C2 proposal 尚未由用户确认，不能记录全局最终复核".to_string());
    }
    if proposal.plan_authorization_id.as_deref() != Some(request.authorization_id.as_str()) {
        return Err("C2 proposal 与 C1 authorization 回链不匹配".to_string());
    }

    let authorization_store = plan_authorization_store::load_store(path, timestamp_ms)?;
    let authorization = authorization_store
        .authorizations
        .iter()
        .find(|authorization| authorization.authorization_id == request.authorization_id)
        .ok_or_else(|| format!("找不到 C1 方案授权对象：{}", request.authorization_id))?;
    if authorization.project_id != request.project_id
        || authorization.workflow_id != request.workflow_id
    {
        return Err("C1 authorization 不属于目标 project/workflow".to_string());
    }
    if authorization.source_proposal_id.as_deref() != Some(request.proposal_id.as_str()) {
        return Err("C1 authorization source_proposal_id 与 C2 proposal 不匹配".to_string());
    }
    if authorization.user_confirmation.is_none() {
        return Err("C1 authorization 缺少用户确认，不能记录全局最终复核".to_string());
    }
    if authorization.status != PlanAuthorizationStatus::Active {
        return Err("C3 全局边界复核未让 authorization active，不能记录最终复核".to_string());
    }
    if !authorization
        .global_boundary_review
        .as_ref()
        .is_some_and(|review| review.status == "approved")
    {
        return Err("缺少 C3 approved global boundary review".to_string());
    }
    if !has_c4_prepared_dispatch(value, &request.workflow_id, &request.authorization_id) {
        return Err("缺少 C4 prepared dispatch 记录，不能记录全局最终复核".to_string());
    }
    if !has_c4_task_package_artifact(value, &request.workflow_id) {
        return Err("缺少 C4 task package artifact，不能记录全局最终复核".to_string());
    }
    if !has_worker_report_for_workflow(value, &request.workflow_id) {
        return Err("缺少 C5 worker 结构化汇报，不能记录全局最终复核".to_string());
    }
    if !has_process_fact_decision_for_workflow(value, &request.workflow_id) {
        return Err("缺少 C5 项目主管过程事实决定，不能记录全局最终复核".to_string());
    }
    Ok(())
}

fn has_c4_prepared_dispatch(value: &Value, workflow_id: &str, authorization_id: &str) -> bool {
    value
        .get("workflow_node_dispatches")
        .and_then(Value::as_array)
        .is_some_and(|dispatches| {
            dispatches.iter().any(|dispatch| {
                optional_string_from(dispatch, "workflow_id").as_deref() == Some(workflow_id)
                    && optional_string_from(dispatch, "plan_authorization_id").as_deref()
                        == Some(authorization_id)
                    && matches!(
                        optional_string_from(dispatch, "state").as_deref(),
                        Some("prepared" | "completed" | "failed" | "timed_out" | "cancelled")
                    )
            })
        })
}

fn has_c4_task_package_artifact(value: &Value, workflow_id: &str) -> bool {
    value
        .get("artifacts")
        .and_then(Value::as_array)
        .is_some_and(|artifacts| {
            artifacts.iter().any(|artifact| {
                artifact_belongs_to_workflow(value, artifact, workflow_id)
                    && optional_string_from(artifact, "artifact_type").as_deref()
                        == Some("task_package")
                    && optional_string_from(artifact, "source_kind").as_deref()
                        == Some("project_director_task_plan")
            })
        })
}

fn artifact_belongs_to_workflow(value: &Value, artifact: &Value, workflow_id: &str) -> bool {
    if optional_string_from(artifact, "workflow_id").as_deref() == Some(workflow_id) {
        return true;
    }
    optional_string_from(artifact, "source_ref")
        .as_deref()
        .is_some_and(|source_ref| find_work_item(value, workflow_id, source_ref).is_some())
}

fn has_worker_report_for_workflow(value: &Value, workflow_id: &str) -> bool {
    value
        .get("audit_events")
        .and_then(Value::as_array)
        .is_some_and(|events| {
            events.iter().any(|event| {
                optional_string_from(event, "workflow_id").as_deref() == Some(workflow_id)
                    && matches!(
                        optional_string_from(event, "event_type").as_deref(),
                        Some("worker_structured_report_recorded" | "subagent_report")
                    )
            })
        })
}

fn process_fact_reviews_for_workflow<'a>(value: &'a Value, workflow_id: &str) -> Vec<&'a Value> {
    value
        .get("reviews")
        .and_then(Value::as_array)
        .map(|reviews| {
            reviews
                .iter()
                .filter(|review| {
                    optional_string_from(review, "workflow_id").as_deref() == Some(workflow_id)
                        && optional_string_from(review, "reviewer_role").as_deref()
                            == Some("project_director")
                        && matches!(
                            optional_string_from(review, "decision").as_deref(),
                            Some("confirm_process_fact" | "request_rework" | "block_and_escalate")
                        )
                })
                .collect::<Vec<_>>()
        })
        .unwrap_or_default()
}

fn has_process_fact_decision_for_workflow(value: &Value, workflow_id: &str) -> bool {
    !process_fact_reviews_for_workflow(value, workflow_id).is_empty()
}

fn confirmed_process_fact_ids_for_workflow(value: &Value, workflow_id: &str) -> Vec<String> {
    process_fact_reviews_for_workflow(value, workflow_id)
        .into_iter()
        .filter(|review| {
            optional_string_from(review, "decision").as_deref() == Some("confirm_process_fact")
        })
        .flat_map(|review| string_array(review, "accepted_fact_ids"))
        .collect()
}

fn unresolved_process_fact_decisions(value: &Value, workflow_id: &str) -> Vec<String> {
    process_fact_reviews_for_workflow(value, workflow_id)
        .into_iter()
        .filter(|review| {
            matches!(
                optional_string_from(review, "decision").as_deref(),
                Some("request_rework" | "block_and_escalate")
            )
        })
        .filter_map(|review| {
            let decision = optional_string_from(review, "decision")?;
            let summary = optional_string_from(review, "summary").unwrap_or_default();
            Some(format!("{decision}: {summary}"))
        })
        .collect()
}

fn latest_global_final_review<'a>(value: &'a Value, workflow_id: &str) -> Option<&'a Value> {
    value
        .get("reviews")
        .and_then(Value::as_array)
        .and_then(|reviews| {
            reviews.iter().rev().find(|review| {
                optional_string_from(review, "workflow_id").as_deref() == Some(workflow_id)
                    && optional_string_from(review, "reviewer_role").as_deref()
                        == Some("global_director")
                    && optional_string_from(review, "review_target").as_deref()
                        == Some("global_final_result")
            })
        })
}

fn latest_user_result_decision<'a>(value: &'a Value, workflow_id: &str) -> Option<&'a Value> {
    value
        .get("reviews")
        .and_then(Value::as_array)
        .and_then(|reviews| {
            reviews.iter().rev().find(|review| {
                optional_string_from(review, "workflow_id").as_deref() == Some(workflow_id)
                    && optional_string_from(review, "reviewer_role").as_deref() == Some("user")
                    && optional_string_from(review, "review_target").as_deref()
                        == Some("user_result_decision")
            })
        })
}

fn latest_stage_c_acceptance_artifact<'a>(
    artifacts: &'a [Value],
    workflow_id: &str,
) -> Option<&'a Value> {
    artifacts.iter().rev().find(|artifact| {
        optional_string_from(artifact, "workflow_id").as_deref() == Some(workflow_id)
            && optional_string_from(artifact, "artifact_type").as_deref()
                == Some("stage_c_acceptance_summary")
    })
}

fn build_stage_c_acceptance_summary(
    path: &Path,
    value: &Value,
    project_id_value: &str,
    workflow_id: &str,
) -> Result<StageCAcceptanceSummary, String> {
    let timestamp_ms = unix_timestamp_ms();
    let proposal_store = project_consultation_proposal_store::load_store(path, timestamp_ms)?;
    let authorization_store = plan_authorization_store::load_store(path, timestamp_ms)?;
    let proposal = proposal_store
        .proposals
        .iter()
        .filter(|proposal| {
            proposal.project_id == project_id_value && proposal.workflow_id == workflow_id
        })
        .last();
    let authorization = proposal
        .and_then(|proposal| proposal.plan_authorization_id.as_deref())
        .and_then(|authorization_id| {
            authorization_store
                .authorizations
                .iter()
                .find(|authorization| authorization.authorization_id == authorization_id)
        })
        .or_else(|| {
            authorization_store
                .authorizations
                .iter()
                .filter(|authorization| {
                    authorization.project_id == project_id_value
                        && authorization.workflow_id == workflow_id
                })
                .rev()
                .find(|authorization| authorization.status == PlanAuthorizationStatus::Active)
        });
    let authorization_id = authorization
        .map(|authorization| authorization.authorization_id.as_str())
        .unwrap_or("");
    let final_review = latest_global_final_review(value, workflow_id);
    let user_decision = latest_user_result_decision(value, workflow_id);
    let final_review_status = final_review
        .and_then(|review| optional_string_from(review, "decision"))
        .unwrap_or_else(|| "pending".to_string());
    let user_decision_status = user_decision
        .and_then(|review| optional_string_from(review, "decision"))
        .unwrap_or_else(|| "pending".to_string());
    let process_decisions = process_fact_reviews_for_workflow(value, workflow_id);
    let mut gates = Vec::new();
    gates.push(stage_c_gate(
        "c1-plan-authorization",
        "C1 方案授权",
        if authorization.is_some_and(|authorization| authorization.user_confirmation.is_some()) {
            "passed"
        } else {
            "missing_evidence"
        },
        if let Some(authorization) = authorization {
            format!(
                "authorization {} / status {:?}",
                authorization.authorization_id, authorization.status
            )
        } else {
            "缺少方案授权对象或用户确认。".to_string()
        },
        authorization
            .map(|authorization| vec![authorization.authorization_id.clone()])
            .unwrap_or_default(),
    ));
    gates.push(stage_c_gate(
        "c2-user-confirmed-proposal",
        "C2 用户确认方案",
        if proposal.is_some_and(|proposal| {
            proposal.status == ProjectConsultationProposalStatus::UserConfirmed
        }) {
            "passed"
        } else {
            "missing_evidence"
        },
        if let Some(proposal) = proposal {
            format!(
                "proposal {} / status {:?}",
                proposal.proposal_id, proposal.status
            )
        } else {
            "缺少用户确认过的项目咨询方案。".to_string()
        },
        proposal
            .map(|proposal| vec![proposal.proposal_id.clone()])
            .unwrap_or_default(),
    ));
    gates.push(stage_c_gate(
        "c3-global-boundary-review",
        "C3 全局边界复核",
        if authorization.is_some_and(|authorization| {
            authorization.status == PlanAuthorizationStatus::Active
                && authorization
                    .global_boundary_review
                    .as_ref()
                    .is_some_and(|review| review.status == "approved")
        }) {
            "passed"
        } else {
            "missing_evidence"
        },
        "authorization 必须 active 且 global boundary review 为 approved。".to_string(),
        authorization
            .map(|authorization| vec![authorization.authorization_id.clone()])
            .unwrap_or_default(),
    ));
    gates.push(stage_c_gate(
        "c4-prepared-dispatch",
        "C4 项目主管拆任务 / prepared dispatch",
        if has_c4_prepared_dispatch(value, workflow_id, authorization_id)
            && has_c4_task_package_artifact(value, workflow_id)
        {
            "passed"
        } else {
            "missing_evidence"
        },
        "需要 task package artifact 和 prepared dispatch 记录。".to_string(),
        evidence_refs_for_c4(value, workflow_id),
    ));
    let c5_status = if process_decisions.iter().any(|review| {
        optional_string_from(review, "decision").as_deref() == Some("block_and_escalate")
    }) {
        "blocked"
    } else if process_decisions
        .iter()
        .any(|review| optional_string_from(review, "decision").as_deref() == Some("request_rework"))
    {
        "needs_changes"
    } else if has_worker_report_for_workflow(value, workflow_id)
        && process_decisions.iter().any(|review| {
            optional_string_from(review, "decision").as_deref() == Some("confirm_process_fact")
        })
    {
        "passed"
    } else {
        "missing_evidence"
    };
    gates.push(stage_c_gate(
        "c5-worker-report-process-fact",
        "C5 worker 汇报 / 过程事实确认",
        c5_status,
        "worker report 必须由项目主管确认过程事实；observation 仍不是正式记忆。".to_string(),
        evidence_refs_for_c5(value, workflow_id),
    ));
    gates.push(stage_c_gate(
        "c6-global-final-review",
        "C6 全局最终复核",
        match final_review_status.as_str() {
            "accepted" => "passed",
            "needs_changes" => "needs_changes",
            "blocked" => "blocked",
            _ => "missing_evidence",
        },
        "全局主管最终复核不能代表用户已接受。".to_string(),
        final_review
            .and_then(|review| optional_string_from(review, "review_id"))
            .into_iter()
            .collect(),
    ));
    gates.push(stage_c_gate(
        "c6-user-result-decision",
        "C6 用户结果决定",
        match user_decision_status.as_str() {
            "accept_result" => "passed",
            "request_changes" => "needs_changes",
            "reject_result" => "blocked",
            _ => "missing_evidence",
        },
        "用户决定只适用于本次结果，不代表未来任务默认接受。".to_string(),
        user_decision
            .and_then(|review| optional_string_from(review, "review_id"))
            .into_iter()
            .collect(),
    ));
    gates.push(stage_c_gate(
        "stage-c-deferred-real-worker",
        "后置：真实 worker / Codex 执行",
        "deferred",
        "C6 默认不执行真实 worker、codex exec 或 codex exec resume。".to_string(),
        vec![],
    ));
    gates.push(stage_c_gate(
        "stage-c-deferred-ops-tauri-retry",
        "后置：真实 Tauri 全面验收 / 自动重试 / 运维日志",
        "deferred",
        "真实窗口全面验收、完整自动重试和运行日志体系后续单独拆任务。".to_string(),
        vec![],
    ));

    let deferred_items = dedupe_strings({
        let mut items = vec![
            "真实 worker / Codex 执行仍需单独授权任务包。".to_string(),
            "真实 Tauri 全面截图验收仍是后置项。".to_string(),
            "完整自动重试、运行日志和运维诊断仍是后置项。".to_string(),
            "M7-M13 完整记忆系统仍未完成。".to_string(),
        ];
        if let Some(review) = final_review {
            items.extend(string_array(review, "deferred_items"));
        }
        items
    });
    let open_blockers = gates
        .iter()
        .filter(|gate| !matches!(gate.status.as_str(), "passed" | "deferred"))
        .map(|gate| format!("{}：{}", gate.label, gate.reason))
        .collect::<Vec<_>>();
    let accepted_as_stage_c_complete = open_blockers.is_empty()
        && final_review_status == "accepted"
        && user_decision_status == "accept_result";
    Ok(StageCAcceptanceSummary {
        project_id: project_id_value.to_string(),
        workflow_id: workflow_id.to_string(),
        gates,
        final_review_status,
        user_decision_status,
        accepted_as_stage_c_complete,
        deferred_items,
        open_blockers,
        warnings: vec![
            "stage_c_acceptance_does_not_complete_middle_version".to_string(),
            "process_fact_observation_is_not_formal_memory".to_string(),
        ],
    })
}

fn stage_c_gate(
    gate_id: &str,
    label: &str,
    status: &str,
    reason: String,
    evidence_refs: Vec<String>,
) -> StageCAcceptanceGate {
    StageCAcceptanceGate {
        gate_id: gate_id.to_string(),
        label: label.to_string(),
        status: status.to_string(),
        reason,
        evidence_refs,
    }
}

fn evidence_refs_for_c4(value: &Value, workflow_id: &str) -> Vec<String> {
    let mut refs = Vec::new();
    if let Some(dispatches) = value
        .get("workflow_node_dispatches")
        .and_then(Value::as_array)
    {
        refs.extend(dispatches.iter().filter_map(|dispatch| {
            (optional_string_from(dispatch, "workflow_id").as_deref() == Some(workflow_id))
                .then(|| optional_string_from(dispatch, "dispatch_id"))
                .flatten()
        }));
    }
    if let Some(artifacts) = value.get("artifacts").and_then(Value::as_array) {
        refs.extend(artifacts.iter().filter_map(|artifact| {
            (artifact_belongs_to_workflow(value, artifact, workflow_id)
                && optional_string_from(artifact, "artifact_type").as_deref()
                    == Some("task_package"))
            .then(|| optional_string_from(artifact, "artifact_id"))
            .flatten()
        }));
    }
    dedupe_strings(refs)
}

fn evidence_refs_for_c5(value: &Value, workflow_id: &str) -> Vec<String> {
    let mut refs = Vec::new();
    if let Some(events) = value.get("audit_events").and_then(Value::as_array) {
        refs.extend(events.iter().filter_map(|event| {
            (optional_string_from(event, "workflow_id").as_deref() == Some(workflow_id)
                && optional_string_from(event, "event_type").as_deref()
                    == Some("worker_structured_report_recorded"))
            .then(|| optional_string_from(event, "event_id"))
            .flatten()
        }));
    }
    refs.extend(
        process_fact_reviews_for_workflow(value, workflow_id)
            .into_iter()
            .filter_map(|review| optional_string_from(review, "review_id")),
    );
    dedupe_strings(refs)
}

fn validate_worker_structured_report_input(
    request: &WorkerStructuredReportInput,
) -> Result<(), String> {
    for (label, value) in [
        ("project_root", request.project_root.as_str()),
        ("project_id", request.project_id.as_str()),
        ("workflow_id", request.workflow_id.as_str()),
        ("workflow_node_id", request.workflow_node_id.as_str()),
        ("work_item_id", request.work_item_id.as_str()),
        ("actor_role", request.actor_role.as_str()),
        ("executed_what", request.executed_what.as_str()),
        ("changed_what", request.changed_what.as_str()),
        ("summary", request.summary.as_str()),
        ("acceptance_status", request.acceptance_status.as_str()),
    ] {
        if value.trim().is_empty() {
            return Err(format!("worker report 缺少必填字段：{label}"));
        }
    }
    if request.evidence_refs.is_empty() {
        return Err("worker report 缺少 evidence_refs，已拒绝记录".to_string());
    }
    if request.source_refs.is_empty() {
        return Err("worker report 缺少 source_refs，已拒绝记录".to_string());
    }
    if request.summary.len() > 1200
        || request.executed_what.len() > 1200
        || request.changed_what.len() > 1200
    {
        return Err("worker report 字段过长；不能存入长日志或 raw transcript".to_string());
    }
    match request.acceptance_status.as_str() {
        "reported_completed" | "reported_not_completed" | "blocked" | "needs_rework" => {}
        other => return Err(format!("未知 worker report acceptance_status：{other}")),
    }
    for source in &request.source_refs {
        validate_c5_source_ref(source)?;
    }
    Ok(())
}

fn validate_c5_source_ref(source: &ObservationSourceRef) -> Result<(), String> {
    if source.source_id.trim().is_empty() || source.summary.trim().is_empty() {
        return Err("source_ref 缺少 source_id 或 summary".to_string());
    }
    match source.source_kind.as_str() {
        "workflow_event" | "worker_report" | "director_review" | "task_package" | "evidence"
        | "handoff" | "user_confirmation" => Ok(()),
        "ordinary_chat" | "chat" => {
            Err("普通聊天来源不能作为 C5 worker report / process fact 来源".to_string())
        }
        other => Err(format!("不支持的 C5 source_kind：{other}")),
    }
}

fn validate_process_fact_decision_input(
    request: &ProjectDirectorProcessFactDecisionInput,
) -> Result<(), String> {
    if request.actor_role != "project_director" {
        return Err("只有项目主管可以确认 worker 汇报中的过程事实".to_string());
    }
    if request.summary.trim().is_empty() {
        return Err("过程事实决定 summary 不能为空".to_string());
    }
    match request.decision.as_str() {
        "confirm_process_fact" => {
            if request.accepted_facts.is_empty() {
                return Err("确认过程事实至少需要一个 accepted_fact".to_string());
            }
        }
        "request_rework" | "block_and_escalate" => {}
        other => return Err(format!("未知过程事实决定：{other}")),
    }
    Ok(())
}

fn validate_process_fact_candidate(
    fact: &ProcessFactCandidate,
    request: &ProjectDirectorProcessFactDecisionInput,
) -> Result<(), String> {
    if fact.process_fact_id.trim().is_empty() || fact.summary.trim().is_empty() {
        return Err("process fact 缺少 id 或 summary".to_string());
    }
    if fact.source_report_id != request.report_id {
        return Err("process fact source_report_id 与当前 report 不匹配".to_string());
    }
    if fact.evidence_refs.is_empty() || fact.source_refs.is_empty() {
        return Err("process fact 缺少 evidence_refs 或 source_refs".to_string());
    }
    if fact.risk_level != "low" {
        return Err(
            "high / medium risk process fact 需要用户或更高层确认，项目主管不能单独确认"
                .to_string(),
        );
    }
    if fact.sensitive_level == "secret" || fact.sensitive_level == "sensitive" {
        return Err(
            "secret / sensitive process fact 需要用户确认，项目主管不能单独确认".to_string(),
        );
    }
    if fact.scope.project_id.as_deref() != Some(request.project_id.as_str()) {
        return Err("cross-project process fact 需要用户确认，项目主管不能单独确认".to_string());
    }
    if fact.scope.workflow_id.as_deref() != Some(request.workflow_id.as_str()) {
        return Err("process fact workflow scope 与当前 workflow 不匹配".to_string());
    }
    if fact.proposed_observation_type != "process_fact"
        && fact.proposed_observation_type != "worker_report"
    {
        return Err(
            "process fact observation_type 必须是 process_fact 或 worker_report".to_string(),
        );
    }
    for source in &fact.source_refs {
        validate_c5_source_ref(source)?;
    }
    Ok(())
}

fn find_worker_report_event<'a>(value: &'a Value, report_id: &str) -> Option<&'a Value> {
    value
        .get("audit_events")
        .and_then(Value::as_array)
        .and_then(|events| {
            events.iter().find(|event| {
                optional_string_from(event, "event_id").as_deref() == Some(report_id)
                    && matches!(
                        optional_string_from(event, "event_type").as_deref(),
                        Some("worker_structured_report_recorded") | Some("subagent_report")
                    )
            })
        })
}

fn process_fact_decision_exists(
    value: &Value,
    report_id: &str,
    facts: &[ProcessFactCandidate],
) -> bool {
    value
        .get("reviews")
        .and_then(Value::as_array)
        .is_some_and(|reviews| {
            reviews.iter().any(|review| {
                optional_string_from(review, "report_id").as_deref() == Some(report_id)
                    && optional_string_from(review, "reviewer_role").as_deref()
                        == Some("project_director")
                    && facts.iter().any(|fact| {
                        string_array(review, "accepted_fact_ids")
                            .iter()
                            .any(|id| id == &fact.process_fact_id)
                    })
            })
        })
}

fn read_c4_workflow_value(
    path: &Path,
    project_root_value: &str,
    workflow_id: &str,
) -> Result<Value, String> {
    if !path.exists() {
        return Err("工作流状态文件不存在；无法做项目主管拆任务。".to_string());
    }
    let value = read_workflow_state_value(path)?;
    let validation_warnings = validate_workflow_state(&value);
    if !validation_warnings.is_empty() {
        return Err(format!(
            "当前状态文件未通过 schema 校验：{}",
            validation_warnings.join(", ")
        ));
    }
    if !workflow_exists(&value, workflow_id) {
        return Err("当前项目还没有匹配 workflow；无法做项目主管拆任务。".to_string());
    }
    let expected_project_id = project_id(project_root_value);
    if !project_exists(&value, &expected_project_id) {
        return Err("workflow state 缺少当前项目记录；无法做项目主管拆任务。".to_string());
    }
    Ok(value)
}

fn project_director_authorization_context(
    path: &Path,
    index: &Value,
    project_root_value: &str,
    project_id_value: &str,
    workflow_id: &str,
    proposal_id: &str,
    authorization_id: &str,
    expected_authorization_revision: Option<i64>,
) -> Result<ProjectDirectorAuthorizationContext, String> {
    let project = find_index_project(index, project_root_value)
        .ok_or_else(|| "项目不在当前索引内，已拒绝项目主管拆任务。".to_string())?;
    let expected_project_id = project_id(project_root_value);
    let expected_workflow_id = default_workflow_id(project_root_value);
    if project_id_value != expected_project_id {
        return Err("C4 输入 project_id 与 project_root 推导结果不一致。".to_string());
    }
    if workflow_id != expected_workflow_id {
        return Err("C4 输入 workflow_id 与 project_root 默认 workflow 不一致。".to_string());
    }
    let timestamp_ms = unix_timestamp_ms();
    let proposal_store = project_consultation_proposal_store::load_store(path, timestamp_ms)?;
    let proposal = proposal_store
        .proposals
        .iter()
        .find(|proposal| proposal.proposal_id == proposal_id)
        .cloned()
        .ok_or_else(|| format!("找不到项目咨询方案：{proposal_id}"))?;
    if proposal.status != ProjectConsultationProposalStatus::UserConfirmed {
        return Err("项目咨询方案尚未由用户确认，不能做项目主管拆任务。".to_string());
    }
    if proposal.project_id != project_id_value || proposal.workflow_id != workflow_id {
        return Err("项目咨询方案与 C4 输入 project_id / workflow_id 不一致。".to_string());
    }
    if proposal.plan_authorization_id.as_deref() != Some(authorization_id) {
        return Err("项目咨询方案缺少匹配的 C1 授权回链，不能做项目主管拆任务。".to_string());
    }

    let authorization_store = plan_authorization_store::load_store(path, timestamp_ms)?;
    if let Some(expected) = expected_authorization_revision {
        if authorization_store.revision != expected {
            return Err(format!(
                "方案授权 revision 不匹配：expected {expected}, actual {}",
                authorization_store.revision
            ));
        }
    }
    let authorization = authorization_store
        .authorizations
        .iter()
        .find(|authorization| authorization.authorization_id == authorization_id)
        .cloned()
        .ok_or_else(|| format!("找不到方案授权对象：{authorization_id}"))?;
    if authorization.project_id != project_id_value || authorization.workflow_id != workflow_id {
        return Err("方案授权对象与 C4 输入 project_id / workflow_id 不一致。".to_string());
    }
    if authorization.source_proposal_id.as_deref() != Some(proposal_id) {
        return Err("方案授权 source_proposal_id 与项目咨询方案不匹配。".to_string());
    }
    if authorization.status != PlanAuthorizationStatus::Active
        || authorization.user_confirmation.is_none()
        || !authorization
            .global_boundary_review
            .as_ref()
            .is_some_and(|review| review.status == "approved")
    {
        return Err("方案授权尚未 active 或缺少 C3 approved 全局边界复核。".to_string());
    }

    Ok(ProjectDirectorAuthorizationContext {
        project,
        proposal,
        authorization,
        authorization_store,
    })
}

fn deterministic_project_director_planned_tasks(
    context: &ProjectDirectorAuthorizationContext,
) -> Vec<ProjectDirectorPlannedTask> {
    let scope = &context.authorization.scope;
    let target_role = scope
        .allowed_role_ids
        .iter()
        .find(|role| {
            !matches!(
                normalize_c4_symbol(role).as_str(),
                "project_director" | "director" | "global_director"
            )
        })
        .or_else(|| scope.allowed_role_ids.first())
        .cloned()
        .unwrap_or_else(|| "codex-dev".to_string());
    let task_package_kind = scope
        .allowed_task_package_kinds
        .first()
        .cloned()
        .unwrap_or_else(|| "task_package".to_string());
    let planned_task_id = format!(
        "project-director-planned-task:{}",
        stable_id(&format!(
            "{}:{}:{}:{}",
            context.authorization.authorization_id,
            context.proposal.proposal_id,
            target_role,
            context.proposal.goal_summary
        ))
    );
    let objective = format!(
        "{}\n\n{}",
        context.proposal.goal_summary,
        context
            .proposal
            .proposed_steps
            .iter()
            .enumerate()
            .map(|(index, step)| format!("{}. {}", index + 1, step))
            .collect::<Vec<_>>()
            .join("\n")
    )
    .trim()
    .to_string();
    let stop_conditions = scope
        .stop_conditions
        .iter()
        .map(|condition| condition.summary.clone())
        .collect::<Vec<_>>();
    vec![ProjectDirectorPlannedTask {
        planned_task_id,
        title: format!("执行已授权方案：{}", context.proposal.title),
        objective,
        scope: ProjectDirectorTaskScope {
            project_id: scope.project_id.clone(),
            workflow_id: scope.workflow_id.clone(),
            target_role,
            task_package_kind,
            allowed_read_scope: scope.allowed_read_roots.clone(),
            allowed_write_scope: scope.allowed_write_roots.clone(),
            callable_tool_capabilities: scope.allowed_tools.clone(),
            required_checks: scope.allowed_checks.clone(),
            stop_conditions,
        },
        depends_on: vec![],
        acceptance_criteria: if context.proposal.acceptance_criteria.is_empty() {
            vec!["按任务包完成工作，并以结构化汇报返回证据、风险和后续建议。".to_string()]
        } else {
            context.proposal.acceptance_criteria.clone()
        },
        report_format: standard_project_director_report_format(),
        status: "draft".to_string(),
        guard_result: None,
        work_item_id: None,
        workflow_node_id: None,
        task_package_id: None,
        memory_packet_snapshot_id: None,
        prepared_dispatch_id: None,
        blocked_reasons: vec![],
    }]
}

fn annotate_project_director_planned_tasks(
    index: &Value,
    value: &Value,
    context: &ProjectDirectorAuthorizationContext,
    tasks: Vec<ProjectDirectorPlannedTask>,
    timestamp_ms: i64,
) -> Vec<ProjectDirectorPlannedTask> {
    tasks
        .into_iter()
        .map(|mut task| {
            let work_item_id =
                c4_work_item_id(&context.authorization.workflow_id, &task.planned_task_id);
            let artifact_id = c4_task_package_artifact_id(
                &context.authorization.workflow_id,
                &task.planned_task_id,
            );
            let node_id = c4_node_id(&context.authorization.workflow_id, &task.scope.target_role);
            task.work_item_id = Some(work_item_id.clone());
            task.task_package_id = Some(artifact_id.clone());
            task.workflow_node_id = Some(node_id.clone());
            task.blocked_reasons = c4_static_task_blocking_reasons(&task);

            let binding = active_binding_for_planned_task(index, value, &node_id, &work_item_id);
            let target_agent_id = binding
                .as_ref()
                .map(|binding| binding.native_thread_id.clone())
                .or_else(|| {
                    context
                        .authorization
                        .scope
                        .allowed_agent_ids
                        .first()
                        .cloned()
                });
            let guard_input = AutoDispatchGuardInput {
                project_id: context.authorization.project_id.clone(),
                workflow_id: context.authorization.workflow_id.clone(),
                work_item_id: work_item_id.clone(),
                task_package_id: Some(artifact_id),
                task_package_kind: Some(task.scope.task_package_kind.clone()),
                target_role_id: task.scope.target_role.clone(),
                target_agent_id,
                requested_read_roots: task.scope.allowed_read_scope.clone(),
                requested_write_roots: task.scope.allowed_write_scope.clone(),
                requested_tools: task.scope.callable_tool_capabilities.clone(),
                requested_checks: task.scope.required_checks.clone(),
                triggered_stop_conditions: vec![],
                dispatch_kind: "prepare_real".to_string(),
            };
            let guard_result = control_core::inspect_auto_dispatch_scope(
                &context.authorization_store,
                &guard_input,
                timestamp_ms,
            );
            if guard_result.status != "authorized" {
                task.blocked_reasons.extend(guard_result.reasons.clone());
            }
            task.guard_result = Some(guard_result);

            if let Some(artifact) = find_task_package_artifact_by_id(value, &work_item_id) {
                if let Some(snapshot) = task_memory_injection::snapshot_from_artifact(artifact) {
                    task.memory_packet_snapshot_id = Some(snapshot.snapshot_id);
                }
            }
            if let Some(dispatch) = existing_prepared_dispatch_for_planned_task(
                value,
                &task.planned_task_id,
                &work_item_id,
                &context.authorization.authorization_id,
            ) {
                task.prepared_dispatch_id = optional_string_from(dispatch, "dispatch_id");
                task.status = "prepared".to_string();
            } else if !task.blocked_reasons.is_empty() {
                task.status = "blocked".to_string();
            } else if binding.is_none() {
                task.status = "needs_binding".to_string();
                push_unique(&mut task.blocked_reasons, "等待绑定会话后才能准备派发。");
            } else if binding
                .as_ref()
                .is_some_and(|binding| !binding.rollout_exists)
            {
                task.status = "needs_binding".to_string();
                push_unique(
                    &mut task.blocked_reasons,
                    "绑定会话 rollout 不可用，等待重新绑定。",
                );
            } else {
                task.status = "authorized".to_string();
            }
            task.blocked_reasons = dedupe_strings(task.blocked_reasons);
            task
        })
        .collect()
}

fn project_director_task_plan_from_tasks(
    project_root_value: &str,
    project_id_value: &str,
    workflow_id: &str,
    proposal_id: &str,
    authorization_id: &str,
    actor_id: &str,
    tasks: Vec<ProjectDirectorPlannedTask>,
    value: &Value,
) -> ProjectDirectorTaskPlan {
    let planned_task_count = tasks.len();
    let prepared_dispatch_count = tasks
        .iter()
        .filter(|task| task.status == "prepared")
        .count();
    let needs_binding_count = tasks
        .iter()
        .filter(|task| task.status == "needs_binding")
        .count();
    let blocked_count = tasks.iter().filter(|task| task.status == "blocked").count();
    let authorized_task_count = tasks
        .iter()
        .filter(|task| {
            task.guard_result
                .as_ref()
                .is_some_and(|guard| guard.status == "authorized")
        })
        .count();
    let blocked_reasons = dedupe_strings(
        tasks
            .iter()
            .flat_map(|task| task.blocked_reasons.clone())
            .take(6)
            .collect(),
    );
    let memory_snapshot_summary = aggregate_project_director_memory_summary(value, &tasks);
    ProjectDirectorTaskPlan {
        project_root: project_root_value.to_string(),
        project_id: project_id_value.to_string(),
        workflow_id: workflow_id.to_string(),
        proposal_id: proposal_id.to_string(),
        authorization_id: authorization_id.to_string(),
        actor_id: actor_id.to_string(),
        planned_tasks: tasks,
        planned_task_count,
        authorized_task_count,
        prepared_dispatch_count,
        blocked_count,
        needs_binding_count,
        blocked_reasons,
        memory_snapshot_summary,
        display_text: format!(
            "项目主管拆任务：planned {planned_task_count} / authorized {authorized_task_count} / prepared {prepared_dispatch_count} / needs_binding {needs_binding_count} / blocked {blocked_count}；prepared 仍未执行 worker。"
        ),
        warnings: vec!["prepared_dispatch_is_not_worker_execution".to_string()],
    }
}

fn aggregate_project_director_memory_summary(
    value: &Value,
    tasks: &[ProjectDirectorPlannedTask],
) -> TaskPackageMemoryInjectionSummary {
    let mut snapshot_ids = Vec::new();
    let mut included_count = 0;
    let mut excluded_count = 0;
    let mut review_material_count = 0;
    let mut stale = false;
    let mut stale_reasons = Vec::new();
    let mut warnings = Vec::new();
    for task in tasks {
        let Some(work_item_id) = task.work_item_id.as_deref() else {
            continue;
        };
        let Some(artifact) = find_task_package_artifact_by_id(value, work_item_id) else {
            continue;
        };
        let Some(snapshot) = task_memory_injection::snapshot_from_artifact(artifact) else {
            continue;
        };
        snapshot_ids.push(snapshot.snapshot_id);
        included_count += snapshot.included_memories.len();
        excluded_count += snapshot.excluded_items.len();
        review_material_count += snapshot.review_materials.len();
        stale = stale || snapshot.stale;
        stale_reasons.extend(snapshot.stale_reasons);
        warnings.extend(snapshot.warnings);
    }
    if snapshot_ids.is_empty() {
        return task_memory_injection::missing_summary();
    }
    TaskPackageMemoryInjectionSummary {
        snapshot_id: Some(snapshot_ids.join(",")),
        included_count,
        excluded_count,
        review_material_count,
        stale,
        stale_reasons: dedupe_strings(stale_reasons),
        display_text: format!(
            "任务包记忆快照：{} 个 snapshot；使用了 {} 条正式记忆；排除了 {} 条候选 / 观察 / lint 阻断项；{} 条待审查材料。",
            snapshot_ids.len(),
            included_count,
            excluded_count,
            review_material_count
        ),
        warnings: dedupe_strings(warnings),
    }
}

fn prepared_dispatch_read_models_from_plan(
    plan: &ProjectDirectorTaskPlan,
    value: &Value,
) -> Vec<PreparedAutoDispatchReadModel> {
    plan.planned_tasks
        .iter()
        .filter_map(|task| {
            let guard = task.guard_result.clone().or_else(|| {
                Some(AutoDispatchGuardResult {
                    status: "blocked".to_string(),
                    authorization_id: Some(plan.authorization_id.clone()),
                    reasons: task.blocked_reasons.clone(),
                    required_user_confirmation: false,
                    required_global_review: false,
                    checked_at_ms: unix_timestamp_ms(),
                })
            })?;
            let dispatch = task
                .prepared_dispatch_id
                .as_deref()
                .and_then(|dispatch_id| find_workflow_node_dispatch(value, dispatch_id));
            Some(PreparedAutoDispatchReadModel {
                dispatch_id: task.prepared_dispatch_id.clone(),
                planned_task_id: task.planned_task_id.clone(),
                work_item_id: task.work_item_id.clone(),
                workflow_node_id: task.workflow_node_id.clone(),
                task_package_id: task.task_package_id.clone(),
                status: task.status.clone(),
                authorization_check: guard,
                memory_packet_snapshot_id: task.memory_packet_snapshot_id.clone(),
                memory_packet_fingerprint: dispatch.and_then(|dispatch| {
                    optional_string_from(dispatch, "memory_packet_fingerprint")
                }),
                binding_status: if task.status == "prepared" {
                    "active_binding_ready".to_string()
                } else if task.status == "needs_binding" {
                    "needs_binding".to_string()
                } else {
                    "not_ready".to_string()
                },
                prompt_preview: dispatch
                    .and_then(|dispatch| optional_string_from(dispatch, "prompt_preview")),
                blocked_reasons: task.blocked_reasons.clone(),
            })
        })
        .collect()
}

fn c4_static_task_blocking_reasons(task: &ProjectDirectorPlannedTask) -> Vec<String> {
    let mut reasons = Vec::new();
    if task.title.trim().is_empty() {
        reasons.push("planned task 缺少标题。".to_string());
    }
    if task.objective.trim().is_empty() {
        reasons.push("planned task 缺少目标说明。".to_string());
    }
    if task.scope.allowed_read_scope.is_empty() {
        reasons.push("授权读取范围为空，不能生成可派发任务包。".to_string());
    }
    if task.scope.allowed_write_scope.is_empty() {
        reasons.push("授权写入范围为空，不能生成可派发任务包。".to_string());
    }
    if task.acceptance_criteria.is_empty() {
        reasons.push("planned task 缺少验收标准。".to_string());
    }
    if task.report_format.is_empty() {
        reasons.push("planned task 缺少回传格式。".to_string());
    }
    if task
        .scope
        .allowed_read_scope
        .iter()
        .chain(task.scope.allowed_write_scope.iter())
        .any(|scope| scope.contains("/Users/yoyi/.codex"))
    {
        reasons.push("读写范围包含 /Users/yoyi/.codex，C4 已阻断。".to_string());
    }
    reasons
}

fn ensure_c4_backup(
    path: &Path,
    timestamp: &str,
    backup_path: &mut Option<PathBuf>,
) -> Result<(), String> {
    if backup_path.is_none() {
        *backup_path = Some(backup_workflow_state_file(path, timestamp)?);
    }
    Ok(())
}

fn ensure_project_director_worker_node(
    value: &mut Value,
    node_id: &str,
    task: &ProjectDirectorPlannedTask,
    timestamp: &str,
) -> Result<(), String> {
    if node_exists(value, &task.scope.workflow_id, node_id) {
        update_node_state_for_id(value, node_id, "ready_to_dispatch", timestamp)?;
        return Ok(());
    }
    array_mut(value, "nodes")?.push(json!({
      "node_id": node_id,
      "workflow_id": task.scope.workflow_id,
      "node_type": "actor",
      "title": assigned_role_label(&task.scope.target_role),
      "state": "ready_to_dispatch",
      "source_kind": "project_director_task_plan",
      "source_ref": task.planned_task_id,
      "agent_type": if task.scope.target_role.contains("codex") { "codex" } else { "agent" },
      "adapter_id": if task.scope.target_role.contains("codex") { Value::String("codex-local".to_string()) } else { Value::Null },
      "permission_level": "plan_authorized_prepared",
      "position": {
        "x": 560,
        "y": 120
      },
      "warnings": []
    }));
    let edge_id = format!(
        "{}:edge:project-director-task:{}",
        task.scope.workflow_id,
        stable_id(&task.planned_task_id)
    );
    if !edge_exists(value, &edge_id) {
        array_mut(value, "edges")?.push(json!({
          "edge_id": edge_id,
          "workflow_id": task.scope.workflow_id,
          "from_node_id": format!("{}:node:task", task.scope.workflow_id),
          "to_node_id": node_id,
          "edge_type": "assigned_to",
          "state": "ready_to_dispatch",
          "source_kind": "project_director_task_plan",
          "source_ref": task.planned_task_id,
          "permission_level": "plan_authorized_prepared",
          "created_at": timestamp,
          "updated_at": timestamp,
          "warnings": []
        }));
    }
    Ok(())
}

fn ensure_project_director_work_item(
    value: &mut Value,
    work_item_id: &str,
    artifact_id: &str,
    task: &ProjectDirectorPlannedTask,
    timestamp: &str,
) -> Result<(), String> {
    if let Some(index) = find_work_item_index(value, &task.scope.workflow_id, work_item_id) {
        let current_state = optional_string_from(&value["work_items"][index], "state")
            .unwrap_or_else(|| "draft".to_string());
        if matches!(
            current_state.as_str(),
            "running" | "ready_for_review" | "accepted" | "failed" | "timed_out" | "cancelled"
        ) {
            return Err(format!(
                "已存在 work item 且状态为 {current_state}，C4 拒绝覆盖：{work_item_id}"
            ));
        }
        let work_items = array_mut(value, "work_items")?;
        let work_item = work_items
            .get_mut(index)
            .ok_or_else(|| "更新 C4 work item 时索引失效".to_string())?;
        work_item["title"] = Value::String(task.title.clone());
        work_item["state"] = Value::String("ready_to_dispatch".to_string());
        work_item["assigned_role_id"] = Value::String(task.scope.target_role.clone());
        work_item["current_node_id"] =
            Value::String(c4_node_id(&task.scope.workflow_id, &task.scope.target_role));
        work_item["project_director_planned_task_id"] = Value::String(task.planned_task_id.clone());
        work_item["updated_at"] = Value::String(timestamp.to_string());
        return Ok(());
    }
    array_mut(value, "work_items")?.push(json!({
      "work_item_id": work_item_id,
      "project_id": task.scope.project_id,
      "workflow_id": task.scope.workflow_id,
      "title": task.title,
      "state": "ready_to_dispatch",
      "source_kind": "project_director_task_plan",
      "source_ref": artifact_id,
      "assigned_role_id": task.scope.target_role,
      "current_node_id": c4_node_id(&task.scope.workflow_id, &task.scope.target_role),
      "agent_type": if task.scope.target_role.contains("codex") { "codex" } else { "agent" },
      "adapter_id": if task.scope.target_role.contains("codex") { "codex-local" } else { "adapter-pending" },
      "permission_level": "plan_authorized_prepared",
      "project_director_planned_task_id": task.planned_task_id,
      "created_at": timestamp,
      "updated_at": timestamp
    }));
    array_mut(value, "audit_events")?.push(json!({
      "event_id": format!("audit:project-director-task-plan-created:{}:{timestamp}", stable_id(work_item_id)),
      "event_type": "project_director_task_plan_created",
      "target_ref": work_item_id,
      "actor_ref": "project_director",
      "source_kind": "workspace_state",
      "permission_level": "plan_authorized_prepared",
      "before_state": "missing_project_director_task",
      "after_state": "ready_to_dispatch",
      "created_at": timestamp,
      "reason": "项目主管在 C3 active 授权范围内生成 worker 子任务；未启动 worker。"
    }));
    Ok(())
}

fn ensure_project_director_task_package_artifact(
    value: &mut Value,
    project: &ProjectRecord,
    work_item_id: &str,
    artifact_id: &str,
    task: &ProjectDirectorPlannedTask,
    memory_snapshot: &TaskPackageMemoryPacketSnapshot,
    timestamp: &str,
) -> Result<(), String> {
    let artifact_index = value
        .get("artifacts")
        .and_then(Value::as_array)
        .and_then(|artifacts| {
            artifacts.iter().position(|artifact| {
                optional_string_from(artifact, "artifact_id").as_deref() == Some(artifact_id)
            })
        });
    let artifact_value = json!({
      "artifact_id": artifact_id,
      "artifact_type": "task_package",
      "project_id": task.scope.project_id,
      "path": Value::Null,
      "title": task.title,
      "brief": task.objective,
      "source_kind": "project_director_task_plan",
      "source_ref": work_item_id,
      "permission_level": "plan_authorized_prepared",
      "version": 1,
      "stale": false,
      "stale_reasons": [],
      "task_name": task.title,
      "assigned_line": assigned_role_label(&task.scope.target_role),
      "background": [
        format!("来自项目主管 C4 拆任务；项目：{}", project.name),
        "prepared dispatch 只是准备态记录，仍未执行 worker。"
      ],
      "goals": [task.objective],
      "allowed_read": task.scope.allowed_read_scope,
      "allowed_write": task.scope.allowed_write_scope,
      "forbidden_actions": [
        "不读写 `/Users/yoyi/.codex`。",
        "不越过任务包授权范围。",
        "不把 worker 汇报直接写成正式事实或正式记忆。",
        "触发停止条件时先回报项目主管。"
      ],
      "acceptance_criteria": task.acceptance_criteria,
      "required_return": task.report_format,
      "review_focus": [
        "项目主管确认过程事实前，worker 汇报只作为过程材料。",
        "汇报必须带证据、文件变化、风险和下一步建议。"
      ],
      "callable_tool_capabilities": task.scope.callable_tool_capabilities,
      "harness_requirements": task.scope.required_checks,
      "target_role": task.scope.target_role,
      "task_package_kind": task.scope.task_package_kind,
      "model_id": "codex-local-prepared",
      "model_context_policy": "local_only",
      "max_memory_items": 8,
      "max_estimated_tokens": 2000,
      "project_director_planned_task_id": task.planned_task_id,
      "created_at": timestamp,
      "updated_at": timestamp,
      "warnings": ["prepared_dispatch_is_not_worker_execution"]
    });
    let artifacts = array_mut(value, "artifacts")?;
    match artifact_index {
        Some(index) => artifacts[index] = artifact_value,
        None => artifacts.push(artifact_value),
    }
    let artifact = artifacts
        .iter_mut()
        .find(|artifact| {
            optional_string_from(artifact, "artifact_id").as_deref() == Some(artifact_id)
        })
        .ok_or_else(|| "写入 C4 task package artifact 后重新定位失败".to_string())?;
    task_memory_injection::write_snapshot_to_artifact(artifact, memory_snapshot)?;
    Ok(())
}

fn project_director_memory_snapshot(
    path: &Path,
    project_root_value: &str,
    task: &ProjectDirectorPlannedTask,
    work_item_id: &str,
    artifact_id: &str,
    timestamp: &str,
) -> Result<TaskPackageMemoryPacketSnapshot, String> {
    let input = TaskMemoryPacketBuildInput {
        project_root: project_root_value.to_string(),
        project_id: Some(task.scope.project_id.clone()),
        workflow_id: Some(task.scope.workflow_id.clone()),
        task_id: Some(work_item_id.to_string()),
        role_id: task.scope.target_role.clone(),
        task_goal: task.objective.clone(),
        retrieval_intent: "worker_task".to_string(),
        target_model_id: Some("codex-local-prepared".to_string()),
        model_context_policy: "local_only".to_string(),
        max_memory_items: 8,
        max_estimated_tokens: 2000,
        expected_formal_store_revision: None,
        expected_candidate_store_revision: None,
        expected_observation_store_revision: None,
    };
    let output = preview_task_memory_packet_at(path, &input, timestamp)?;
    task_memory_injection::snapshot_from_build_output(
        &output,
        work_item_id,
        Some(artifact_id),
        timestamp,
    )
}

fn active_binding_for_planned_task(
    index: &Value,
    value: &Value,
    node_id: &str,
    work_item_id: &str,
) -> Option<ActiveBindingInfo> {
    let workflow_id = value
        .get("work_items")
        .and_then(Value::as_array)
        .and_then(|work_items| {
            work_items.iter().find(|work_item| {
                optional_string_from(work_item, "work_item_id").as_deref() == Some(work_item_id)
            })
        })
        .and_then(|work_item| optional_string_from(work_item, "workflow_id"))
        .or_else(|| node_id.split(":node:").next().map(str::to_string))?;
    let binding_index =
        workflow_node_session_binding_index(value, &workflow_id, node_id, Some(work_item_id))
            .or_else(|| workflow_node_session_binding_index(value, &workflow_id, node_id, None))?;
    let binding = value
        .get("workflow_node_session_bindings")
        .and_then(Value::as_array)
        .and_then(|bindings| bindings.get(binding_index))?;
    let native_thread_id = optional_string_from(binding, "native_thread_id")?;
    let mut warnings = string_array(binding, "warnings");
    let index_session = find_index_thread(index, &native_thread_id);
    if index_session.is_none() {
        warnings.push("binding_thread_missing_from_index".to_string());
    }
    let rollout_exists = bool_value(binding, "rollout_exists")
        && index_session
            .as_ref()
            .is_none_or(|session| session.rollout_exists);
    Some(ActiveBindingInfo {
        binding_id: optional_string_from(binding, "binding_id")?,
        native_thread_id,
        rollout_exists,
        warnings: dedupe_strings(warnings),
    })
}

fn find_task_package_artifact_by_id<'a>(value: &'a Value, work_item_id: &str) -> Option<&'a Value> {
    value
        .get("artifacts")
        .and_then(Value::as_array)
        .and_then(|artifacts| {
            artifacts.iter().find(|artifact| {
                optional_string_from(artifact, "source_ref").as_deref() == Some(work_item_id)
                    && optional_string_from(artifact, "artifact_type").as_deref()
                        == Some("task_package")
            })
        })
}

fn existing_prepared_dispatch_for_planned_task<'a>(
    value: &'a Value,
    planned_task_id: &str,
    work_item_id: &str,
    authorization_id: &str,
) -> Option<&'a Value> {
    value
        .get("workflow_node_dispatches")
        .and_then(Value::as_array)
        .and_then(|dispatches| {
            dispatches.iter().rev().find(|dispatch| {
                optional_string_from(dispatch, "state").as_deref() == Some("prepared")
                    && optional_string_from(dispatch, "work_item_id").as_deref()
                        == Some(work_item_id)
                    && optional_string_from(dispatch, "plan_authorization_id").as_deref()
                        == Some(authorization_id)
                    && optional_string_from(dispatch, "c4_planned_task_id")
                        .as_deref()
                        .is_none_or(|id| id == planned_task_id)
            })
        })
}

