fn execute_workflow_machine_step(
    path: &Path,
    index: &Value,
    readback_db_path: &Path,
    runner: &dyn CodexResumeRunner,
    request: &WorkflowMachineRunRequest,
    run_id: &str,
    round_no: usize,
    role_id: &str,
    role_label: &str,
    prompt: &str,
) -> Result<WorkflowMachineRunStepRecord, String> {
    let workflow_id = default_workflow_id(&request.project_root);
    let node_id = offline_role_node_id(&workflow_id, role_id)?;
    let instruction = workflow_machine_step_instruction(request, run_id, round_no, role_id, prompt);
    let execute_request = WorkflowNodeDispatchExecuteRequest {
        project_root: request.project_root.clone(),
        node_id: node_id.clone(),
        work_item_id: request.work_item_id.clone(),
        prompt_kind: "user_reviewed_instruction".to_string(),
        user_reviewed_instruction: Some(instruction),
    };
    let dispatch_result =
        execute_workflow_node_dispatch_at(path, index, readback_db_path, runner, &execute_request)?;
    let dispatch = dispatch_result.dispatch;
    let state = if dispatch.state == "completed" {
        "completed".to_string()
    } else {
        dispatch.state.clone()
    };
    reset_work_item_for_next_machine_step(
        path,
        &workflow_id,
        &request.work_item_id,
        if state == "completed" {
            "ready_to_dispatch"
        } else {
            &state
        },
        role_id,
        run_id,
    )?;
    Ok(WorkflowMachineRunStepRecord {
        step_id: dispatch.dispatch_id,
        role_id: role_id.to_string(),
        role_label: role_label.to_string(),
        node_id,
        native_thread_id: dispatch.native_thread_id,
        state,
        exit_code: dispatch.exit_code,
        last_message_summary: dispatch.last_message_summary,
        warnings: dispatch.warnings,
    })
}

fn workflow_machine_step_instruction(
    request: &WorkflowMachineRunRequest,
    run_id: &str,
    round_no: usize,
    role_id: &str,
    prompt: &str,
) -> UserReviewedInstructionInput {
    let project_root = request.project_root.trim().to_string();
    let execution_root = workflow_machine_execution_root(request);
    let allowed_reads = if execution_root == project_root {
        vec![project_root.clone()]
    } else {
        vec![project_root.clone(), execution_root.clone()]
    };
    UserReviewedInstructionInput {
        instruction_id: format!(
            "workflow-machine:{}:round-{}:{}",
            stable_id(run_id),
            round_no,
            stable_id(role_id)
        ),
        summary: format!("工作流机器第 {round_no} 轮：{role_id}"),
        objective: request.objective.trim().to_string(),
        execution_cwd: execution_root.clone(),
        sandbox_mode: if role_id == "codex-dev" {
            "workspace-write".to_string()
        } else {
            "read-only".to_string()
        },
        allowed_write_roots: if role_id == "codex-dev" {
            vec![execution_root.clone()]
        } else {
            vec![]
        },
        allowed_reads,
        allowed_writes: if role_id == "codex-dev" {
            vec![execution_root]
        } else {
            vec![]
        },
        forbidden_actions: vec![
            "不读取 auth.json、.env、密钥、token、授权文件".to_string(),
            "不读取完整 transcript".to_string(),
            "不触碰工作流目录和目标执行目录之外的其他业务项目".to_string(),
            "不删除、移动、归档 Codex 会话".to_string(),
            "不联网安装依赖".to_string(),
        ],
        timeout_seconds: request.timeout_seconds_per_step,
        max_retries: 0,
        required_return: vec![
            "薄弱点".to_string(),
            "本步做了什么".to_string(),
            "改了哪些文件".to_string(),
            "验证结果".to_string(),
            "下一步建议".to_string(),
            "WORKFLOW_MACHINE_STEP_STATUS".to_string(),
        ],
        prompt_preview: Some(prompt.to_string()),
    }
}

fn render_workflow_machine_step_prompt(
    request: &WorkflowMachineRunRequest,
    run_id: &str,
    round_no: usize,
    role_id: &str,
    previous_steps: &[WorkflowMachineRunStepRecord],
) -> String {
    let history = if previous_steps.is_empty() {
        "暂无上一环节结果。".to_string()
    } else {
        previous_steps
            .iter()
            .map(|step| {
                format!(
                    "- {} / {} / {}：{}",
                    step.role_label,
                    step.role_id,
                    step.state,
                    step.last_message_summary.as_deref().unwrap_or("无摘要")
                )
            })
            .collect::<Vec<_>>()
            .join("\n")
    };
    let role_instruction = match role_id {
        "director" if previous_steps.is_empty() => {
            "你是总指导。不要修改文件。只输出极短第一轮安排：开发线做什么、验证线查什么、回收线判断什么。"
        }
        "director" => {
            "你是总指导。请根据开发线、验证线、回收线的结果判断是否进入下一轮。若目标已完成，必须明确给出最终结论。不要修改文件。"
        }
        "codex-dev" => {
            "你是开发线。请只在允许目录内完成总目标要求的实现或修复。优先做最小可验证改动，保留现有功能，不要自行改目标范围。"
        }
        "validation" => {
            "你是验证线。请检查开发结果是否满足总目标、是否有明显退化、是否违反边界。不要修改文件。"
        }
        "review" => {
            "你是回收线。请根据开发线和验证线结果给出是否通过、还缺什么、是否应该回到总指导继续下一轮。不要修改文件。"
        }
        _ => "请按角色完成本轮工作。",
    };
    let status_rule = if role_id == "director" && !previous_steps.is_empty() {
        "如果确认最终目标完成，请在最后单独输出一行：WORKFLOW_MACHINE_FINAL_ACCEPTED；否则输出：WORKFLOW_MACHINE_CONTINUE。"
    } else if role_id == "director" {
        "请控制在 8 行内，并在最后单独输出一行：WORKFLOW_MACHINE_STEP_STATUS: completed。"
    } else {
        "请在最后单独输出一行：WORKFLOW_MACHINE_STEP_STATUS: completed 或 WORKFLOW_MACHINE_STEP_STATUS: needs_changes。"
    };
    let execution_root = workflow_machine_execution_root(request);
    format!(
        "{role_instruction}\n\n总目标：\n{}\n\n工作流目录：\n{}\n\n目标执行目录：\n{}\n\n运行 ID：{run_id}\n轮次：{round_no}\n角色：{role_id}\n\n上一环节摘要：\n{history}\n\n边界：\n- 不读取 auth.json、.env、密钥、token、授权文件。\n- 不读取完整 transcript。\n- 不触碰工作流目录和目标执行目录之外的其他业务项目。\n- 不删除、移动、归档 Codex 会话。\n- 只有开发线允许写目标执行目录；其他角色只读。\n\n{status_rule}",
        request.objective.trim(),
        request.project_root.trim(),
        execution_root
    )
}

fn workflow_machine_execution_root(request: &WorkflowMachineRunRequest) -> String {
    request
        .execution_root
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or_else(|| request.project_root.trim())
        .to_string()
}

fn workflow_machine_final_acceptance(summary: &str) -> bool {
    summary.contains("WORKFLOW_MACHINE_FINAL_ACCEPTED")
        || summary.contains("最终目标完成")
        || summary.contains("最终结论：通过")
        || summary.contains("我的判断：通过")
        || summary.contains("判断：通过")
        || summary.contains("结论：通过")
}

fn reset_work_item_for_next_machine_step(
    path: &Path,
    workflow_id: &str,
    work_item_id: &str,
    next_state: &str,
    role_id: &str,
    run_id: &str,
) -> Result<(), String> {
    let timestamp = unix_timestamp_string();
    let mut value = read_workflow_state_value(path)?;
    let work_item_index = find_work_item_index(&value, workflow_id, work_item_id)
        .ok_or_else(|| "当前 workflow 下找不到该 work item；无法推进工作流机器".to_string())?;
    let before_state = {
        let work_items = array_mut(&mut value, "work_items")?;
        let work_item = work_items
            .get_mut(work_item_index)
            .ok_or_else(|| "当前 workflow 下找不到该 work item；无法推进工作流机器".to_string())?;
        let before_state =
            optional_string_from(work_item, "state").unwrap_or_else(|| "unknown".to_string());
        work_item["state"] = Value::String(next_state.to_string());
        work_item["current_node_id"] = Value::String(format!("{workflow_id}:node:{role_id}"));
        work_item["updated_at"] = Value::String(timestamp.clone());
        before_state
    };
    array_mut(&mut value, "audit_events")?.push(json!({
      "event_id": format!("audit:workflow-machine-step-reset:{}:{timestamp}", stable_id(run_id)),
      "event_type": "workflow_machine_step_ready_for_next_role",
      "target_ref": work_item_id,
      "actor_ref": "desktop_shell_workflow_machine",
      "source_kind": "workspace_state_and_codex_resume",
      "permission_level": "user_confirmed_write",
      "before_state": before_state,
      "after_state": next_state,
      "created_at": timestamp,
      "reason": format!("工作流机器完成 {role_id} 步骤后，为下一角色继续派发重置工作项状态。")
    }));
    value["updated_at"] = Value::String(timestamp);
    write_validated_workflow_state(path, &value)
}

fn append_workflow_machine_run_started(
    path: &Path,
    request: &WorkflowMachineRunRequest,
    run_id: &str,
    timestamp: &str,
) -> Result<(), String> {
    let mut value = read_workflow_state_value(path)?;
    ensure_array_mut(&mut value, "workflow_machine_runs")?.push(json!({
      "run_id": run_id,
      "project_id": project_id(&request.project_root),
      "workflow_id": default_workflow_id(&request.project_root),
      "work_item_id": request.work_item_id,
      "objective": request.objective,
      "state": "running",
      "max_rounds": request.max_rounds,
      "timeout_seconds_per_step": request.timeout_seconds_per_step,
      "started_at": timestamp,
      "ended_at": Value::Null,
      "rounds_completed": 0,
      "steps": [],
      "warnings": []
    }));
    array_mut(&mut value, "audit_events")?.push(json!({
      "event_id": format!("audit:workflow-machine-run-started:{}:{timestamp}", stable_id(run_id)),
      "event_type": "workflow_machine_run_started",
      "target_ref": request.work_item_id,
      "actor_ref": "user_confirmed_desktop_shell",
      "source_kind": "workspace_state_and_codex_resume",
      "permission_level": "user_confirmed_write",
      "before_state": "ready_to_dispatch",
      "after_state": "running",
      "created_at": timestamp,
      "reason": "用户确认启动四角色工作流机器；会按总指导、开发线、验证线、回收线、总指导结论循环调用绑定 Codex 会话。"
    }));
    value["updated_at"] = Value::String(timestamp.to_string());
    write_validated_workflow_state(path, &value)
}

fn append_workflow_machine_run_finished(
    path: &Path,
    request: &WorkflowMachineRunRequest,
    run_id: &str,
    project_id_value: &str,
    workflow_id: &str,
    final_state: &str,
    rounds_completed: usize,
    steps: &[WorkflowMachineRunStepRecord],
) -> Result<(), String> {
    control_core::validate_workflow_machine_final_state(final_state)?;
    let timestamp = unix_timestamp_string();
    let mut value = read_workflow_state_value(path)?;
    if let Some(run) = ensure_array_mut(&mut value, "workflow_machine_runs")?
        .iter_mut()
        .find(|run| optional_string_from(run, "run_id").as_deref() == Some(run_id))
    {
        run["state"] = Value::String(final_state.to_string());
        run["ended_at"] = Value::String(timestamp.clone());
        run["rounds_completed"] = Value::Number((rounds_completed as i64).into());
        run["steps"] = serde_json::to_value(steps)
            .map_err(|error| format!("workflow machine steps 序列化失败：{error}"))?;
    }
    if let Some(work_item) = array_mut(&mut value, "work_items")?
        .iter_mut()
        .find(|item| {
            optional_string_from(item, "workflow_id").as_deref() == Some(workflow_id)
                && optional_string_from(item, "work_item_id").as_deref()
                    == Some(request.work_item_id.as_str())
        })
    {
        work_item["state"] = Value::String(if final_state == "accepted" {
            "accepted".to_string()
        } else if final_state == "failed" {
            "failed".to_string()
        } else {
            "needs_changes".to_string()
        });
        work_item["current_node_id"] = Value::String(format!("{workflow_id}:node:director"));
        work_item["updated_at"] = Value::String(timestamp.clone());
    }
    array_mut(&mut value, "reviews")?.push(json!({
      "review_id": format!("review:{}:{}:workflow-machine:{}", stable_id(workflow_id), stable_id(&request.work_item_id), timestamp),
      "project_id": project_id_value,
      "workflow_id": workflow_id,
      "work_item_id": request.work_item_id,
      "dispatch_id": run_id,
      "reviewer_role": "director",
      "decision": if final_state == "accepted" { "accepted" } else { "needs_changes" },
      "summary": format!("工作流机器收口：state={final_state}, rounds={rounds_completed}, steps={}", steps.len()),
      "evidence_refs": [],
      "handoff_refs": [],
      "created_at": timestamp,
      "updated_at": timestamp,
      "warnings": []
    }));
    let audit_event_id = format!(
        "audit:workflow-machine-run-finished:{}:{timestamp}",
        stable_id(run_id)
    );
    array_mut(&mut value, "audit_events")?.push(json!({
      "event_id": audit_event_id,
      "event_type": "workflow_machine_run_finished",
      "target_ref": request.work_item_id,
      "actor_ref": "desktop_shell_workflow_machine",
      "source_kind": "workspace_state_and_codex_resume",
      "permission_level": "user_confirmed_write",
      "before_state": "running",
      "after_state": final_state,
      "created_at": timestamp,
      "reason": format!("工作流机器结束：state={final_state}, rounds={rounds_completed}, steps={}", steps.len())
    }));
    value["updated_at"] = Value::String(timestamp);
    write_validated_workflow_state(path, &value)
}

fn workflow_machine_result_from_state(
    path: &Path,
    backup_path: Option<PathBuf>,
    run_id: &str,
    final_state: &str,
    rounds_completed: usize,
    steps: Vec<WorkflowMachineRunStepRecord>,
    message: &str,
) -> Result<WorkflowMachineRunResult, String> {
    Ok(WorkflowMachineRunResult {
        message: message.to_string(),
        path: path.display().to_string(),
        backup_path: backup_path.map(|path| path.display().to_string()),
        audit_event_id: format!("audit:workflow-machine-run-finished:{}", stable_id(run_id)),
        product_command_boundary: legacy_product_command_boundary("workflow_machine_run_result"),
        run_id: run_id.to_string(),
        final_state: final_state.to_string(),
        rounds_completed,
        steps,
        snapshot: read_workflow_state_snapshot(path)?,
    })
}

fn find_work_item<'a>(
    value: &'a Value,
    workflow_id: &str,
    work_item_id: &str,
) -> Option<&'a Value> {
    value
        .get("work_items")
        .and_then(Value::as_array)
        .and_then(|items| {
            items.iter().find(|item| {
                optional_string_from(item, "workflow_id").as_deref() == Some(workflow_id)
                    && optional_string_from(item, "work_item_id").as_deref() == Some(work_item_id)
            })
        })
}

fn find_work_item_index(value: &Value, workflow_id: &str, work_item_id: &str) -> Option<usize> {
    value
        .get("work_items")
        .and_then(Value::as_array)
        .and_then(|items| {
            items.iter().position(|item| {
                optional_string_from(item, "workflow_id").as_deref() == Some(workflow_id)
                    && optional_string_from(item, "work_item_id").as_deref() == Some(work_item_id)
            })
        })
}

fn find_permission_request_index(
    value: &Value,
    workflow_id: &str,
    work_item_id: &str,
    request_id: &str,
) -> Option<usize> {
    value
        .get("permission_requests")
        .and_then(Value::as_array)
        .and_then(|requests| {
            requests.iter().position(|request| {
                optional_string_from(request, "workflow_id").as_deref() == Some(workflow_id)
                    && optional_string_from(request, "work_item_id").as_deref()
                        == Some(work_item_id)
                    && optional_string_from(request, "request_id").as_deref() == Some(request_id)
            })
        })
}

fn find_task_package_artifact_index(
    value: &Value,
    work_item_id: &str,
    work_item_index: usize,
) -> Option<usize> {
    let work_item = value
        .get("work_items")
        .and_then(Value::as_array)
        .and_then(|items| items.get(work_item_index))?;
    let source_artifact_id = optional_string_from(work_item, "source_ref");
    value
        .get("artifacts")
        .and_then(Value::as_array)
        .and_then(|artifacts| {
            artifacts.iter().position(|artifact| {
                optional_string_from(artifact, "artifact_type").as_deref() == Some("task_package")
                    && (optional_string_from(artifact, "source_ref").as_deref()
                        == Some(work_item_id)
                        || source_artifact_id.as_deref().is_some_and(|id| {
                            optional_string_from(artifact, "artifact_id").as_deref() == Some(id)
                        }))
            })
        })
}

fn find_task_package_artifact<'a>(
    value: &'a Value,
    work_item_id: &str,
    work_item: &Value,
) -> Option<&'a Value> {
    let source_artifact_id = optional_string_from(work_item, "source_ref");
    value
        .get("artifacts")
        .and_then(Value::as_array)
        .and_then(|artifacts| {
            artifacts.iter().find(|artifact| {
                optional_string_from(artifact, "artifact_type").as_deref() == Some("task_package")
                    && (optional_string_from(artifact, "source_ref").as_deref()
                        == Some(work_item_id)
                        || source_artifact_id.as_deref().is_some_and(|id| {
                            optional_string_from(artifact, "artifact_id").as_deref() == Some(id)
                        }))
            })
        })
}

struct RenderTaskPackageFields {
    task_name: String,
    assigned_line: String,
    background: Vec<String>,
    goals: Vec<String>,
    allowed_read: Vec<String>,
    allowed_write: Vec<String>,
    forbidden_actions: Vec<String>,
    acceptance_criteria: Vec<String>,
    required_return: Vec<String>,
    review_focus: Vec<String>,
    project_name: String,
    project_root: String,
    workflow_id: String,
    work_item_id: String,
}

fn task_package_fields_from(
    work_item: &Value,
    artifact: &Value,
    project: &ProjectRecord,
    workflow_id: &str,
    work_item_id: &str,
) -> RenderTaskPackageFields {
    RenderTaskPackageFields {
        task_name: present_or_placeholder(
            optional_string_from(artifact, "task_name")
                .or_else(|| optional_string_from(work_item, "title")),
        ),
        assigned_line: optional_string_from(artifact, "assigned_line")
            .filter(|value| !value.trim().is_empty())
            .or_else(|| {
                optional_string_from(work_item, "assigned_role_id")
                    .map(|role| assigned_role_label(&role).to_string())
            })
            .unwrap_or_else(|| "未登记".to_string()),
        background: string_array_or_placeholder(
            artifact,
            "background",
            vec!["业务背景：待补充。".to_string()],
        ),
        goals: string_array_or_placeholder(
            artifact,
            "goals",
            vec![present_or_placeholder(optional_string_from(
                artifact, "brief",
            ))],
        ),
        allowed_read: string_array_or_placeholder(
            artifact,
            "allowed_read",
            vec![
                format!("`{}`", project.project_root),
                "待补充：草稿未登记更多允许读取清单。".to_string(),
            ],
        ),
        allowed_write: string_array_or_placeholder(
            artifact,
            "allowed_write",
            vec!["待补充：草稿未登记允许写入清单。".to_string()],
        ),
        forbidden_actions: string_array_or_placeholder(
            artifact,
            "forbidden_actions",
            vec![
                "不写 `/Users/yoyi/.codex`。".to_string(),
                "不改真实 Codex 状态库。".to_string(),
                "不生成真实 `product-line/tasks/*.md` 任务包文件，除非后续任务明确要求并再次确认。"
                    .to_string(),
                "不自动派发真实 Codex 会话。".to_string(),
                "不启动 Codex CLI。".to_string(),
                "不自动运行 harness。".to_string(),
                "待补充：草稿未登记更多禁止事项。".to_string(),
            ],
        ),
        acceptance_criteria: string_array_or_placeholder(
            artifact,
            "acceptance_criteria",
            vec!["待补充：草稿未登记验收标准。".to_string()],
        ),
        required_return: string_array_or_placeholder(
            artifact,
            "required_return",
            vec![
                "做了什么".to_string(),
                "改了哪些文件".to_string(),
                "新增了哪些测试或证据".to_string(),
                "哪些结论有依据".to_string(),
                "哪些仍不确定".to_string(),
                "风险和下一步建议".to_string(),
            ],
        ),
        review_focus: string_array_or_placeholder(
            artifact,
            "review_focus",
            vec![
                "判断是否接受、需要修改、暂停或废弃。".to_string(),
                "说明判断依据。".to_string(),
                "待补充：草稿未登记更具体的回收重点。".to_string(),
            ],
        ),
        project_name: project.name.clone(),
        project_root: project.project_root.clone(),
        workflow_id: workflow_id.to_string(),
        work_item_id: work_item_id.to_string(),
    }
}

fn present_or_placeholder(value: Option<String>) -> String {
    value
        .map(|raw| raw.trim().to_string())
        .filter(|raw| !raw.is_empty())
        .unwrap_or_else(|| "待补充".to_string())
}

fn task_memory_packet_input_from_task_package(
    project_root_value: &str,
    workflow_id: &str,
    work_item_id: &str,
    work_item: &Value,
    artifact: &Value,
    fields: &RenderTaskPackageFields,
) -> TaskMemoryPacketBuildInput {
    let joined_goals = fields
        .goals
        .iter()
        .map(|goal| goal.trim())
        .filter(|goal| !goal.is_empty())
        .collect::<Vec<_>>()
        .join("\n");
    let task_goal = if joined_goals.trim().is_empty() {
        fields.task_name.clone()
    } else {
        joined_goals
    };
    let role_id = optional_string_from(work_item, "assigned_role_id")
        .or_else(|| optional_string_from(artifact, "target_role"))
        .unwrap_or_else(|| assigned_line_id(&fields.assigned_line).to_string());
    let model_context_policy = optional_string_from(artifact, "model_context_policy")
        .filter(|policy| !policy.trim().is_empty())
        .unwrap_or_else(|| "local_only".to_string());

    TaskMemoryPacketBuildInput {
        project_root: project_root_value.to_string(),
        project_id: Some(project_id(project_root_value)),
        workflow_id: Some(workflow_id.to_string()),
        task_id: Some(work_item_id.to_string()),
        role_id,
        task_goal,
        retrieval_intent: "worker_task".to_string(),
        target_model_id: optional_string_from(artifact, "model_id"),
        model_context_policy,
        max_memory_items: i64_value(artifact, "max_memory_items").unwrap_or(8).max(1) as usize,
        max_estimated_tokens: i64_value(artifact, "max_estimated_tokens")
            .unwrap_or(2000)
            .max(128) as usize,
        expected_formal_store_revision: None,
        expected_candidate_store_revision: None,
        expected_observation_store_revision: None,
    }
}

fn string_array_or_placeholder(value: &Value, key: &str, fallback: Vec<String>) -> Vec<String> {
    let values = string_array(value, key)
        .into_iter()
        .map(|line| line.trim().to_string())
        .filter(|line| !line.is_empty())
        .collect::<Vec<_>>();
    if values.is_empty() {
        fallback
    } else {
        values
    }
}

fn string_vec_value(items: &[String]) -> Value {
    Value::Array(
        items
            .iter()
            .map(|item| item.trim())
            .filter(|item| !item.is_empty())
            .map(|item| Value::String(item.to_string()))
            .collect(),
    )
}

fn cleaned_scalar(value: &str) -> String {
    value.trim().to_string()
}

fn join_lines(items: &[String]) -> String {
    items
        .iter()
        .map(|item| item.trim())
        .filter(|item| !item.is_empty())
        .collect::<Vec<_>>()
        .join("\n")
}

fn assigned_line_id(value: &str) -> &str {
    match value.trim() {
        "Codex 开发线" | "codex-dev" => "codex-dev",
        "桌面应用线" | "desktop-app" => "desktop-app",
        "" => "未登记",
        other => other,
    }
}

fn field_warning_strings(fields: &TaskPackageFieldsInput) -> Vec<String> {
    let mut warnings = Vec::new();
    if cleaned_scalar(&fields.task_name).is_empty() {
        warnings.push("missing_task_name".to_string());
    }
    if cleaned_scalar(&fields.assigned_line).is_empty() {
        warnings.push("missing_assigned_line".to_string());
    }
    if join_lines(&fields.background).is_empty() {
        warnings.push("missing_background".to_string());
    }
    if join_lines(&fields.goals).is_empty() {
        warnings.push("missing_goals".to_string());
    }
    if join_lines(&fields.allowed_read).is_empty() {
        warnings.push("missing_allowed_read".to_string());
    }
    if join_lines(&fields.allowed_write).is_empty() {
        warnings.push("missing_allowed_write".to_string());
    }
    if join_lines(&fields.forbidden_actions).is_empty() {
        warnings.push("missing_forbidden_actions".to_string());
    }
    if join_lines(&fields.acceptance_criteria).is_empty() {
        warnings.push("missing_acceptance_criteria".to_string());
    }
    if join_lines(&fields.required_return).is_empty() {
        warnings.push("missing_required_return".to_string());
    }
    if join_lines(&fields.review_focus).is_empty() {
        warnings.push("missing_review_focus".to_string());
    }
    warnings
}

fn assigned_role_label(role: &str) -> &str {
    match role {
        "codex-dev" => "Codex 开发线",
        "desktop-app" => "桌面应用线",
        _ => role,
    }
}

fn preview_warnings(work_item: &Value, artifact: &Value) -> Vec<String> {
    let mut warnings = Vec::new();
    if present_or_placeholder(optional_string_from(work_item, "title")) == "待补充" {
        warnings.push("任务名未登记，预览使用待补充。".to_string());
    }
    if optional_string_from(work_item, "assigned_role_id").is_none() {
        warnings.push("所属开发线未登记，预览使用未登记。".to_string());
    }
    if present_or_placeholder(optional_string_from(artifact, "brief")) == "待补充" {
        warnings.push("目标说明未登记，预览使用待补充。".to_string());
    }
    warnings.extend(string_array(artifact, "warnings"));
    warnings
}

fn dispatch_blocking_reasons(
    fields: &RenderTaskPackageFields,
    artifact_path: Option<&str>,
) -> Vec<String> {
    let mut reasons = Vec::new();
    if artifact_path.is_none_or(|path| path.trim().is_empty()) {
        reasons.push("尚未生成真实任务包文件。".to_string());
    }
    if looks_missing(&fields.task_name) || looks_test_draft(&fields.task_name) {
        reasons.push("任务名为空、待补充或仍像测试草稿。".to_string());
    }
    if list_missing_or_dirty(&fields.goals) {
        reasons.push("目标为空、待补充或含输入法污染。".to_string());
    }
    if list_missing_or_dirty(&fields.allowed_read) {
        reasons.push("允许读取为空、待补充或含输入法污染。".to_string());
    }
    if list_missing_or_dirty(&fields.allowed_write) {
        reasons.push("允许写入为空、待补充或含输入法污染。".to_string());
    }
    if list_missing_or_dirty(&fields.acceptance_criteria) {
        reasons.push("验收标准为空、待补充或含输入法污染。".to_string());
    }
    if fields
        .forbidden_actions
        .iter()
        .any(|line| contains_conflicting_generation_ban(line))
    {
        reasons.push("禁止事项仍包含和当前生成行为冲突的历史禁令。".to_string());
    }
    if fields
        .allowed_write
        .iter()
        .any(|line| line.contains("/Users/yoyi/.codex"))
    {
        reasons.push("允许写入包含 /Users/yoyi/.codex，违反本轮边界。".to_string());
    }
    let required_return = fields
        .required_return
        .iter()
        .map(|line| line.trim())
        .collect::<Vec<_>>();
    for required in ["做了什么", "改了哪些文件", "验证命令和结果", "风险"] {
        if !required_return.iter().any(|line| line.contains(required)) {
            reasons.push(format!("必须回传缺少标准字段：{required}。"));
        }
    }
    reasons
}

fn dispatch_warning_reasons(artifact: &Value, artifact_path: Option<&str>) -> Vec<String> {
    let mut warnings = string_array(artifact, "warnings")
        .into_iter()
        .map(|warning| format!("artifact warning: {warning}"))
        .collect::<Vec<_>>();
    if bool_value(artifact, "stale") {
        warnings.push("任务包已标记 stale；需要重新检查并生成新版本。".to_string());
    }
    warnings.extend(
        string_array(artifact, "stale_reasons")
            .into_iter()
            .map(|reason| format!("stale: {reason}")),
    );
    if let Some(path) = artifact_path {
        if !Path::new(path).exists() {
            warnings.push("artifact path 指向的文件当前不存在。".to_string());
        }
    }
    warnings
}

fn list_missing_or_dirty(values: &[String]) -> bool {
    values.is_empty()
        || values
            .iter()
            .any(|value| looks_missing(value) || contains_input_method_noise(value))
}

fn looks_missing(value: &str) -> bool {
    let cleaned = value.trim();
    cleaned.is_empty()
        || cleaned.contains("待补充")
        || cleaned.contains("未登记")
        || cleaned.contains("草稿未登记")
}

fn looks_test_draft(value: &str) -> bool {
    let cleaned = value.trim().to_ascii_lowercase();
    cleaned.contains("task draft")
        || cleaned.contains("smoke")
        || cleaned.contains("test")
        || value.contains("测试草稿")
}

fn contains_input_method_noise(value: &str) -> bool {
    value.contains("他日") || value.contains("输入法污染")
}

fn contains_conflicting_generation_ban(value: &str) -> bool {
    let cleaned = value.trim();
    cleaned.contains("不生成真实 `product-line/tasks/*.md`")
        || cleaned.contains("不生成真实 product-line/tasks/*.md")
        || cleaned.contains("不生成真实任务文件")
        || cleaned.contains("不生成真实任务包文件")
}

fn render_task_package_markdown(
    fields: &RenderTaskPackageFields,
    artifact_id: Option<&str>,
    memory_snapshot: Option<&TaskPackageMemoryPacketSnapshot>,
) -> String {
    let artifact_ref = artifact_id.unwrap_or("未登记");
    let memory_context = memory_snapshot
        .map(task_memory_injection::render_markdown_block)
        .unwrap_or_default();
    format!(
        r#"# 任务包：{task_name}

## 任务名

{task_name}

## 所属开发线

{assigned_line}

## 背景

- 预览依据：工作台状态文件中的 `work_items[]` 和 `artifacts[]` 草稿记录。
- 项目来源：索引内项目 `{project_name}`。
- 项目根目录：`{project_root}`。
- workflow：`{workflow_id}`。
- work item：`{work_item_id}`。
- artifact：`{artifact_ref}`。
{background}

## 目标

{goals}

{memory_context}

## 允许读取

{allowed_read}

## 允许写入

{allowed_write}

## 禁止事项

{forbidden_actions}

## 验收标准

{acceptance_criteria}

## 必须回传

{required_return}

## 总指导回收重点

{review_focus}
"#,
        task_name = fields.task_name,
        assigned_line = fields.assigned_line,
        background = bullet_lines(&fields.background),
        goals = bullet_lines(&fields.goals),
        memory_context = memory_context,
        allowed_read = bullet_lines(&fields.allowed_read),
        allowed_write = bullet_lines(&fields.allowed_write),
        forbidden_actions = bullet_lines(&fields.forbidden_actions),
        acceptance_criteria = bullet_lines(&fields.acceptance_criteria),
        required_return = numbered_lines(&fields.required_return),
        review_focus = bullet_lines(&fields.review_focus),
        project_name = fields.project_name,
        project_root = fields.project_root,
        workflow_id = fields.workflow_id,
        work_item_id = fields.work_item_id,
        artifact_ref = artifact_ref
    )
}

fn task_package_fingerprint(fields: &RenderTaskPackageFields) -> String {
    stable_id(&format!(
        "{}|{}|{}|{}|{}|{}|{}|{}|{}",
        fields.task_name,
        fields.assigned_line,
        fields.background.join("\n"),
        fields.goals.join("\n"),
        fields.allowed_read.join("\n"),
        fields.allowed_write.join("\n"),
        fields.forbidden_actions.join("\n"),
        fields.acceptance_criteria.join("\n"),
        fields.required_return.join("\n")
    ))
}

fn bullet_lines(items: &[String]) -> String {
    items
        .iter()
        .map(|item| format!("- {item}"))
        .collect::<Vec<_>>()
        .join("\n")
}

fn numbered_lines(items: &[String]) -> String {
    items
        .iter()
        .enumerate()
        .map(|(index, item)| format!("{}. {item}", index + 1))
        .collect::<Vec<_>>()
        .join("\n")
}

fn markdown_list_or_empty(items: &[String]) -> String {
    if items.is_empty() {
        "- 待补充".to_string()
    } else {
        items
            .iter()
            .map(|item| format!("- {item}"))
            .collect::<Vec<_>>()
            .join("\n")
    }
}

fn render_user_reviewed_instruction_preview(
    summary: &str,
    objective: &str,
    execution_cwd: &str,
    sandbox_mode: &str,
    allowed_write_roots: &[String],
    allowed_reads: &[String],
    allowed_writes: &[String],
    forbidden_actions: &[String],
    required_return: &[String],
) -> String {
    format!(
        "# 用户审核业务指令预览\n\n## 摘要\n{}\n\n## 目标\n{}\n\n## 执行目录\n{}\n\n## 沙箱模式\n{}\n\n## 允许写入根目录\n{}\n\n## 允许读取\n{}\n\n## 允许写入\n{}\n\n## 禁止事项\n{}\n\n## 必须回传\n{}",
        summary,
        objective,
        execution_cwd,
        sandbox_mode,
        markdown_list_or_empty(allowed_write_roots),
        markdown_list_or_empty(allowed_reads),
        markdown_list_or_empty(allowed_writes),
        markdown_list_or_empty(forbidden_actions),
        markdown_list_or_empty(required_return)
    )
}

