fn session_operation_descriptor_for_adapter(
    adapter: &AgentAdapterDescriptor,
    spec: &SessionOperationSpec,
) -> SessionOperationDescriptor {
    let is_codex = adapter.adapter_id == "codex-local";
    let planned_adapter =
        adapter.status == "planned" || adapter.execution_status == "not_implemented";
    let current_status = if is_codex {
        spec.codex_status
    } else if spec.codex_status == "blocked_destructive" {
        "blocked_destructive"
    } else if matches!(spec.operation_id, "export" | "favorite") {
        "planned"
    } else {
        "blocked"
    };
    let mut warnings = vec![
        "session_operation_boundary_read_model_only".to_string(),
        "no_session_operation_execution_in_e2".to_string(),
        "no_codex_home_write_in_e2".to_string(),
    ];
    warnings.extend(spec.warnings.iter().map(|warning| (*warning).to_string()));
    if planned_adapter {
        warnings.push("planned_adapter_operation_not_available".to_string());
    }

    let unavailable_reason = if planned_adapter {
        format!(
            "{}；{} 仍只是 planned descriptor，没有真实命令、会话、凭据或模型访问。",
            spec.unavailable_reason, adapter.display_name
        )
    } else {
        spec.unavailable_reason.to_string()
    };
    let future_task_hint = if planned_adapter {
        format!(
            "{}；必须先完成 {} adapter 真实接入设计和凭据 / 模型只读边界确认。",
            spec.future_task_hint, adapter.display_name
        )
    } else {
        spec.future_task_hint.to_string()
    };

    SessionOperationDescriptor {
        operation_id: spec.operation_id.to_string(),
        label: spec.label.to_string(),
        category: spec.category.to_string(),
        current_status: current_status.to_string(),
        risk_level: spec.risk_level.to_string(),
        adapter_id: adapter.adapter_id.clone(),
        agent_type: adapter.agent_type.clone(),
        applies_to_session_state: if planned_adapter {
            "planned_adapter_without_session_source".to_string()
        } else {
            spec.applies_to_session_state.to_string()
        },
        requires_user_confirmation: spec.requires_user_confirmation,
        writes_codex_home: spec.writes_codex_home,
        writes_workbench_state: spec.writes_workbench_state,
        writes_project_files: spec.writes_project_files,
        reads_full_transcript: spec.reads_full_transcript,
        requires_credential: planned_adapter && spec.operation_id != "favorite",
        requires_model_access: spec.requires_model_access || planned_adapter,
        requires_runtime_handle: spec.requires_runtime_handle,
        audit_requirement: spec.audit_requirement.to_string(),
        unavailable_reason,
        future_task_hint,
        warnings,
    }
}

fn software_key_of_session(session: &SessionRecord) -> String {
    let key = session
        .thread_source
        .as_deref()
        .unwrap_or("codex")
        .trim()
        .to_ascii_lowercase();
    if key.is_empty() {
        "codex".to_string()
    } else {
        key
    }
}

fn load_sessions(index: &Value, mode: SessionSourceMode) -> (Vec<SessionRecord>, Vec<String>) {
    match mode {
        SessionSourceMode::RealWithSqliteFallback => load_sessions_from_sqlite_or_index(index),
        SessionSourceMode::IndexOnly => (parse_sessions(index), Vec::new()),
    }
}

fn load_sessions_from_sqlite_or_index(index: &Value) -> (Vec<SessionRecord>, Vec<String>) {
    let db_path = codex_db::default_state_db_path();
    match codex_db::read_threads(&db_path) {
        Ok(rows) => {
            let sessions = rows
                .into_iter()
                .map(|r| SessionRecord {
                    thread_id: r.thread_id,
                    title: r.title,
                    project_root: r.project_root,
                    updated_at_ms: r.updated_at_ms,
                    archived: r.archived,
                    rollout_exists: r.rollout_exists,
                    rollout_path: r.rollout_path,
                    model: r.model,
                    reasoning_effort: r.reasoning_effort,
                    thread_source: r.thread_source,
                    warnings: r.warnings,
                })
                .collect();
            (sessions, Vec::new())
        }
        Err(err) => (
            parse_sessions(index),
            vec![format!("codex sqlite 读取失败，回落到旧索引：{err}")],
        ),
    }
}

fn overlay_project_thread_counts(projects: &mut Vec<ProjectRecord>, sessions: &[SessionRecord]) {
    use std::collections::HashMap;
    struct Acc {
        total: usize,
        active: usize,
        archived: usize,
        latest: Option<i64>,
    }
    let mut by_root: HashMap<String, Acc> = HashMap::new();
    for s in sessions {
        let Some(root) = s.project_root.as_ref() else {
            continue;
        };
        let entry = by_root.entry(root.clone()).or_insert(Acc {
            total: 0,
            active: 0,
            archived: 0,
            latest: None,
        });
        entry.total += 1;
        if s.archived {
            entry.archived += 1;
        } else {
            entry.active += 1;
        }
        if let Some(ms) = s.updated_at_ms {
            entry.latest = Some(entry.latest.map_or(ms, |c| c.max(ms)));
        }
    }
    for project in projects.iter_mut() {
        if let Some(acc) = by_root.get(&project.project_root) {
            project.thread_count = acc.total;
            project.active_thread_count = acc.active;
            project.archived_thread_count = acc.archived;
            project.latest_updated_at_ms = acc.latest;
        }
    }
}

